insert into play_questions (id, pillar, tags, tier, type, content, reel_id, chapter_slug, status, source) values
  ('budget-needs-vs-wants-001','budget', array['needs-vs-wants','pocket-money'], 'bronze','mcq', '{"en":{"prompt":"In \"Peter Learns Needs vs Wants\", what simple test does Stewie give to tell a need from a want?","options":["Is it cheaper than ₹500?","Can I get through the month without it?","Do all my friends already have it?","Will I enjoy it today?"],"answer":"B","explanation":"A need is something you can''t get through the month without. A want is just nice to have."},"hi":{"prompt":"\"Peter Learns Needs vs Wants\" में, ज़रूरत और चाहत में फ़र्क पहचानने के लिए स्टूवी कौन-सा आसान टेस्ट बताता है?","options":["क्या यह ₹500 से सस्ता है?","क्या मैं इसके बिना महीना निकाल सकता हूँ?","क्या मेरे सभी दोस्तों के पास यह पहले से है?","क्या आज मुझे इसमें मज़ा आएगा?"],"answer":"B","explanation":"ज़रूरत वह है जिसके बिना महीना नहीं निकल सकता। चाहत वह है जो बस हो तो अच्छा है।"},"te":{"prompt":"\"Peter Learns Needs vs Wants\"లో, అవసరం ఏదో, కోరిక ఏదో తెలుసుకోవడానికి స్టూవీ ఏ సులభమైన టెస్ట్ చెబుతాడు?","options":["ఇది ₹500 కంటే తక్కువ ధరా?","ఇది లేకుండా నేను నెల గడపగలనా?","నా ఫ్రెండ్స్ అందరి దగ్గర ఇది ఇప్పటికే ఉందా?","ఈరోజు దీన్ని నేను ఎంజాయ్ చేస్తానా?"],"answer":"B","explanation":"అవసరం అంటే అది లేకుండా నెల గడవనిది. కోరిక అంటే ఉంటే బాగుంటుంది, అంతే."}}'::jsonb, 'budget-needs-vs-wants',null,'live','ai'),
  ('budget-50-30-20-001','budget', array['50-30-20','pocket-money'], 'bronze','mcq', '{"en":{"prompt":"In the reel, Stewie splits ₹2,000 of monthly money using the 50-30-20 rule. What is the split?","options":["₹1,000 wants, ₹600 needs, ₹400 savings","₹700 needs, ₹600 wants, ₹700 savings","₹1,000 needs, ₹600 wants, ₹400 savings","₹600 needs, ₹400 wants, ₹1,000 savings"],"answer":"C","explanation":"50% of ₹2,000 is ₹1,000 for needs, 30% is ₹600 for wants and 20% is ₹400 for savings."},"hi":{"prompt":"रील में स्टूवी 50-30-20 नियम से महीने के ₹2,000 बाँटता है। बँटवारा क्या है?","options":["₹1,000 चाहतें, ₹600 ज़रूरतें, ₹400 बचत","₹700 ज़रूरतें, ₹600 चाहतें, ₹700 बचत","₹1,000 ज़रूरतें, ₹600 चाहतें, ₹400 बचत","₹600 ज़रूरतें, ₹400 चाहतें, ₹1,000 बचत"],"answer":"C","explanation":"₹2,000 का 50% यानी ₹1,000 ज़रूरतों के लिए, 30% यानी ₹600 चाहतों के लिए और 20% यानी ₹400 बचत के लिए।"},"te":{"prompt":"రీల్‌లో స్టూవీ 50-30-20 రూల్ ప్రకారం నెలకు వచ్చే ₹2,000ను పంచుతాడు. ఆ పంపకం ఏమిటి?","options":["₹1,000 కోరికలు, ₹600 అవసరాలు, ₹400 పొదుపు","₹700 అవసరాలు, ₹600 కోరికలు, ₹700 పొదుపు","₹1,000 అవసరాలు, ₹600 కోరికలు, ₹400 పొదుపు","₹600 అవసరాలు, ₹400 కోరికలు, ₹1,000 పొదుపు"],"answer":"C","explanation":"₹2,000లో 50% అంటే ₹1,000 అవసరాలకు, 30% అంటే ₹600 కోరికలకు, 20% అంటే ₹400 పొదుపుకు."}}'::jsonb, 'budget-50-30-20',null,'live','ai'),
  ('budget-tracking-spending-001','budget', array['tracking-spending'], 'bronze','mcq', '{"en":{"prompt":"In \"Peter''s Chai Math\", Stewie says spending ₹20 a day on chai adds up to how much in a month?","options":["₹200","₹2,000","₹7,300","₹600"],"answer":"D","explanation":"₹20 a day for 30 days is ₹600 a month. ₹7,300 is what it adds up to in a whole year."},"hi":{"prompt":"\"Peter''s Chai Math\" में स्टूवी कहता है कि रोज़ चाय पर ₹20 खर्च करना एक महीने में कितना हो जाता है?","options":["₹200","₹2,000","₹7,300","₹600"],"answer":"D","explanation":"30 दिन तक रोज़ ₹20 यानी महीने में ₹600। ₹7,300 तो पूरे साल का जोड़ है।"},"te":{"prompt":"\"Peter''s Chai Math\"లో, రోజూ టీ మీద ₹20 ఖర్చు చేస్తే నెలకు ఎంత అవుతుందని స్టూవీ చెబుతాడు?","options":["₹200","₹2,000","₹7,300","₹600"],"answer":"D","explanation":"రోజుకు ₹20 చొప్పున 30 రోజులకు నెలకు ₹600. ₹7,300 అనేది ఏడాది మొత్తానికి అయ్యే ఖర్చు."}}'::jsonb, 'budget-chai-math',null,'live','ai'),
  ('budget-needs-vs-wants-002','budget', array['needs-vs-wants'], 'bronze','mcq', '{"en":{"prompt":"Which of these is a need for a student who takes the bus to school?","options":["Monthly bus pass","New wireless earphones","A skin for an online game","Biryani with friends every Friday"],"answer":"A","explanation":"Without the bus pass the student can''t get to school. The others are nice to have but not needed to get through the month."},"hi":{"prompt":"स्कूल बस से जाने वाले स्टूडेंट के लिए इनमें से कौन-सी चीज़ ज़रूरत है?","options":["महीने का बस पास","नए वायरलेस ईयरफ़ोन","ऑनलाइन गेम की एक स्किन","हर शुक्रवार दोस्तों के साथ बिरयानी"],"answer":"A","explanation":"बस पास के बिना स्टूडेंट स्कूल नहीं पहुँच सकता। बाकी चीज़ें हों तो अच्छा है, पर महीना निकालने के लिए ज़रूरी नहीं।"},"te":{"prompt":"బస్సులో స్కూల్‌కి వెళ్లే స్టూడెంట్‌కి వీటిలో ఏది అవసరం?","options":["నెలవారీ బస్ పాస్","కొత్త వైర్‌లెస్ ఇయర్‌ఫోన్స్","ఆన్‌లైన్ గేమ్‌లో ఒక స్కిన్","ప్రతి శుక్రవారం ఫ్రెండ్స్‌తో బిర్యానీ"],"answer":"A","explanation":"బస్ పాస్ లేకపోతే స్టూడెంట్ స్కూల్‌కి వెళ్లలేరు. మిగతావి ఉంటే బాగుంటాయి, కానీ నెల గడవడానికి అవసరం లేదు."}}'::jsonb, null,'budget-needs-vs-wants','live','ai'),
  ('budget-needs-vs-wants-003','budget', array['needs-vs-wants'], 'bronze','mcq', '{"en":{"prompt":"Kavya''s phone works fine, but a new model has just launched. For Kavya, buying the new phone is:","options":["A need, because everyone uses phones","A need, because newer is always better","An emergency expense","A want, because her phone already works"],"answer":"D","explanation":"Her current phone already does the job, so the new one is nice to have, not something she can''t do without."},"hi":{"prompt":"काव्या का फ़ोन ठीक चल रहा है, पर अभी-अभी नया मॉडल लॉन्च हुआ है। काव्या के लिए नया फ़ोन खरीदना:","options":["ज़रूरत है, क्योंकि सब फ़ोन इस्तेमाल करते हैं","ज़रूरत है, क्योंकि नया हमेशा बेहतर होता है","एक इमरजेंसी खर्च है","चाहत है, क्योंकि उसका फ़ोन पहले से चल रहा है"],"answer":"D","explanation":"उसका अभी का फ़ोन काम कर रहा है, इसलिए नया फ़ोन हो तो अच्छा है, पर उसके बिना उसका काम नहीं रुकेगा।"},"te":{"prompt":"కావ్య ఫోన్ బాగానే పనిచేస్తోంది, కానీ కొత్త మోడల్ ఇప్పుడే లాంచ్ అయింది. కావ్యకు కొత్త ఫోన్ కొనడం:","options":["అవసరం, ఎందుకంటే అందరూ ఫోన్లు వాడతారు","అవసరం, ఎందుకంటే కొత్తది ఎప్పుడూ మంచిదే","ఒక ఎమర్జెన్సీ ఖర్చు","కోరిక, ఎందుకంటే తన ఫోన్ ఇప్పటికే పనిచేస్తోంది"],"answer":"D","explanation":"ఇప్పుడున్న ఫోన్‌తోనే పని జరుగుతోంది, కాబట్టి కొత్తది ఉంటే బాగుంటుంది, కానీ అది లేకుండా గడవదు అని కాదు."}}'::jsonb, null,'budget-needs-vs-wants','live','ai'),
  ('budget-needs-vs-wants-004','budget', array['needs-vs-wants'], 'bronze','mcq', '{"en":{"prompt":"Food is a need. Which of these food spends is a want?","options":["Rice and dal at home","A lunch tiffin for school","Pizza with friends every weekend","Milk for the family"],"answer":"C","explanation":"Eating is a need, but eating out with friends every weekend is extra. You can get through the month without it."},"hi":{"prompt":"खाना ज़रूरत है। इनमें से खाने पर कौन-सा खर्च चाहत है?","options":["घर पर दाल-चावल","स्कूल के लिए लंच टिफ़िन","हर वीकेंड दोस्तों के साथ पिज़्ज़ा","परिवार के लिए दूध"],"answer":"C","explanation":"खाना ज़रूरत है, पर हर वीकेंड दोस्तों के साथ बाहर खाना एक्स्ट्रा है। इसके बिना भी महीना निकल सकता है।"},"te":{"prompt":"ఆహారం అవసరం. వీటిలో ఆహారం మీద చేసే ఏ ఖర్చు కోరిక?","options":["ఇంట్లో అన్నం, పప్పు","స్కూల్‌కి లంచ్ టిఫిన్","ప్రతి వీకెండ్ ఫ్రెండ్స్‌తో పిజ్జా","కుటుంబానికి పాలు"],"answer":"C","explanation":"తినడం అవసరమే, కానీ ప్రతి వీకెండ్ ఫ్రెండ్స్‌తో బయట తినడం అదనం. అది లేకుండా కూడా నెల గడుస్తుంది."}}'::jsonb, null,'budget-needs-vs-wants','live','ai'),
  ('budget-needs-vs-wants-005','budget', array['needs-vs-wants','pocket-money'], 'bronze','mcq', '{"en":{"prompt":"Arjun has just got his monthly pocket money. In what order should he spend it?","options":["Wants first, then needs with the rest","Needs first, then wants with the leftovers","Half on needs, half on wants","Whatever feels most urgent that day"],"answer":"B","explanation":"Paying for needs first makes sure the important things are covered. Wants are paid from whatever is left."},"hi":{"prompt":"अर्जुन को अभी-अभी महीने की पॉकेट मनी मिली है। उसे किस क्रम में खर्च करना चाहिए?","options":["पहले चाहतें, फिर बचे पैसों से ज़रूरतें","पहले ज़रूरतें, फिर बचे पैसों से चाहतें","आधा ज़रूरतों पर, आधा चाहतों पर","उस दिन जो सबसे ज़रूरी लगे"],"answer":"B","explanation":"पहले ज़रूरतों पर खर्च करने से ज़रूरी चीज़ें पक्की हो जाती हैं। चाहतें बचे हुए पैसों से पूरी होती हैं।"},"te":{"prompt":"అర్జున్‌కి ఇప్పుడే నెల పాకెట్ మనీ వచ్చింది. అతను ఏ క్రమంలో ఖర్చు చేయాలి?","options":["ముందు కోరికలు, మిగిలిన డబ్బుతో అవసరాలు","ముందు అవసరాలు, మిగిలిన డబ్బుతో కోరికలు","సగం అవసరాలకు, సగం కోరికలకు","ఆ రోజు ఏది అర్జెంట్ అనిపిస్తే అది"],"answer":"B","explanation":"ముందు అవసరాలకు ఖర్చు చేస్తే ముఖ్యమైనవన్నీ కవర్ అవుతాయి. కోరికలకు మిగిలిన డబ్బు నుంచి ఖర్చు చేయాలి."}}'::jsonb, null,'budget-needs-vs-wants','live','ai'),
  ('budget-needs-vs-wants-006','budget', array['needs-vs-wants'], 'bronze','mcq', '{"en":{"prompt":"A phone recharge is a need for Neha, who attends online classes, but a want for her cousin. Why can this happen?","options":["Prices are different from shop to shop","Wants turn into needs if you like them enough","Needs depend on what each person''s life truly requires","Only adults have real needs"],"answer":"C","explanation":"Whether something is a need depends on the person''s situation. Neha needs the recharge for school; her cousin can manage without it."},"hi":{"prompt":"ऑनलाइन क्लास करने वाली नेहा के लिए फ़ोन रिचार्ज ज़रूरत है, पर उसके कज़िन के लिए चाहत। ऐसा क्यों हो सकता है?","options":["हर दुकान पर दाम अलग होते हैं","कोई चीज़ बहुत पसंद हो तो चाहत ज़रूरत बन जाती है","ज़रूरतें इस पर निर्भर हैं कि हर इंसान की ज़िंदगी को सच में क्या चाहिए","असली ज़रूरतें सिर्फ़ बड़ों की होती हैं"],"answer":"C","explanation":"कोई चीज़ ज़रूरत है या नहीं, यह इंसान के हालात पर निर्भर करता है। नेहा को पढ़ाई के लिए रिचार्ज चाहिए; उसके कज़िन का काम इसके बिना चल सकता है।"},"te":{"prompt":"ఆన్‌లైన్ క్లాసులు వినే నేహాకి ఫోన్ రీచార్జ్ అవసరం, కానీ తన కజిన్‌కి కోరిక. ఇలా ఎందుకు జరగొచ్చు?","options":["ఒక్కో షాపులో ఒక్కో ధర ఉంటుంది","బాగా నచ్చితే కోరికలు అవసరాలుగా మారిపోతాయి","ప్రతి వ్యక్తి జీవితానికి నిజంగా ఏం కావాలో దాన్ని బట్టి అవసరాలు ఉంటాయి","నిజమైన అవసరాలు పెద్దవాళ్లకే ఉంటాయి"],"answer":"C","explanation":"ఏదైనా అవసరమా కాదా అనేది ఆ వ్యక్తి పరిస్థితిని బట్టి ఉంటుంది. నేహాకి చదువు కోసం రీచార్జ్ కావాలి; తన కజిన్‌కి అది లేకపోయినా పర్వాలేదు."}}'::jsonb, null,'budget-needs-vs-wants','live','ai'),
  ('budget-tracking-spending-002','budget', array['tracking-spending'], 'bronze','mcq', '{"en":{"prompt":"What is the main purpose of tracking your spending?","options":["To see where your money actually goes","To make your income go up","To prove you never buy wants","So you no longer need a budget"],"answer":"A","explanation":"Tracking shows you exactly where your money goes. Then you can decide what to change."},"hi":{"prompt":"अपने खर्च का हिसाब रखने का मुख्य मकसद क्या है?","options":["यह देखना कि आपका पैसा असल में कहाँ जाता है","अपनी आमदनी बढ़ाना","यह साबित करना कि आप कभी चाहतों पर खर्च नहीं करते","ताकि आपको बजट की ज़रूरत ही न रहे"],"answer":"A","explanation":"हिसाब रखने से साफ़ दिखता है कि आपका पैसा कहाँ जा रहा है। फिर आप तय कर सकते हैं कि क्या बदलना है।"},"te":{"prompt":"మీ ఖర్చులను ట్రాక్ చేయడం ముఖ్య ఉద్దేశం ఏమిటి?","options":["మీ డబ్బు నిజంగా ఎక్కడికి వెళ్తుందో చూడటం","మీ ఆదాయం పెంచుకోవడం","మీరు ఎప్పుడూ కోరికల మీద ఖర్చు చేయరని నిరూపించడం","ఇక బడ్జెట్ అవసరం లేకుండా ఉండటం"],"answer":"A","explanation":"ట్రాక్ చేస్తే మీ డబ్బు సరిగ్గా ఎక్కడికి వెళ్తుందో తెలుస్తుంది. అప్పుడు ఏం మార్చాలో మీరు నిర్ణయించుకోవచ్చు."}}'::jsonb, null,null,'live','ai'),
  ('budget-tracking-spending-003','budget', array['tracking-spending'], 'bronze','mcq', '{"en":{"prompt":"Why do small UPI payments often go unnoticed?","options":["UPI payments are always free","One tap, no cash leaves your hand, so it feels invisible","UPI hides payments from your history","Small payments don''t count in a budget"],"answer":"B","explanation":"With UPI you never see cash leave your hand, so small spends don''t feel real. They still add up."},"hi":{"prompt":"छोटे UPI पेमेंट अक्सर ध्यान में क्यों नहीं आते?","options":["UPI पेमेंट हमेशा फ़्री होते हैं","बस एक टैप, हाथ से कैश नहीं जाता, इसलिए खर्च दिखता ही नहीं","UPI आपकी हिस्ट्री से पेमेंट छिपा देता है","छोटे पेमेंट बजट में नहीं गिने जाते"],"answer":"B","explanation":"UPI में हाथ से कैश जाता हुआ नहीं दिखता, इसलिए छोटे खर्च असली नहीं लगते। फिर भी वे जुड़ते जाते हैं।"},"te":{"prompt":"చిన్న UPI పేమెంట్లు తరచుగా ఎందుకు మన దృష్టికి రావు?","options":["UPI పేమెంట్లు ఎప్పుడూ ఫ్రీ","ఒక్క ట్యాప్, చేతిలోంచి క్యాష్ వెళ్లదు, అందుకే ఖర్చు కనిపించదు","UPI మీ హిస్టరీ నుంచి పేమెంట్లను దాచేస్తుంది","చిన్న పేమెంట్లు బడ్జెట్‌లో లెక్కలోకి రావు"],"answer":"B","explanation":"UPIలో చేతిలోంచి క్యాష్ వెళ్లడం కనిపించదు, అందుకే చిన్న ఖర్చులు నిజమైనవిగా అనిపించవు. అయినా అవి కలిసి పెద్ద మొత్తం అవుతాయి."}}'::jsonb, null,'save-chai-math','live','ai'),
  ('budget-50-30-20-002','budget', array['50-30-20'], 'bronze','mcq', '{"en":{"prompt":"In the 50-30-20 rule, what is the 20% part for?","options":["Wants","Needs","Bills and EMIs","Savings"],"answer":"D","explanation":"The rule puts 50% on needs, 30% on wants and 20% into savings."},"hi":{"prompt":"50-30-20 नियम में 20% वाला हिस्सा किसके लिए है?","options":["चाहतें","ज़रूरतें","बिल और EMI","बचत"],"answer":"D","explanation":"यह नियम 50% ज़रूरतों पर, 30% चाहतों पर और 20% बचत में रखता है।"},"te":{"prompt":"50-30-20 రూల్‌లో 20% భాగం దేనికోసం?","options":["కోరికలు","అవసరాలు","బిల్లులు, EMIలు","పొదుపు"],"answer":"D","explanation":"ఈ రూల్ ప్రకారం 50% అవసరాలకు, 30% కోరికలకు, 20% పొదుపుకు."}}'::jsonb, null,null,'live','ai'),
  ('budget-pocket-money-001','budget', array['pocket-money'], 'bronze','mcq', '{"en":{"prompt":"What is a budget?","options":["A plan for how you will use your money","A list of what you bought last year","A rule that bans spending on fun","The money left at the end of the month"],"answer":"A","explanation":"A budget is a plan made in advance for how your money will be used. It can include fun, as long as it is planned."},"hi":{"prompt":"बजट क्या है?","options":["आप अपना पैसा कैसे इस्तेमाल करेंगे, उसका प्लान","पिछले साल आपने जो खरीदा, उसकी लिस्ट","मौज-मस्ती पर खर्च रोकने वाला नियम","महीने के आख़िर में बचा पैसा"],"answer":"A","explanation":"बजट पहले से बनाया गया प्लान है कि आपका पैसा कैसे इस्तेमाल होगा। इसमें मौज-मस्ती भी हो सकती है, बस वह प्लान की हुई हो।"},"te":{"prompt":"బడ్జెట్ అంటే ఏమిటి?","options":["మీ డబ్బును ఎలా వాడతారో వేసుకునే ప్లాన్","పోయిన ఏడాది మీరు కొన్నవాటి లిస్ట్","సరదాల మీద ఖర్చును నిషేధించే రూల్","నెల చివర మిగిలే డబ్బు"],"answer":"A","explanation":"బడ్జెట్ అంటే మీ డబ్బు ఎలా వాడాలో ముందే వేసుకునే ప్లాన్. ప్లాన్ చేసుకుంటే అందులో సరదాలకు కూడా చోటు ఉంటుంది."}}'::jsonb, null,null,'live','ai'),
  ('budget-bills-and-emi-001','budget', array['bills-and-emi'], 'bronze','mcq', '{"en":{"prompt":"What is an EMI?","options":["A one-time discount when you buy","A fee charged on every UPI payment","A fixed monthly payment to repay a loan","Interest you earn on your savings"],"answer":"C","explanation":"EMI means Equated Monthly Instalment. It is the same amount paid every month until a loan is repaid."},"hi":{"prompt":"EMI क्या है?","options":["खरीदते समय मिलने वाली एक बार की छूट","हर UPI पेमेंट पर लगने वाली फ़ीस","लोन चुकाने के लिए हर महीने दी जाने वाली तय रकम","आपकी बचत पर मिलने वाला ब्याज"],"answer":"C","explanation":"EMI का मतलब है Equated Monthly Instalment। यह वह तय रकम है जो लोन चुकने तक हर महीने दी जाती है।"},"te":{"prompt":"EMI అంటే ఏమిటి?","options":["కొనేటప్పుడు ఒక్కసారి ఇచ్చే డిస్కౌంట్","ప్రతి UPI పేమెంట్‌కి వసూలు చేసే ఫీజు","లోన్ తీర్చడానికి ప్రతి నెలా కట్టే ఫిక్స్‌డ్ మొత్తం","మీ పొదుపు మీద మీకు వచ్చే వడ్డీ"],"answer":"C","explanation":"EMI అంటే Equated Monthly Instalment. లోన్ పూర్తిగా తీరేవరకు ప్రతి నెలా కట్టే ఒకే మొత్తం ఇది."}}'::jsonb, null,'budget-no-cost-emi','live','ai'),
  ('budget-bills-and-emi-002','budget', array['bills-and-emi'], 'bronze','mcq', '{"en":{"prompt":"Which of these is a fixed bill that many families pay every month?","options":["A movie ticket","A birthday gift","Street food on the way home","House rent"],"answer":"D","explanation":"Rent is the same amount, due every month. The others change or happen only now and then."},"hi":{"prompt":"इनमें से कौन-सा एक तय बिल है जो कई परिवार हर महीने भरते हैं?","options":["मूवी टिकट","जन्मदिन का तोहफ़ा","घर लौटते वक़्त स्ट्रीट फ़ूड","घर का किराया"],"answer":"D","explanation":"किराया हर महीने उतना ही होता है और हर महीने देना पड़ता है। बाकी खर्च बदलते रहते हैं या कभी-कभी ही होते हैं।"},"te":{"prompt":"చాలా కుటుంబాలు ప్రతి నెలా కట్టే ఫిక్స్‌డ్ బిల్లు వీటిలో ఏది?","options":["సినిమా టికెట్","బర్త్‌డే గిఫ్ట్","ఇంటికి వెళ్తూ తినే స్ట్రీట్ ఫుడ్","ఇంటి అద్దె"],"answer":"D","explanation":"అద్దె ప్రతి నెలా ఒకే మొత్తం, ప్రతి నెలా కట్టాలి. మిగతావి మారుతుంటాయి లేదా అప్పుడప్పుడు మాత్రమే వస్తాయి."}}'::jsonb, null,null,'live','ai'),
  ('budget-pocket-money-002','budget', array['pocket-money','tracking-spending'], 'bronze','mcq', '{"en":{"prompt":"What does \"pay yourself first\" mean?","options":["Move your savings aside as soon as money comes in","Buy something for yourself before paying bills","Spend first, then save whatever is left","Pay friends back before buying anything"],"answer":"A","explanation":"Saving first, on the day money arrives, means it doesn''t get spent by accident. You then spend what''s left."},"hi":{"prompt":"\"पहले खुद को पे करो\" का क्या मतलब है?","options":["पैसा आते ही अपनी बचत अलग रख दो","बिल भरने से पहले अपने लिए कुछ खरीद लो","पहले खर्च करो, फिर जो बचे उसे बचाओ","कुछ भी खरीदने से पहले दोस्तों का उधार चुकाओ"],"answer":"A","explanation":"जिस दिन पैसा आए उसी दिन बचत करने से वह गलती से खर्च नहीं होता। फिर जो बचे, वह खर्च करो।"},"te":{"prompt":"\"ముందు మీకు మీరే పే చేసుకోండి\" అంటే అర్థం ఏమిటి?","options":["డబ్బు రాగానే పొదుపును పక్కన పెట్టేయడం","బిల్లులు కట్టే ముందు మీ కోసం ఏదైనా కొనుక్కోవడం","ముందు ఖర్చు చేసి, మిగిలింది పొదుపు చేయడం","ఏదైనా కొనే ముందు ఫ్రెండ్స్ అప్పు తీర్చడం"],"answer":"A","explanation":"డబ్బు వచ్చిన రోజే పొదుపు చేస్తే అది పొరపాటున ఖర్చైపోదు. ఆ తర్వాత మిగిలినదాన్ని ఖర్చు చేయండి."}}'::jsonb, null,null,'live','ai'),
  ('budget-bills-and-emi-003','budget', array['bills-and-emi'], 'silver','mcq', '{"en":{"prompt":"In \"Peter Falls for ''No-Cost EMI''\", why does Stewie say no-cost EMI is often not really free?","options":["The price doubles after the first month","You must pay the full price upfront","You may still pay a processing fee and GST on interest","The shop keeps your phone until you finish paying"],"answer":"C","explanation":"The shop''s discount covers the interest, but a processing fee and GST on the interest are often still charged. So \"no-cost\" can mean some cost."},"hi":{"prompt":"\"Peter Falls for ''No-Cost EMI''\" में स्टूवी क्यों कहता है कि नो-कॉस्ट EMI अक्सर सच में फ़्री नहीं होती?","options":["पहले महीने के बाद दाम दोगुना हो जाता है","आपको पूरी कीमत पहले ही देनी पड़ती है","आपको फिर भी प्रोसेसिंग फ़ीस और ब्याज पर GST देना पड़ सकता है","पूरा पैसा चुकने तक दुकान आपका फ़ोन अपने पास रखती है"],"answer":"C","explanation":"दुकान की छूट ब्याज को कवर करती है, पर प्रोसेसिंग फ़ीस और ब्याज पर GST अक्सर फिर भी लगते हैं। इसलिए \"नो-कॉस्ट\" में भी कुछ खर्च हो सकता है।"},"te":{"prompt":"\"Peter Falls for ''No-Cost EMI''\"లో, నో-కాస్ట్ EMI చాలాసార్లు నిజంగా ఫ్రీ కాదని స్టూవీ ఎందుకు అంటాడు?","options":["మొదటి నెల తర్వాత ధర రెట్టింపు అవుతుంది","పూర్తి ధర ముందే కట్టాలి","అయినా ప్రాసెసింగ్ ఫీజు, వడ్డీ మీద GST కట్టాల్సి రావొచ్చు","మొత్తం కట్టేవరకు షాప్ వాళ్లు మీ ఫోన్‌ని తమ దగ్గరే ఉంచుకుంటారు"],"answer":"C","explanation":"షాప్ ఇచ్చే డిస్కౌంట్ వడ్డీని కవర్ చేస్తుంది, కానీ ప్రాసెసింగ్ ఫీజు, వడ్డీ మీద GST చాలాసార్లు అయినా వసూలు చేస్తారు. కాబట్టి \"నో-కాస్ట్\" అన్నా కొంత ఖర్చు ఉండొచ్చు."}}'::jsonb, 'budget-no-cost-emi',null,'live','ai'),
  ('budget-bills-and-emi-004','budget', array['bills-and-emi'], 'silver','mcq', '{"en":{"prompt":"Peter''s credit card bill is ₹20,000. He pays only the ₹1,000 \"minimum due\". What happens to the rest?","options":["It is forgiven by the card company","It is charged interest, which keeps growing","It waits interest-free until next month","It is taken from his savings automatically"],"answer":"B","explanation":"Paying the minimum only avoids a late fee. The unpaid ₹19,000 is charged high interest every month, and interest gets added on interest."},"hi":{"prompt":"पीटर का क्रेडिट कार्ड बिल ₹20,000 है। वह सिर्फ़ ₹1,000 का \"मिनिमम ड्यू\" भरता है। बाकी रकम का क्या होता है?","options":["कार्ड कंपनी उसे माफ़ कर देती है","उस पर ब्याज लगता है, जो बढ़ता ही जाता है","वह अगले महीने तक बिना ब्याज के रुकी रहती है","वह अपने-आप उसकी बचत से कट जाती है"],"answer":"B","explanation":"मिनिमम भरने से सिर्फ़ लेट फ़ीस से बचते हैं। बचे हुए ₹19,000 पर हर महीने भारी ब्याज लगता है, और ब्याज पर भी ब्याज जुड़ता है।"},"te":{"prompt":"పీటర్ క్రెడిట్ కార్డ్ బిల్లు ₹20,000. అతను ₹1,000 \"మినిమమ్ డ్యూ\" మాత్రమే కడతాడు. మిగతా మొత్తానికి ఏమవుతుంది?","options":["కార్డ్ కంపెనీ దాన్ని మాఫీ చేస్తుంది","దాని మీద వడ్డీ పడుతుంది, అది పెరుగుతూనే ఉంటుంది","వచ్చే నెల వరకు వడ్డీ లేకుండా ఆగుతుంది","అతని పొదుపు నుంచి ఆటోమేటిక్‌గా కట్ అవుతుంది"],"answer":"B","explanation":"మినిమమ్ కడితే లేట్ ఫీజు మాత్రమే తప్పుతుంది. కట్టని ₹19,000 మీద ప్రతి నెలా ఎక్కువ వడ్డీ పడుతుంది, వడ్డీ మీద కూడా వడ్డీ కలుస్తుంది."}}'::jsonb, 'budget-minimum-due',null,'live','ai'),
  ('budget-pocket-money-003','budget', array['pocket-money','tracking-spending'], 'silver','mcq', '{"en":{"prompt":"Rahul''s ₹2,000 pocket money runs out by the 20th every month, and he isn''t sure why. What is the most useful first step?","options":["Ask his parents for more money","Write down every spend for a month","Borrow from friends till month end","Stop buying any food outside at all"],"answer":"B","explanation":"He can''t fix a leak he can''t see. Tracking every spend shows where the money really goes, so he can cut the right things."},"hi":{"prompt":"राहुल की ₹2,000 पॉकेट मनी हर महीने 20 तारीख तक ख़त्म हो जाती है, और उसे समझ नहीं आता क्यों। सबसे काम का पहला कदम क्या है?","options":["माता-पिता से और पैसे माँगना","एक महीने तक हर खर्च लिखना","महीने के आख़िर तक दोस्तों से उधार लेना","बाहर का खाना बिल्कुल बंद कर देना"],"answer":"B","explanation":"जो लीक दिखे ही नहीं, उसे ठीक नहीं किया जा सकता। हर खर्च लिखने से पता चलता है कि पैसा असल में कहाँ जाता है, ताकि वह सही चीज़ों में कटौती कर सके।"},"te":{"prompt":"రాహుల్ ₹2,000 పాకెట్ మనీ ప్రతి నెలా 20వ తేదీకల్లా అయిపోతుంది, ఎందుకో అతనికి అర్థం కావట్లేదు. అన్నిటికంటే ఉపయోగపడే మొదటి అడుగు ఏది?","options":["అమ్మానాన్నలను ఇంకా డబ్బు అడగడం","ఒక నెల పాటు ప్రతి ఖర్చును రాసుకోవడం","నెల చివరి వరకు ఫ్రెండ్స్ దగ్గర అప్పు తీసుకోవడం","బయట ఏ ఫుడ్ కొనడం అయినా పూర్తిగా ఆపేయడం"],"answer":"B","explanation":"కనిపించని లీక్‌ని సరిచేయలేం. ప్రతి ఖర్చు రాసుకుంటే డబ్బు నిజంగా ఎక్కడికి వెళ్తుందో తెలుస్తుంది, అప్పుడు సరైనవాటినే తగ్గించుకోవచ్చు."}}'::jsonb, null,'budget-pocket-money-plan','live','ai'),
  ('budget-50-30-20-003','budget', array['50-30-20','pocket-money'], 'silver','mcq', '{"en":{"prompt":"Sneha gets ₹3,000 a month and wants to follow the 50-30-20 rule. How much goes to savings?","options":["₹300","₹900","₹1,500","₹600"],"answer":"D","explanation":"Savings are 20% of the money. 20% of ₹3,000 is ₹600."},"hi":{"prompt":"स्नेहा को हर महीने ₹3,000 मिलते हैं और वह 50-30-20 नियम मानना चाहती है। बचत में कितना जाएगा?","options":["₹300","₹900","₹1,500","₹600"],"answer":"D","explanation":"बचत पैसे का 20% होती है। ₹3,000 का 20% है ₹600।"},"te":{"prompt":"స్నేహకి నెలకు ₹3,000 వస్తాయి, ఆమె 50-30-20 రూల్ పాటించాలనుకుంటోంది. పొదుపుకు ఎంత వెళ్తుంది?","options":["₹300","₹900","₹1,500","₹600"],"answer":"D","explanation":"పొదుపు అంటే డబ్బులో 20%. ₹3,000లో 20% అంటే ₹600."}}'::jsonb, null,'budget-pocket-money-plan','live','ai'),
  ('budget-tracking-spending-004','budget', array['tracking-spending','pocket-money'], 'silver','mcq', '{"en":{"prompt":"On Sunday, Imran checks his UPI history and finds he spent ₹450 on snacks this week. What is a sensible next step?","options":["Set a weekly snack limit and keep checking","Delete the history so it doesn''t bother him","Ignore it, because small spends don''t matter","Spend more next week to even it out"],"answer":"A","explanation":"A limit turns what he learned into a plan, and checking each week shows if it is working."},"hi":{"prompt":"रविवार को इमरान अपनी UPI हिस्ट्री देखता है और पाता है कि इस हफ़्ते उसने स्नैक्स पर ₹450 खर्च किए। अगला समझदारी भरा कदम क्या है?","options":["स्नैक्स की हफ़्ते की लिमिट तय करना और चेक करते रहना","हिस्ट्री डिलीट कर देना ताकि परेशानी न हो","नज़रअंदाज़ करना, क्योंकि छोटे खर्च मायने नहीं रखते","हिसाब बराबर करने के लिए अगले हफ़्ते और खर्च करना"],"answer":"A","explanation":"लिमिट तय करने से जो उसने सीखा, वह एक प्लान बन जाता है, और हर हफ़्ते चेक करने से पता चलता है कि प्लान काम कर रहा है या नहीं।"},"te":{"prompt":"ఆదివారం ఇమ్రాన్ తన UPI హిస్టరీ చూస్తే, ఈ వారం స్నాక్స్ మీద ₹450 ఖర్చు చేశాడని తెలుస్తుంది. తర్వాత చేయాల్సిన సరైన పని ఏది?","options":["స్నాక్స్‌కి వారానికి ఒక లిమిట్ పెట్టుకుని, చెక్ చేస్తూ ఉండటం","ఇబ్బంది లేకుండా హిస్టరీ డిలీట్ చేయడం","చిన్న ఖర్చులు పెద్ద విషయం కాదని పట్టించుకోకపోవడం","బ్యాలెన్స్ చేయడానికి వచ్చే వారం ఇంకా ఎక్కువ ఖర్చు చేయడం"],"answer":"A","explanation":"లిమిట్ పెట్టుకుంటే తెలుసుకున్నది ఒక ప్లాన్‌గా మారుతుంది, ప్రతి వారం చెక్ చేస్తే అది పనిచేస్తోందో లేదో తెలుస్తుంది."}}'::jsonb, null,'budget-pocket-money-plan','live','ai'),
  ('budget-pocket-money-004','budget', array['pocket-money'], 'silver','mcq', '{"en":{"prompt":"Divya gets ₹1,800 on the 1st. Her ₹600 bus pass must be paid on the 10th. Which plan keeps her from running short?","options":["Keep ₹600 aside for the pass on day 1","Spend freely and pay from what is left","Pay the pass only if money is left","Use the pass money now and borrow later"],"answer":"A","explanation":"Setting the bus pass money aside first means a need is covered before any of it is spent on wants."},"hi":{"prompt":"दिव्या को 1 तारीख को ₹1,800 मिलते हैं। उसके ₹600 के बस पास का पैसा 10 तारीख को भरना है। कौन-सा प्लान उसे पैसों की कमी से बचाता है?","options":["पहले ही दिन पास के लिए ₹600 अलग रख देना","खुलकर खर्च करना और बचे पैसों से पास भरना","पैसे बचें तो ही पास भरना","पास के पैसे अभी इस्तेमाल करना और बाद में उधार लेना"],"answer":"A","explanation":"बस पास के पैसे पहले अलग रखने से चाहतों पर कुछ भी खर्च होने से पहले ज़रूरत पूरी हो जाती है।"},"te":{"prompt":"దివ్యకి 1వ తేదీన ₹1,800 వస్తాయి. ₹600 బస్ పాస్ డబ్బు 10వ తేదీన కట్టాలి. ఏ ప్లాన్ వల్ల ఆమెకు డబ్బు కొరత రాదు?","options":["మొదటి రోజే పాస్ కోసం ₹600 పక్కన పెట్టడం","ఇష్టం వచ్చినట్లు ఖర్చు చేసి, మిగిలినదానితో పాస్ కట్టడం","డబ్బు మిగిలితేనే పాస్ కట్టడం","పాస్ డబ్బును ఇప్పుడు వాడేసి, తర్వాత అప్పు తీసుకోవడం"],"answer":"A","explanation":"బస్ పాస్ డబ్బును ముందే పక్కన పెడితే, కోరికల మీద ఏదైనా ఖర్చు చేసే ముందే అవసరం కవర్ అవుతుంది."}}'::jsonb, null,'budget-pocket-money-plan','live','ai'),
  ('budget-50-30-20-004','budget', array['50-30-20','pocket-money'], 'silver','mcq', '{"en":{"prompt":"Kiran gets ₹2,500 a month. Her needs cost ₹1,500, which is more than 50%. How can she adjust her 50-30-20 plan?","options":["Stop saving and keep wants the same","Skip a need, like her exam fee","Drop the plan and spend as she likes","Spend less on wants so needs and savings stay covered"],"answer":"D","explanation":"50-30-20 is a guide, not a fixed law. When needs cost more, the extra should come out of wants first."},"hi":{"prompt":"किरण को हर महीने ₹2,500 मिलते हैं। उसकी ज़रूरतें ₹1,500 की हैं, जो 50% से ज़्यादा है। वह अपना 50-30-20 प्लान कैसे बदल सकती है?","options":["बचत बंद कर दे और चाहतें वैसी ही रखे","कोई ज़रूरत छोड़ दे, जैसे अपनी एग्ज़ाम फ़ीस","प्लान छोड़कर मन मुताबिक खर्च करे","चाहतों पर कम खर्च करे ताकि ज़रूरतें और बचत दोनों पूरी हों"],"answer":"D","explanation":"50-30-20 एक गाइड है, पक्का कानून नहीं। जब ज़रूरतें ज़्यादा हों, तो एक्स्ट्रा पैसा पहले चाहतों में से कटना चाहिए।"},"te":{"prompt":"కిరణ్‌కి నెలకు ₹2,500 వస్తాయి. ఆమె అవసరాలకు ₹1,500 అవుతుంది, ఇది 50% కంటే ఎక్కువ. తన 50-30-20 ప్లాన్‌ని ఎలా మార్చుకోవచ్చు?","options":["పొదుపు ఆపేసి, కోరికలను అలాగే ఉంచడం","ఎగ్జామ్ ఫీజు లాంటి ఒక అవసరాన్ని వదిలేయడం","ప్లాన్ వదిలేసి ఇష్టం వచ్చినట్లు ఖర్చు చేయడం","అవసరాలు, పొదుపు కవర్ అయ్యేలా కోరికల మీద ఖర్చు తగ్గించడం"],"answer":"D","explanation":"50-30-20 ఒక గైడ్ మాత్రమే, మార్చలేని రూల్ కాదు. అవసరాలకు ఎక్కువ అయితే, ఆ అదనపు మొత్తం ముందు కోరికల నుంచి తగ్గించాలి."}}'::jsonb, null,'budget-pocket-money-plan','live','ai'),
  ('budget-needs-vs-wants-007','budget', array['needs-vs-wants'], 'silver','mcq', '{"en":{"prompt":"Ravi has ₹500 left. His phone recharge for online classes costs ₹299, and a concert ticket costs ₹450. Which is the needs-first choice?","options":["Buy the ticket and skip the recharge","Borrow ₹250 to pay for both","Recharge now and save the rest toward the ticket","Spend ₹250 on each"],"answer":"C","explanation":"The recharge is needed for his classes, so it comes first. The ticket is a want he can save up for."},"hi":{"prompt":"रवि के पास ₹500 बचे हैं। ऑनलाइन क्लास के लिए उसका फ़ोन रिचार्ज ₹299 का है, और एक कॉन्सर्ट टिकट ₹450 का। \"पहले ज़रूरत\" वाला चुनाव कौन-सा है?","options":["टिकट खरीद ले और रिचार्ज छोड़ दे","दोनों के लिए ₹250 उधार ले","अभी रिचार्ज करे और बाकी पैसे टिकट के लिए बचाए","हर एक पर ₹250 खर्च करे"],"answer":"C","explanation":"क्लास के लिए रिचार्ज ज़रूरी है, इसलिए वह पहले आता है। टिकट एक चाहत है, जिसके लिए वह पैसे जोड़ सकता है।"},"te":{"prompt":"రవి దగ్గర ₹500 మిగిలాయి. ఆన్‌లైన్ క్లాసుల కోసం ఫోన్ రీచార్జ్ ₹299, ఒక కాన్సర్ట్ టికెట్ ₹450. \"ముందు అవసరాలు\" అనే పద్ధతిలో సరైన ఎంపిక ఏది?","options":["టికెట్ కొని రీచార్జ్ వదిలేయడం","రెండింటి కోసం ₹250 అప్పు తీసుకోవడం","ఇప్పుడు రీచార్జ్ చేసి, మిగిలింది టికెట్ కోసం దాచుకోవడం","ఒక్కోదానికి ₹250 ఖర్చు చేయడం"],"answer":"C","explanation":"క్లాసుల కోసం రీచార్జ్ అవసరం, కాబట్టి అదే ముందు. టికెట్ ఒక కోరిక, దాని కోసం అతను డబ్బు కూడబెట్టుకోవచ్చు."}}'::jsonb, null,null,'live','ai'),
  ('budget-bills-and-emi-005','budget', array['bills-and-emi'], 'silver','mcq', '{"en":{"prompt":"A shop offers a phone \"for just ₹999 a month\". Before agreeing, which question matters most?","options":["What is the total I will pay?","Is the monthly amount under ₹1,000?","Do my friends also buy on EMI?","What colours does the phone come in?"],"answer":"A","explanation":"A small monthly amount can hide a large total. Knowing the total, with fees, tells you the true cost."},"hi":{"prompt":"एक दुकान फ़ोन \"सिर्फ़ ₹999 महीना\" में ऑफ़र करती है। हाँ कहने से पहले कौन-सा सवाल सबसे ज़रूरी है?","options":["कुल मिलाकर मैं कितना भरूँगा?","क्या महीने की रकम ₹1,000 से कम है?","क्या मेरे दोस्त भी EMI पर खरीदते हैं?","फ़ोन किन रंगों में आता है?"],"answer":"A","explanation":"छोटी मासिक रकम के पीछे बड़ा कुल खर्च छिपा हो सकता है। फ़ीस मिलाकर कुल रकम जानने से असली कीमत पता चलती है।"},"te":{"prompt":"ఒక షాప్ ఫోన్‌ని \"నెలకు కేవలం ₹999\" అని ఆఫర్ చేస్తోంది. ఒప్పుకునే ముందు అడగాల్సిన అతి ముఖ్యమైన ప్రశ్న ఏది?","options":["మొత్తం కలిపి నేను ఎంత కడతాను?","నెలవారీ మొత్తం ₹1,000 కంటే తక్కువా?","నా ఫ్రెండ్స్ కూడా EMIలో కొంటారా?","ఫోన్ ఏ రంగుల్లో వస్తుంది?"],"answer":"A","explanation":"చిన్న నెలవారీ మొత్తం వెనుక పెద్ద మొత్తం దాగి ఉండొచ్చు. ఫీజులతో కలిపి మొత్తం ఎంతో తెలిస్తే అసలు ధర తెలుస్తుంది."}}'::jsonb, null,'budget-no-cost-emi','live','ai'),
  ('budget-tracking-spending-005','budget', array['tracking-spending'], 'silver','mcq', '{"en":{"prompt":"Which kind of spending is easiest to lose track of?","options":["One large exam fee","Many small spends every day","A fixed monthly rent","A yearly school fee"],"answer":"B","explanation":"Big payments are easy to remember. Small daily spends feel like nothing but quietly add up."},"hi":{"prompt":"किस तरह के खर्च का हिसाब सबसे आसानी से छूट जाता है?","options":["एक बड़ी एग्ज़ाम फ़ीस","रोज़ के कई छोटे खर्च","महीने का तय किराया","साल की स्कूल फ़ीस"],"answer":"B","explanation":"बड़े पेमेंट याद रखना आसान है। रोज़ के छोटे खर्च कुछ नहीं लगते, पर चुपचाप जुड़ते जाते हैं।"},"te":{"prompt":"ఏ రకమైన ఖర్చు లెక్క చాలా సులభంగా తప్పిపోతుంది?","options":["ఒక పెద్ద ఎగ్జామ్ ఫీజు","రోజూ చేసే చాలా చిన్న ఖర్చులు","నెలవారీ ఫిక్స్‌డ్ అద్దె","ఏడాదికి ఒకసారి కట్టే స్కూల్ ఫీజు"],"answer":"B","explanation":"పెద్ద పేమెంట్లు గుర్తుంచుకోవడం సులభం. రోజువారీ చిన్న ఖర్చులు ఏమీ కానట్టు అనిపిస్తాయి, కానీ నిశ్శబ్దంగా పెరిగిపోతాయి."}}'::jsonb, null,'save-chai-math','live','ai'),
  ('budget-needs-vs-wants-008','budget', array['needs-vs-wants'], 'silver','mcq', '{"en":{"prompt":"A sale offers 40% off shoes Ajay doesn''t need. He has ₹1,000 saved for his exam fee. What is the sound reasoning?","options":["Buy now, because 40% off saves money","Use the exam money now and refill it later","Buy two pairs to save even more","A discount on a want is still spending"],"answer":"D","explanation":"A discount only saves money on something you were going to buy anyway. Using exam fee money on a want puts a need at risk."},"hi":{"prompt":"एक सेल में उन जूतों पर 40% छूट है जिनकी अजय को ज़रूरत नहीं। उसने एग्ज़ाम फ़ीस के लिए ₹1,000 बचाए हैं। सही सोच क्या है?","options":["अभी खरीद ले, क्योंकि 40% छूट से पैसे बचते हैं","एग्ज़ाम के पैसे अभी इस्तेमाल करे और बाद में भर दे","और ज़्यादा बचाने के लिए दो जोड़ी खरीद ले","चाहत पर छूट भी आख़िर खर्च ही है"],"answer":"D","explanation":"छूट से पैसे तभी बचते हैं जब आप वह चीज़ वैसे भी खरीदने वाले थे। एग्ज़ाम फ़ीस के पैसे चाहत पर लगाने से एक ज़रूरत ख़तरे में पड़ जाती है।"},"te":{"prompt":"అజయ్‌కి అవసరం లేని షూస్ మీద సేల్‌లో 40% డిస్కౌంట్ ఉంది. అతను ఎగ్జామ్ ఫీజు కోసం ₹1,000 దాచుకున్నాడు. సరైన ఆలోచన ఏది?","options":["ఇప్పుడే కొనేయాలి, 40% డిస్కౌంట్ వల్ల డబ్బు ఆదా అవుతుంది","ఎగ్జామ్ డబ్బు ఇప్పుడు వాడి, తర్వాత మళ్లీ పెట్టాలి","ఇంకా ఎక్కువ ఆదా కోసం రెండు జతలు కొనాలి","కోరిక మీద డిస్కౌంట్ అయినా అది ఖర్చే"],"answer":"D","explanation":"మీరు ఎలాగూ కొనాలనుకున్న వస్తువు మీద మాత్రమే డిస్కౌంట్ డబ్బు ఆదా చేస్తుంది. ఎగ్జామ్ ఫీజు డబ్బును కోరిక మీద వాడితే ఒక అవసరం ప్రమాదంలో పడుతుంది."}}'::jsonb, null,null,'live','ai'),
  ('budget-pocket-money-005','budget', array['pocket-money'], 'silver','mcq', '{"en":{"prompt":"Fatima earns ₹800 from tuitions in some months and nothing in others. How should she plan her spending?","options":["Plan around her best month","Spend it all as soon as it comes","Plan around the low months, not the best ones","Plan on the average and borrow the gap"],"answer":"C","explanation":"If she plans for the months with no income, she won''t run short when they come. Extra in good months can be saved."},"hi":{"prompt":"फ़ातिमा कुछ महीनों में ट्यूशन से ₹800 कमाती है और कुछ महीनों में कुछ नहीं। उसे अपना खर्च कैसे प्लान करना चाहिए?","options":["अपने सबसे अच्छे महीने के हिसाब से","पैसा आते ही सब खर्च कर दे","कम कमाई वाले महीनों के हिसाब से, अच्छे महीनों के नहीं","औसत के हिसाब से, और कमी उधार लेकर पूरी करे"],"answer":"C","explanation":"अगर वह बिना कमाई वाले महीनों के हिसाब से प्लान करे, तो ऐसे महीने आने पर पैसे कम नहीं पड़ेंगे। अच्छे महीनों का एक्स्ट्रा पैसा बचाया जा सकता है।"},"te":{"prompt":"ఫాతిమా కొన్ని నెలల్లో ట్యూషన్ల ద్వారా ₹800 సంపాదిస్తుంది, కొన్ని నెలల్లో ఏమీ రాదు. తన ఖర్చును ఎలా ప్లాన్ చేసుకోవాలి?","options":["తనకు బాగా వచ్చిన నెలను బట్టి","వచ్చిన వెంటనే మొత్తం ఖర్చు చేయడం","బాగా వచ్చిన నెలలను కాదు, తక్కువ వచ్చే నెలలను బట్టి","సగటును బట్టి, తక్కువైనది అప్పు తీసుకుని"],"answer":"C","explanation":"ఆదాయం లేని నెలలను బట్టి ప్లాన్ చేస్తే, అలాంటి నెలలు వచ్చినప్పుడు డబ్బు కొరత రాదు. మంచి నెలల్లో వచ్చే అదనపు డబ్బును పొదుపు చేయవచ్చు."}}'::jsonb, null,null,'live','ai'),
  ('budget-bills-and-emi-006','budget', array['bills-and-emi'], 'silver','mcq', '{"en":{"prompt":"Suresh''s family pays rent, electricity and a ₹2,000 loan EMI every month. Why should these come first in their budget?","options":["They must be paid every month, with fines if late","They are wants that can wait","They change every day","They earn interest for the family"],"answer":"A","explanation":"These are fixed bills that are due every month. Missing them brings late fees and other trouble, so they are planned first."},"hi":{"prompt":"सुरेश का परिवार हर महीने किराया, बिजली का बिल और ₹2,000 की लोन EMI भरता है। इन्हें बजट में सबसे पहले क्यों रखना चाहिए?","options":["ये हर महीने भरने ही पड़ते हैं, देर होने पर जुर्माना लगता है","ये चाहतें हैं जो रुक सकती हैं","ये रोज़ बदलते हैं","इनसे परिवार को ब्याज मिलता है"],"answer":"A","explanation":"ये तय बिल हैं जो हर महीने देने होते हैं। इन्हें न भरने पर लेट फ़ीस और दूसरी परेशानियाँ होती हैं, इसलिए इन्हें पहले प्लान किया जाता है।"},"te":{"prompt":"సురేష్ కుటుంబం ప్రతి నెలా అద్దె, కరెంట్ బిల్లు, ₹2,000 లోన్ EMI కడుతుంది. వీటిని బడ్జెట్‌లో ఎందుకు ముందు పెట్టాలి?","options":["వీటిని ప్రతి నెలా కట్టాల్సిందే, ఆలస్యమైతే జరిమానా పడుతుంది","ఇవి ఆగగలిగే కోరికలు","ఇవి రోజూ మారుతుంటాయి","వీటి వల్ల కుటుంబానికి వడ్డీ వస్తుంది"],"answer":"A","explanation":"ఇవి ప్రతి నెలా కట్టాల్సిన ఫిక్స్‌డ్ బిల్లులు. కట్టకపోతే లేట్ ఫీజులు, ఇతర ఇబ్బందులు వస్తాయి, అందుకే వీటిని ముందు ప్లాన్ చేస్తారు."}}'::jsonb, null,null,'live','ai'),
  ('budget-50-30-20-005','budget', array['50-30-20'], 'silver','mcq', '{"en":{"prompt":"Which of these belongs in the 30% \"wants\" part of a 50-30-20 budget?","options":["A bus pass","A movie with friends","An exam fee","Money for emergencies"],"answer":"B","explanation":"A movie is nice to have but not needed. Bus pass and exam fee are needs, and emergency money is savings."},"hi":{"prompt":"50-30-20 बजट के 30% \"चाहतों\" वाले हिस्से में इनमें से क्या आता है?","options":["बस पास","दोस्तों के साथ मूवी","एग्ज़ाम फ़ीस","इमरजेंसी के लिए पैसे"],"answer":"B","explanation":"मूवी हो तो अच्छा है, पर ज़रूरी नहीं। बस पास और एग्ज़ाम फ़ीस ज़रूरतें हैं, और इमरजेंसी के पैसे बचत में आते हैं।"},"te":{"prompt":"50-30-20 బడ్జెట్‌లో 30% \"కోరికలు\" భాగంలోకి వీటిలో ఏది వస్తుంది?","options":["బస్ పాస్","ఫ్రెండ్స్‌తో సినిమా","ఎగ్జామ్ ఫీజు","ఎమర్జెన్సీల కోసం డబ్బు"],"answer":"B","explanation":"సినిమా ఉంటే బాగుంటుంది కానీ అవసరం కాదు. బస్ పాస్, ఎగ్జామ్ ఫీజు అవసరాలు; ఎమర్జెన్సీ డబ్బు పొదుపులోకి వస్తుంది."}}'::jsonb, null,null,'live','ai'),
  ('budget-tracking-spending-006','budget', array['tracking-spending'], 'silver','mcq', '{"en":{"prompt":"Lakshmi wants to track her spending but keeps forgetting. Which habit is easiest to keep up?","options":["Check it once a year","Track only purchases above ₹1,000","Track only the cash she spends","Check her payment history for a few minutes each week"],"answer":"D","explanation":"A short weekly check catches small spends before they pile up, and it is quick enough to stick with."},"hi":{"prompt":"लक्ष्मी अपना खर्च ट्रैक करना चाहती है, पर बार-बार भूल जाती है। कौन-सी आदत निभाना सबसे आसान है?","options":["साल में एक बार चेक करना","सिर्फ़ ₹1,000 से ऊपर की खरीद ट्रैक करना","सिर्फ़ कैश वाले खर्च ट्रैक करना","हर हफ़्ते कुछ मिनट अपनी पेमेंट हिस्ट्री देखना"],"answer":"D","explanation":"हफ़्ते में एक छोटी-सी जाँच छोटे खर्चों को जमा होने से पहले पकड़ लेती है, और यह इतनी जल्दी हो जाती है कि आदत बनी रहती है।"},"te":{"prompt":"లక్ష్మి తన ఖర్చులు ట్రాక్ చేయాలనుకుంటుంది, కానీ మర్చిపోతూ ఉంటుంది. ఏ అలవాటు కొనసాగించడం అన్నిటికంటే సులభం?","options":["ఏడాదికి ఒకసారి చెక్ చేయడం","₹1,000 పైన ఉన్న కొనుగోళ్లు మాత్రమే ట్రాక్ చేయడం","క్యాష్ ఖర్చులు మాత్రమే ట్రాక్ చేయడం","ప్రతి వారం కొన్ని నిమిషాలు తన పేమెంట్ హిస్టరీ చూడటం"],"answer":"D","explanation":"వారానికి ఒకసారి చిన్న చెక్ చేస్తే చిన్న ఖర్చులు పోగయ్యేలోపే తెలుస్తాయి, ఇది త్వరగా అయిపోతుంది కాబట్టి అలవాటుగా కొనసాగుతుంది."}}'::jsonb, null,'save-chai-math','live','ai'),
  ('budget-tracking-spending-007','budget', array['tracking-spending'], 'gold','mcq', '{"en":{"prompt":"Meena buys a ₹40 cold drink every school day. Assume 24 school days a month. How much does this cost her in a year?","options":["₹960","₹4,800","₹11,520","₹14,600"],"answer":"C","explanation":"₹40 × 24 = ₹960 a month, and ₹960 × 12 = ₹11,520 a year."},"hi":{"prompt":"मीना हर स्कूल वाले दिन ₹40 की कोल्ड ड्रिंक खरीदती है। मान लो महीने में 24 स्कूल के दिन होते हैं। इससे साल भर में उसका कितना खर्च होता है?","options":["₹960","₹4,800","₹11,520","₹14,600"],"answer":"C","explanation":"₹40 × 24 = महीने के ₹960, और ₹960 × 12 = साल के ₹11,520।"},"te":{"prompt":"మీనా స్కూల్ ఉన్న ప్రతి రోజూ ₹40 కూల్ డ్రింక్ కొంటుంది. నెలకు 24 స్కూల్ రోజులు అనుకుందాం. ఏడాదికి దీనికి ఆమెకు ఎంత ఖర్చవుతుంది?","options":["₹960","₹4,800","₹11,520","₹14,600"],"answer":"C","explanation":"₹40 × 24 = నెలకు ₹960, ₹960 × 12 = ఏడాదికి ₹11,520."}}'::jsonb, null,'save-chai-math','live','ai'),
  ('budget-bills-and-emi-007','budget', array['bills-and-emi'], 'gold','mcq', '{"en":{"prompt":"A ₹12,000 phone is offered at ₹1,100 a month for 12 months. Assume no other fees. How much more than the price do you pay?","options":["₹1,200","₹1,100","₹100","₹13,200"],"answer":"A","explanation":"₹1,100 × 12 = ₹13,200 in total. ₹13,200 − ₹12,000 = ₹1,200 extra."},"hi":{"prompt":"₹12,000 का एक फ़ोन 12 महीने तक ₹1,100 महीना पर मिल रहा है। मान लो कोई और फ़ीस नहीं है। आप कीमत से कितना ज़्यादा भरते हैं?","options":["₹1,200","₹1,100","₹100","₹13,200"],"answer":"A","explanation":"कुल ₹1,100 × 12 = ₹13,200 भरने होंगे। ₹13,200 − ₹12,000 = ₹1,200 ज़्यादा।"},"te":{"prompt":"₹12,000 ఫోన్‌ని 12 నెలల పాటు నెలకు ₹1,100 చొప్పున ఇస్తున్నారు. వేరే ఫీజులు లేవనుకుందాం. ధర కంటే ఎంత ఎక్కువ కడతారు?","options":["₹1,200","₹1,100","₹100","₹13,200"],"answer":"A","explanation":"మొత్తం ₹1,100 × 12 = ₹13,200. ₹13,200 − ₹12,000 = ₹1,200 అదనం."}}'::jsonb, null,'budget-no-cost-emi','live','ai'),
  ('budget-50-30-20-006','budget', array['50-30-20','pocket-money'], 'gold','mcq', '{"en":{"prompt":"Nikhil gets ₹4,000 a month and follows the 50-30-20 rule. He wants a ₹4,800 cycle and saves only his savings share for it. How many months will it take?","options":["4 months","8 months","12 months","6 months"],"answer":"D","explanation":"His savings share is 20% of ₹4,000 = ₹800 a month. ₹4,800 ÷ ₹800 = 6 months."},"hi":{"prompt":"निखिल को हर महीने ₹4,000 मिलते हैं और वह 50-30-20 नियम मानता है। उसे ₹4,800 की साइकिल चाहिए और इसके लिए वह सिर्फ़ अपना बचत वाला हिस्सा जोड़ता है। कितने महीने लगेंगे?","options":["4 महीने","8 महीने","12 महीने","6 महीने"],"answer":"D","explanation":"उसका बचत वाला हिस्सा ₹4,000 का 20% = हर महीने ₹800 है। ₹4,800 ÷ ₹800 = 6 महीने।"},"te":{"prompt":"నిఖిల్‌కి నెలకు ₹4,000 వస్తాయి, అతను 50-30-20 రూల్ పాటిస్తాడు. ₹4,800 సైకిల్ కొనాలనుకుంటున్నాడు, దానికోసం తన పొదుపు భాగాన్ని మాత్రమే దాచుకుంటాడు. ఎన్ని నెలలు పడుతుంది?","options":["4 నెలలు","8 నెలలు","12 నెలలు","6 నెలలు"],"answer":"D","explanation":"అతని పొదుపు భాగం ₹4,000లో 20% = నెలకు ₹800. ₹4,800 ÷ ₹800 = 6 నెలలు."}}'::jsonb, null,null,'live','ai'),
  ('budget-pocket-money-006','budget', array['pocket-money','tracking-spending'], 'gold','mcq', '{"en":{"prompt":"Anjali gets ₹2,400 for a 30-day month. On day 1 she pays ₹600 for a bus pass and ₹300 for a recharge, and saves ₹300. Spread over all 30 days, how much can she spend per day?","options":["₹50","₹40","₹60","₹80"],"answer":"B","explanation":"₹2,400 − ₹600 − ₹300 − ₹300 = ₹1,200 left. ₹1,200 ÷ 30 days = ₹40 a day."},"hi":{"prompt":"अंजलि को 30 दिन के महीने के लिए ₹2,400 मिलते हैं। पहले दिन वह ₹600 बस पास पर और ₹300 रिचार्ज पर देती है, और ₹300 बचाती है। बचे पैसे सभी 30 दिनों में बाँटें, तो वह रोज़ कितना खर्च कर सकती है?","options":["₹50","₹40","₹60","₹80"],"answer":"B","explanation":"₹2,400 − ₹600 − ₹300 − ₹300 = ₹1,200 बचे। ₹1,200 ÷ 30 दिन = रोज़ ₹40।"},"te":{"prompt":"అంజలికి 30 రోజుల నెలకు ₹2,400 వస్తాయి. మొదటి రోజు బస్ పాస్‌కి ₹600, రీచార్జ్‌కి ₹300 కట్టి, ₹300 పొదుపు చేస్తుంది. మిగిలినది 30 రోజులకు పంచితే, ఆమె రోజుకు ఎంత ఖర్చు చేయొచ్చు?","options":["₹50","₹40","₹60","₹80"],"answer":"B","explanation":"₹2,400 − ₹600 − ₹300 − ₹300 = ₹1,200 మిగులుతుంది. ₹1,200 ÷ 30 రోజులు = రోజుకు ₹40."}}'::jsonb, null,null,'live','ai'),
  ('budget-bills-and-emi-008','budget', array['bills-and-emi'], 'gold','mcq', '{"en":{"prompt":"A credit card charges 3% a month on the unpaid balance. Varun owes ₹10,000, pays nothing and spends nothing more. Ignore fees. What does he owe after 2 months?","options":["₹10,600","₹10,300","₹10,609","₹16,000"],"answer":"C","explanation":"After month 1 he owes ₹10,000 + ₹300 = ₹10,300. In month 2, 3% of ₹10,300 is ₹309, making ₹10,609, because interest is charged on interest."},"hi":{"prompt":"एक क्रेडिट कार्ड बकाया रकम पर हर महीने 3% ब्याज लेता है। वरुण पर ₹10,000 बकाया है, वह कुछ नहीं भरता और कुछ नया खर्च भी नहीं करता। फ़ीस को छोड़ दें। 2 महीने बाद उस पर कितना बकाया होगा?","options":["₹10,600","₹10,300","₹10,609","₹16,000"],"answer":"C","explanation":"पहले महीने के बाद बकाया ₹10,000 + ₹300 = ₹10,300 है। दूसरे महीने ₹10,300 का 3% यानी ₹309 जुड़कर ₹10,609 हो जाता है, क्योंकि ब्याज पर भी ब्याज लगता है।"},"te":{"prompt":"ఒక క్రెడిట్ కార్డ్ కట్టని బాకీ మీద నెలకు 3% వడ్డీ వేస్తుంది. వరుణ్ ₹10,000 బాకీ ఉన్నాడు, ఏమీ కట్టడు, కొత్తగా ఏమీ ఖర్చు చేయడు. ఫీజులు లెక్కలోకి తీసుకోవద్దు. 2 నెలల తర్వాత అతని బాకీ ఎంత?","options":["₹10,600","₹10,300","₹10,609","₹16,000"],"answer":"C","explanation":"మొదటి నెల తర్వాత బాకీ ₹10,000 + ₹300 = ₹10,300. రెండో నెలలో ₹10,300లో 3% అంటే ₹309 కలిసి ₹10,609 అవుతుంది, ఎందుకంటే వడ్డీ మీద కూడా వడ్డీ పడుతుంది."}}'::jsonb, null,'save-credit-card-trap','live','ai'),
  ('budget-bills-and-emi-009','budget', array['bills-and-emi'], 'platinum','mcq', '{"en":{"prompt":"A laptop costs ₹15,000 in cash. A \"no-cost EMI\" plan is ₹2,500 a month for 6 months plus a ₹499 processing fee. Which statement is true?","options":["Both options cost exactly the same","EMI costs ₹499 more, but you keep cash in hand longer","EMI is cheaper because you pay later","Cash costs more because you pay all at once"],"answer":"B","explanation":"₹2,500 × 6 = ₹15,000, plus the ₹499 fee makes ₹15,499. The EMI keeps money in hand for longer, but it costs more in total."},"hi":{"prompt":"एक लैपटॉप कैश में ₹15,000 का है। \"नो-कॉस्ट EMI\" प्लान में 6 महीने तक ₹2,500 महीना और ₹499 प्रोसेसिंग फ़ीस है। कौन-सी बात सही है?","options":["दोनों का खर्च बिल्कुल बराबर है","EMI ₹499 महँगी पड़ती है, पर कैश ज़्यादा समय तक हाथ में रहता है","EMI सस्ती है क्योंकि पैसा बाद में देना है","कैश महँगा है क्योंकि सारा पैसा एक साथ देना पड़ता है"],"answer":"B","explanation":"₹2,500 × 6 = ₹15,000, और ₹499 फ़ीस मिलाकर ₹15,499। EMI से पैसा ज़्यादा समय तक हाथ में रहता है, पर कुल खर्च ज़्यादा होता है।"},"te":{"prompt":"ఒక ల్యాప్‌టాప్ క్యాష్‌లో ₹15,000. \"నో-కాస్ట్ EMI\" ప్లాన్‌లో 6 నెలల పాటు నెలకు ₹2,500, దానికి తోడు ₹499 ప్రాసెసింగ్ ఫీజు. ఏది నిజం?","options":["రెండింటికీ సరిగ్గా ఒకే ఖర్చు","EMIకి ₹499 ఎక్కువ అవుతుంది, కానీ క్యాష్ ఎక్కువ కాలం చేతిలో ఉంటుంది","తర్వాత కడతాం కాబట్టి EMI చౌక","ఒకేసారి కడతాం కాబట్టి క్యాష్ ఖరీదు"],"answer":"B","explanation":"₹2,500 × 6 = ₹15,000, ₹499 ఫీజుతో కలిపి ₹15,499. EMI వల్ల డబ్బు ఎక్కువ కాలం చేతిలో ఉంటుంది, కానీ మొత్తం ఖర్చు ఎక్కువ."}}'::jsonb, null,'budget-no-cost-emi','live','ai'),
  ('budget-needs-vs-wants-009','budget', array['needs-vs-wants'], 'platinum','mcq', '{"en":{"prompt":"Meera has one free afternoon. A paid shift earns ₹900 but costs ₹150 in travel. Tutoring earns ₹650. A workshop is free. She picks the workshop. In money, what does she give up?","options":["₹650, from tutoring","₹900, the shift''s full pay","₹1,400, both jobs added together","₹750, from the best option she skipped"],"answer":"D","explanation":"Opportunity cost is the value of the best choice you give up. The shift''s net pay, ₹900 − ₹150 = ₹750, is the best she skipped."},"hi":{"prompt":"मीरा के पास एक खाली दोपहर है। एक पेड शिफ़्ट से ₹900 मिलते हैं, पर ₹150 आने-जाने में लगते हैं। ट्यूशन पढ़ाने से ₹650 मिलते हैं। एक वर्कशॉप फ़्री है। वह वर्कशॉप चुनती है। पैसों के हिसाब से वह क्या छोड़ती है?","options":["₹650, ट्यूशन वाले","₹900, शिफ़्ट की पूरी कमाई","₹1,400, दोनों काम मिलाकर","₹750, छोड़े गए सबसे अच्छे विकल्प के"],"answer":"D","explanation":"अवसर लागत (opportunity cost) उस सबसे अच्छे विकल्प की कीमत है जिसे आप छोड़ते हैं। शिफ़्ट की असली कमाई, ₹900 − ₹150 = ₹750, ही वह सबसे अच्छा विकल्प था जो उसने छोड़ा।"},"te":{"prompt":"మీరాకి ఒక ఖాళీ మధ్యాహ్నం ఉంది. ఒక పెయిడ్ షిఫ్ట్‌లో ₹900 వస్తాయి, కానీ ప్రయాణానికి ₹150 ఖర్చవుతుంది. ట్యూషన్ చెబితే ₹650 వస్తాయి. ఒక వర్క్‌షాప్ ఫ్రీ. ఆమె వర్క్‌షాప్ ఎంచుకుంటుంది. డబ్బు పరంగా ఆమె ఏం వదులుకుంటుంది?","options":["₹650, ట్యూషన్ నుంచి","₹900, షిఫ్ట్ పూర్తి జీతం","₹1,400, రెండు పనులూ కలిపి","₹750, వదులుకున్న వాటిలో అత్యుత్తమ ఆప్షన్ నుంచి"],"answer":"D","explanation":"వదులుకున్న వాటిలో అత్యుత్తమ ఎంపిక విలువనే అవకాశ వ్యయం (opportunity cost) అంటారు. షిఫ్ట్ నికర సంపాదన ₹900 − ₹150 = ₹750, ఆమె వదులుకున్న వాటిలో అదే అత్యుత్తమం."}}'::jsonb, null,null,'live','ai'),
  ('budget-bills-and-emi-010','budget', array['bills-and-emi'], 'platinum','mcq', '{"en":{"prompt":"Printing Plan A costs ₹200 a month plus ₹1 a page. Plan B costs ₹3 a page with no monthly fee. Gopal will print 60 to 90 pages a month. Which plan is cheaper?","options":["Plan B, at every amount in that range","Plan A, because ₹1 a page is lower","Plan A at 90 pages, Plan B at 60","Both cost the same at 75 pages"],"answer":"A","explanation":"At 60 pages, A costs ₹260 and B ₹180; at 90, A costs ₹290 and B ₹270. A only becomes cheaper above 100 pages, when the fixed fee is spread over more pages."},"hi":{"prompt":"प्रिंटिंग प्लान A में ₹200 महीना और ₹1 प्रति पेज लगता है। प्लान B में ₹3 प्रति पेज लगता है, कोई मासिक फ़ीस नहीं। गोपाल हर महीने 60 से 90 पेज प्रिंट करेगा। कौन-सा प्लान सस्ता है?","options":["प्लान B, इस रेंज में हर बार","प्लान A, क्योंकि ₹1 प्रति पेज कम है","90 पेज पर प्लान A, 60 पर प्लान B","75 पेज पर दोनों बराबर"],"answer":"A","explanation":"60 पेज पर A ₹260 और B ₹180 का पड़ता है; 90 पेज पर A ₹290 और B ₹270 का। A सिर्फ़ 100 पेज से ऊपर सस्ता होता है, जब तय फ़ीस ज़्यादा पेजों में बँट जाती है।"},"te":{"prompt":"ప్రింటింగ్ ప్లాన్ Aలో నెలకు ₹200, దానికి తోడు పేజీకి ₹1. ప్లాన్ Bలో పేజీకి ₹3, నెలవారీ ఫీజు లేదు. గోపాల్ నెలకు 60 నుంచి 90 పేజీలు ప్రింట్ చేస్తాడు. ఏ ప్లాన్ చౌక?","options":["ప్లాన్ B, ఈ రేంజ్‌లో ప్రతిసారీ","ప్లాన్ A, ఎందుకంటే పేజీకి ₹1 తక్కువ","90 పేజీలకు ప్లాన్ A, 60కి ప్లాన్ B","75 పేజీల దగ్గర రెండూ సమానం"],"answer":"A","explanation":"60 పేజీలకు A ₹260, B ₹180; 90 పేజీలకు A ₹290, B ₹270. ఫిక్స్‌డ్ ఫీజు ఎక్కువ పేజీలకు పంచుకున్నప్పుడు, అంటే 100 పేజీలు దాటితేనే A చౌక అవుతుంది."}}'::jsonb, null,null,'live','ai'),
  ('budget-50-30-20-007','budget', array['50-30-20','pocket-money'], 'platinum','mcq', '{"en":{"prompt":"Sana''s allowance is ₹2,000, split 50-30-20. Bus fares rise and her needs now cost ₹1,300. She wants to keep saving ₹400. What must her wants budget become?","options":["₹600","₹400","₹300","₹100"],"answer":"C","explanation":"₹2,000 − ₹1,300 needs − ₹400 savings leaves ₹300 for wants. Keeping her saving means giving up ₹300 of wants."},"hi":{"prompt":"सना का अलाउंस ₹2,000 है, जो 50-30-20 में बँटा है। बस का किराया बढ़ गया और अब उसकी ज़रूरतें ₹1,300 की हैं। वह ₹400 बचाते रहना चाहती है। उसका चाहतों का बजट कितना होना चाहिए?","options":["₹600","₹400","₹300","₹100"],"answer":"C","explanation":"₹2,000 − ₹1,300 ज़रूरतें − ₹400 बचत = चाहतों के लिए ₹300। बचत जारी रखने के लिए उसे चाहतों में से ₹300 छोड़ने होंगे।"},"te":{"prompt":"సనా అలవెన్స్ ₹2,000, దాన్ని 50-30-20 ప్రకారం పంచుతుంది. బస్ చార్జీలు పెరిగి ఇప్పుడు ఆమె అవసరాలకు ₹1,300 అవుతుంది. ఆమె ₹400 పొదుపు కొనసాగించాలనుకుంటోంది. ఆమె కోరికల బడ్జెట్ ఎంత ఉండాలి?","options":["₹600","₹400","₹300","₹100"],"answer":"C","explanation":"₹2,000 − ₹1,300 అవసరాలు − ₹400 పొదుపు = కోరికలకు ₹300. పొదుపు కొనసాగించాలంటే కోరికల్లో ₹300 వదులుకోవాలి."}}'::jsonb, null,null,'live','ai'),
  ('budget-bills-and-emi-011','budget', array['bills-and-emi'], 'platinum','mcq', '{"en":{"prompt":"Priya''s mother has an ₹8,000 card bill and ₹8,000 in her account. Paying only the minimum due would keep cash for a ₹3,000 trip. What is the main trade-off?","options":["None, because minimum due means no extra cost","The unpaid balance is charged high interest each month","Paying in full would lower her credit score","Interest starts only after one year"],"answer":"B","explanation":"Whatever is left unpaid is charged interest, often around 3% a month, so the trip ends up costing more than ₹3,000."},"hi":{"prompt":"प्रिया की माँ का कार्ड बिल ₹8,000 है और उनके खाते में ₹8,000 हैं। सिर्फ़ मिनिमम ड्यू भरने से ₹3,000 की एक ट्रिप के लिए पैसे बच जाएँगे। इसमें मुख्य ट्रेड-ऑफ़ क्या है?","options":["कोई नहीं, क्योंकि मिनिमम ड्यू का मतलब कोई एक्स्ट्रा खर्च नहीं","बची हुई बकाया रकम पर हर महीने भारी ब्याज लगता है","पूरा बिल भरने से उनका क्रेडिट स्कोर कम होगा","ब्याज सिर्फ़ एक साल बाद शुरू होता है"],"answer":"B","explanation":"जो भी रकम बिना भरे रह जाती है उस पर ब्याज लगता है, अक्सर लगभग 3% हर महीने, इसलिए ट्रिप ₹3,000 से ज़्यादा की पड़ती है।"},"te":{"prompt":"ప్రియ వాళ్ల అమ్మ కార్డ్ బిల్లు ₹8,000, ఆమె అకౌంట్‌లో ₹8,000 ఉన్నాయి. మినిమమ్ డ్యూ మాత్రమే కడితే ₹3,000 ట్రిప్ కోసం డబ్బు మిగులుతుంది. ఇందులో ముఖ్యమైన ట్రేడ్-ఆఫ్ ఏమిటి?","options":["ఏమీ లేదు, మినిమమ్ డ్యూ అంటే అదనపు ఖర్చు ఉండదు","కట్టని బాకీ మీద ప్రతి నెలా ఎక్కువ వడ్డీ పడుతుంది","పూర్తిగా కడితే ఆమె క్రెడిట్ స్కోర్ తగ్గుతుంది","వడ్డీ ఒక ఏడాది తర్వాతే మొదలవుతుంది"],"answer":"B","explanation":"కట్టకుండా మిగిలిన మొత్తం మీద వడ్డీ పడుతుంది, చాలాసార్లు నెలకు దాదాపు 3%, కాబట్టి ట్రిప్ ₹3,000 కంటే ఎక్కువ ఖర్చవుతుంది."}}'::jsonb, null,'save-credit-card-trap','live','ai'),
  ('budget-pocket-money-007','budget', array['pocket-money'], 'diamond','mcq', '{"en":{"prompt":"Nila has saved ₹1,800 for a ₹9,000 laptop she will buy in 6 months. She can save ₹900 a month in months 1–3. Assume no interest. What equal amount must she save in each of months 4–6?","options":["₹1,500","₹1,200","₹2,400","₹1,400"],"answer":"A","explanation":"She still needs ₹9,000 − ₹1,800 − ₹2,700 = ₹4,500 after month 3. ₹4,500 ÷ 3 = ₹1,500 a month."},"hi":{"prompt":"निला ने ₹9,000 के लैपटॉप के लिए ₹1,800 बचाए हैं, जिसे वह 6 महीने में खरीदेगी। महीने 1–3 में वह हर महीने ₹900 बचा सकती है। मान लो कोई ब्याज नहीं। महीने 4–6 में उसे हर महीने कितनी बराबर रकम बचानी होगी?","options":["₹1,500","₹1,200","₹2,400","₹1,400"],"answer":"A","explanation":"महीने 3 के बाद भी उसे ₹9,000 − ₹1,800 − ₹2,700 = ₹4,500 चाहिए। ₹4,500 ÷ 3 = हर महीने ₹1,500।"},"te":{"prompt":"నీల ₹9,000 ల్యాప్‌టాప్ కోసం ₹1,800 దాచుకుంది, దాన్ని 6 నెలల్లో కొంటుంది. 1–3 నెలల్లో ఆమె నెలకు ₹900 దాచగలదు. వడ్డీ లేదనుకుందాం. 4–6 నెలల్లో ప్రతి నెలా ఎంత సమానమైన మొత్తం దాచాలి?","options":["₹1,500","₹1,200","₹2,400","₹1,400"],"answer":"A","explanation":"3వ నెల తర్వాత ఇంకా ₹9,000 − ₹1,800 − ₹2,700 = ₹4,500 కావాలి. ₹4,500 ÷ 3 = నెలకు ₹1,500."}}'::jsonb, null,null,'live','ai'),
  ('budget-pocket-money-008','budget', array['pocket-money','tracking-spending'], 'diamond','mcq', '{"en":{"prompt":"Ravi has ₹900 left from last month and gets ₹7,200. He pays ₹3,100 for essentials, saves ₹1,200, pays an ₹800 fee and wants ₹1,000 left at month end. Assume 4 weeks. What is his weekly limit for other spending?","options":["₹625","₹750","₹2,000","₹500"],"answer":"D","explanation":"₹900 + ₹7,200 − ₹3,100 − ₹1,200 − ₹800 − ₹1,000 = ₹2,000. Spread over 4 weeks, that is ₹500 a week."},"hi":{"prompt":"रवि के पास पिछले महीने के ₹900 बचे हैं और उसे ₹7,200 मिलते हैं। वह ज़रूरी चीज़ों पर ₹3,100 देता है, ₹1,200 बचाता है, ₹800 की एक फ़ीस भरता है और चाहता है कि महीने के आख़िर में ₹1,000 बचे रहें। मान लो महीने में 4 हफ़्ते हैं। बाकी खर्चों के लिए उसकी हफ़्ते की लिमिट कितनी है?","options":["₹625","₹750","₹2,000","₹500"],"answer":"D","explanation":"₹900 + ₹7,200 − ₹3,100 − ₹1,200 − ₹800 − ₹1,000 = ₹2,000। इसे 4 हफ़्तों में बाँटें तो हफ़्ते के ₹500।"},"te":{"prompt":"రవి దగ్గర పోయిన నెల ₹900 మిగిలాయి, ఇప్పుడు ₹7,200 వస్తాయి. అవసరమైనవాటికి ₹3,100 కడతాడు, ₹1,200 పొదుపు చేస్తాడు, ₹800 ఫీజు కడతాడు, నెల చివర ₹1,000 మిగలాలనుకుంటాడు. నెలకు 4 వారాలు అనుకుందాం. మిగతా ఖర్చులకు వారానికి అతని లిమిట్ ఎంత?","options":["₹625","₹750","₹2,000","₹500"],"answer":"D","explanation":"₹900 + ₹7,200 − ₹3,100 − ₹1,200 − ₹800 − ₹1,000 = ₹2,000. దాన్ని 4 వారాలకు పంచితే వారానికి ₹500."}}'::jsonb, null,null,'live','ai'),
  ('budget-50-30-20-008','budget', array['50-30-20'], 'diamond','mcq', '{"en":{"prompt":"A family splits ₹30,000 a month by 50-30-20. Their income falls by 10%, but needs stay at ₹15,000. They keep saving 20% of the new income. How much is left for wants?","options":["₹8,100","₹9,000","₹6,600","₹6,000"],"answer":"C","explanation":"New income is ₹27,000 and 20% savings is ₹5,400. ₹27,000 − ₹15,000 − ₹5,400 = ₹6,600 for wants."},"hi":{"prompt":"एक परिवार हर महीने ₹30,000 को 50-30-20 से बाँटता है। उनकी आमदनी 10% घट जाती है, पर ज़रूरतें ₹15,000 ही रहती हैं। वे नई आमदनी का 20% बचाते रहते हैं। चाहतों के लिए कितना बचता है?","options":["₹8,100","₹9,000","₹6,600","₹6,000"],"answer":"C","explanation":"नई आमदनी ₹27,000 है और 20% बचत ₹5,400। ₹27,000 − ₹15,000 − ₹5,400 = चाहतों के लिए ₹6,600।"},"te":{"prompt":"ఒక కుటుంబం నెలకు ₹30,000ను 50-30-20 ప్రకారం పంచుతుంది. వాళ్ల ఆదాయం 10% తగ్గుతుంది, కానీ అవసరాలు ₹15,000 దగ్గరే ఉంటాయి. కొత్త ఆదాయంలో 20% పొదుపు చేస్తూనే ఉంటారు. కోరికలకు ఎంత మిగులుతుంది?","options":["₹8,100","₹9,000","₹6,600","₹6,000"],"answer":"C","explanation":"కొత్త ఆదాయం ₹27,000, 20% పొదుపు ₹5,400. ₹27,000 − ₹15,000 − ₹5,400 = కోరికలకు ₹6,600."}}'::jsonb, null,null,'live','ai'),
  ('budget-bills-and-emi-012','budget', array['bills-and-emi'], 'diamond','mcq', '{"en":{"prompt":"A family buys a ₹24,000 fridge on EMI: ₹2,200 a month for 12 months. They have ₹3,000 spare each month and set aside ₹500 of it for emergencies. Which is true?","options":["It costs ₹2,200 extra, and ₹800 is left monthly","It costs ₹2,400 extra, and ₹300 is left monthly","It costs ₹2,400 extra, and ₹800 is left monthly","It costs nothing extra, and ₹300 is left monthly"],"answer":"B","explanation":"₹2,200 × 12 = ₹26,400, which is ₹2,400 more than the price. Each month ₹3,000 − ₹2,200 − ₹500 leaves ₹300."},"hi":{"prompt":"एक परिवार ₹24,000 का फ़्रिज EMI पर लेता है: 12 महीने तक ₹2,200 महीना। उनके पास हर महीने ₹3,000 एक्स्ट्रा बचते हैं, जिनमें से ₹500 वे इमरजेंसी के लिए अलग रखते हैं। कौन-सी बात सही है?","options":["₹2,200 ज़्यादा लगते हैं, और हर महीने ₹800 बचते हैं","₹2,400 ज़्यादा लगते हैं, और हर महीने ₹300 बचते हैं","₹2,400 ज़्यादा लगते हैं, और हर महीने ₹800 बचते हैं","कुछ ज़्यादा नहीं लगता, और हर महीने ₹300 बचते हैं"],"answer":"B","explanation":"₹2,200 × 12 = ₹26,400, जो कीमत से ₹2,400 ज़्यादा है। हर महीने ₹3,000 − ₹2,200 − ₹500 के बाद ₹300 बचते हैं।"},"te":{"prompt":"ఒక కుటుంబం ₹24,000 ఫ్రిజ్‌ని EMIలో కొంటుంది: 12 నెలల పాటు నెలకు ₹2,200. వాళ్ల దగ్గర ప్రతి నెలా ₹3,000 అదనంగా ఉంటాయి, అందులో ₹500 ఎమర్జెన్సీల కోసం పక్కన పెడతారు. ఏది నిజం?","options":["₹2,200 అదనపు ఖర్చు, నెలకు ₹800 మిగులుతుంది","₹2,400 అదనపు ఖర్చు, నెలకు ₹300 మిగులుతుంది","₹2,400 అదనపు ఖర్చు, నెలకు ₹800 మిగులుతుంది","అదనపు ఖర్చు లేదు, నెలకు ₹300 మిగులుతుంది"],"answer":"B","explanation":"₹2,200 × 12 = ₹26,400, ఇది ధర కంటే ₹2,400 ఎక్కువ. ప్రతి నెలా ₹3,000 − ₹2,200 − ₹500 తర్వాత ₹300 మిగులుతుంది."}}'::jsonb, null,'budget-no-cost-emi','live','ai'),
  ('budget-tracking-spending-008','budget', array['tracking-spending'], 'diamond','mcq', '{"en":{"prompt":"Harsha spends ₹30 on snacks every day. Assume 30-day months. He cuts down to snacks on only 10 days a month and saves the difference for a ₹4,800 phone. How many months will it take?","options":["6 months","5 months","16 months","8 months"],"answer":"D","explanation":"Before, he spent ₹900 a month; now he spends ₹300, so he saves ₹600 a month. ₹4,800 ÷ ₹600 = 8 months."},"hi":{"prompt":"हर्षा रोज़ स्नैक्स पर ₹30 खर्च करता है। मान लो महीना 30 दिन का है। वह घटाकर महीने में सिर्फ़ 10 दिन स्नैक्स लेता है और जो फ़र्क बचता है, उसे ₹4,800 के फ़ोन के लिए जोड़ता है। कितने महीने लगेंगे?","options":["6 महीने","5 महीने","16 महीने","8 महीने"],"answer":"D","explanation":"पहले वह महीने में ₹900 खर्च करता था; अब ₹300 करता है, यानी हर महीने ₹600 बचते हैं। ₹4,800 ÷ ₹600 = 8 महीने।"},"te":{"prompt":"హర్ష రోజూ స్నాక్స్ మీద ₹30 ఖర్చు చేస్తాడు. నెలకు 30 రోజులు అనుకుందాం. అతను నెలలో 10 రోజులు మాత్రమే స్నాక్స్ తినేలా తగ్గించి, ఆ తేడా డబ్బును ₹4,800 ఫోన్ కోసం దాచుకుంటాడు. ఎన్ని నెలలు పడుతుంది?","options":["6 నెలలు","5 నెలలు","16 నెలలు","8 నెలలు"],"answer":"D","explanation":"ముందు అతను నెలకు ₹900 ఖర్చు చేసేవాడు; ఇప్పుడు ₹300, అంటే నెలకు ₹600 ఆదా. ₹4,800 ÷ ₹600 = 8 నెలలు."}}'::jsonb, null,'save-chai-math','live','ai'),
  ('invest-risk-and-return-001','invest', array['risk-and-return'], 'bronze','mcq', '{"en":{"prompt":"In investing, what does the word \"risk\" mainly mean?","options":["The chance your money''s value falls or swings","The fee a bank charges to open an account","The interest rate printed on an FD receipt","The tax taken from a person''s salary"],"answer":"A","explanation":"Risk is the chance that an investment is worth less than you hoped, or even less than you put in. Values that move up and down a lot carry more risk."},"hi":{"prompt":"निवेश में \"रिस्क\" (जोखिम) शब्द का मुख्य मतलब क्या है?","options":["आपके पैसे की वैल्यू गिरने या ऊपर-नीचे होने की संभावना","खाता खोलने के लिए बैंक जो फ़ीस लेता है","FD की रसीद पर छपी ब्याज दर","किसी व्यक्ति की सैलरी से कटने वाला टैक्स"],"answer":"A","explanation":"रिस्क यह संभावना है कि निवेश की वैल्यू आपकी उम्मीद से कम हो जाए, या आपके लगाए पैसे से भी कम। जिनकी वैल्यू बहुत ऊपर-नीचे होती है, उनमें रिस्क ज़्यादा होता है।"},"te":{"prompt":"పెట్టుబడిలో \"రిస్క్\" అనే పదానికి ముఖ్యమైన అర్థం ఏమిటి?","options":["మీ డబ్బు విలువ తగ్గే లేదా ఊగిసలాడే అవకాశం","ఖాతా తెరవడానికి బ్యాంకు వసూలు చేసే ఫీజు","FD రసీదుపై ముద్రించిన వడ్డీ రేటు","ఒక వ్యక్తి జీతం నుండి తీసుకునే పన్ను"],"answer":"A","explanation":"రిస్క్ అంటే మీ పెట్టుబడి విలువ మీరు ఆశించిన దానికంటే, లేదా మీరు పెట్టిన దానికంటే కూడా తక్కువ అయ్యే అవకాశం. విలువ ఎక్కువగా పెరుగుతూ తగ్గుతూ ఉండే వాటిలో రిస్క్ ఎక్కువ."}}'::jsonb, null,null,'live','ai'),
  ('invest-risk-and-return-002','invest', array['risk-and-return'], 'bronze','mcq', '{"en":{"prompt":"In general, how are risk and possible return linked?","options":["Higher return always comes with lower risk","Risk and return have no link at all","Low-risk options always give the highest return","Higher possible return usually comes with higher risk"],"answer":"D","explanation":"Options that could grow more are usually the ones that can also fall more. A chance of bigger reward comes with a chance of bigger loss."},"hi":{"prompt":"आम तौर पर, रिस्क और संभावित रिटर्न का आपस में क्या संबंध होता है?","options":["ज़्यादा रिटर्न हमेशा कम रिस्क के साथ आता है","रिस्क और रिटर्न का कोई संबंध नहीं है","कम रिस्क वाले विकल्प हमेशा सबसे ज़्यादा रिटर्न देते हैं","ज़्यादा संभावित रिटर्न के साथ आम तौर पर ज़्यादा रिस्क होता है"],"answer":"D","explanation":"जो विकल्प ज़्यादा बढ़ सकते हैं, वे आम तौर पर ज़्यादा गिर भी सकते हैं। बड़े फ़ायदे की संभावना के साथ बड़े नुकसान की संभावना भी आती है।"},"te":{"prompt":"సాధారణంగా, రిస్క్‌కు మరియు వచ్చే అవకాశం ఉన్న రిటర్న్‌కు మధ్య సంబంధం ఏమిటి?","options":["ఎక్కువ రిటర్న్ ఎప్పుడూ తక్కువ రిస్క్‌తో వస్తుంది","రిస్క్‌కు, రిటర్న్‌కు ఎలాంటి సంబంధం లేదు","తక్కువ రిస్క్ ఉన్న ఆప్షన్లు ఎప్పుడూ అత్యధిక రిటర్న్ ఇస్తాయి","ఎక్కువ రిటర్న్ వచ్చే అవకాశం ఉంటే సాధారణంగా రిస్క్ కూడా ఎక్కువ"],"answer":"D","explanation":"ఎక్కువగా పెరగగలిగే ఆప్షన్లే సాధారణంగా ఎక్కువగా పడిపోగలవు కూడా. పెద్ద లాభం వచ్చే అవకాశంతో పాటు పెద్ద నష్టం వచ్చే అవకాశం కూడా ఉంటుంది."}}'::jsonb, null,null,'live','ai'),
  ('invest-diversification-001','invest', array['diversification'], 'bronze','mcq', '{"en":{"prompt":"What does \"diversification\" mean when you invest money?","options":["Putting all your money in the one best option","Moving money often to chase quick gains","Spreading money across different kinds of options","Keeping all your savings as cash at home"],"answer":"C","explanation":"Diversification means not depending on just one thing. If one option does badly, the others can soften the blow."},"hi":{"prompt":"पैसा निवेश करते समय \"डाइवर्सिफ़िकेशन\" (विविधीकरण) का क्या मतलब है?","options":["सारा पैसा एक सबसे अच्छे विकल्प में लगाना","जल्दी मुनाफ़े के पीछे बार-बार पैसा इधर-उधर करना","पैसे को अलग-अलग तरह के विकल्पों में बाँटना","सारी बचत घर पर नकद रखना"],"answer":"C","explanation":"डाइवर्सिफ़िकेशन का मतलब है सिर्फ़ एक चीज़ पर निर्भर न रहना। अगर एक विकल्प खराब करे, तो बाकी विकल्प झटके को कम कर सकते हैं।"},"te":{"prompt":"డబ్బు పెట్టుబడి పెట్టేటప్పుడు \"డైవర్సిఫికేషన్\" (వైవిధ్యీకరణ) అంటే ఏమిటి?","options":["మొత్తం డబ్బును ఒకే ఉత్తమ ఆప్షన్‌లో పెట్టడం","త్వరగా లాభం కోసం డబ్బును తరచూ మారుస్తూ ఉండటం","డబ్బును వేర్వేరు రకాల ఆప్షన్లలో పంచి పెట్టడం","పొదుపు మొత్తాన్ని ఇంట్లో నగదుగా ఉంచడం"],"answer":"C","explanation":"డైవర్సిఫికేషన్ అంటే ఒకే దానిపై ఆధారపడకపోవడం. ఒక ఆప్షన్ బాగా నష్టపోయినా, మిగతావి ఆ దెబ్బను తగ్గించగలవు."}}'::jsonb, null,null,'live','ai'),
  ('invest-diversification-002','invest', array['diversification'], 'bronze','mcq', '{"en":{"prompt":"The saying \"Don''t put all your eggs in one basket\" teaches which money lesson?","options":["Always buy the cheapest thing available","Spread risk so one loss can''t wipe you out","Keep all savings in one bank account","Spend money before prices go up"],"answer":"B","explanation":"If all your money is in one place, one bad event can hurt all of it. Spreading it out limits the damage from any single loss."},"hi":{"prompt":"कहावत \"सारे अंडे एक ही टोकरी में मत रखो\" पैसे के बारे में क्या सीख देती है?","options":["हमेशा सबसे सस्ती चीज़ खरीदो","रिस्क बाँटो ताकि एक नुकसान से सब कुछ खत्म न हो जाए","सारी बचत एक ही बैंक खाते में रखो","दाम बढ़ने से पहले पैसा खर्च कर दो"],"answer":"B","explanation":"अगर आपका सारा पैसा एक ही जगह है, तो एक बुरी घटना पूरे पैसे को नुकसान पहुँचा सकती है। पैसा बाँटकर रखने से किसी एक नुकसान का असर सीमित रहता है।"},"te":{"prompt":"\"అన్ని గుడ్లను ఒకే బుట్టలో పెట్టవద్దు\" అనే సామెత డబ్బు గురించి ఏ పాఠం నేర్పుతుంది?","options":["ఎప్పుడూ దొరికే వాటిలో చౌకైనదే కొనండి","ఒక్క నష్టం మొత్తం తుడిచిపెట్టకుండా రిస్క్‌ను పంచండి","పొదుపు మొత్తాన్ని ఒకే బ్యాంకు ఖాతాలో ఉంచండి","ధరలు పెరగకముందే డబ్బు ఖర్చు పెట్టండి"],"answer":"B","explanation":"మీ డబ్బు మొత్తం ఒకే చోట ఉంటే, ఒక్క చెడు సంఘటన దాని మొత్తాన్నీ దెబ్బతీయగలదు. డబ్బును పంచి పెడితే ఏ ఒక్క నష్టం వల్ల అయినా జరిగే హాని పరిమితంగా ఉంటుంది."}}'::jsonb, null,null,'live','ai'),
  ('invest-time-horizon-001','invest', array['time-horizon'], 'bronze','mcq', '{"en":{"prompt":"What is an investment''s \"time horizon\"?","options":["The hours the bank stays open each day","How long you plan to keep the money invested","The date a company first sold its shares","The time it takes to open an account"],"answer":"B","explanation":"Time horizon is how long until you need the money. It helps decide how much up-and-down movement the money can handle."},"hi":{"prompt":"किसी निवेश का \"टाइम होराइज़न\" क्या होता है?","options":["बैंक रोज़ कितने घंटे खुला रहता है","आप पैसे को कितने समय तक निवेश में रखने की योजना बनाते हैं","वह तारीख जब किसी कंपनी ने पहली बार अपने शेयर बेचे","खाता खोलने में लगने वाला समय"],"answer":"B","explanation":"टाइम होराइज़न यह है कि आपको पैसे की ज़रूरत कितने समय बाद पड़ेगी। इससे तय करने में मदद मिलती है कि वह पैसा कितना उतार-चढ़ाव झेल सकता है।"},"te":{"prompt":"ఒక పెట్టుబడి \"టైమ్ హొరైజన్\" అంటే ఏమిటి?","options":["బ్యాంకు రోజూ ఎన్ని గంటలు తెరిచి ఉంటుందో","డబ్బును ఎంత కాలం పెట్టుబడిలో ఉంచాలని మీరు అనుకుంటున్నారో","ఒక కంపెనీ మొదటిసారి తన షేర్లు అమ్మిన తేదీ","ఖాతా తెరవడానికి పట్టే సమయం"],"answer":"B","explanation":"టైమ్ హొరైజన్ అంటే మీకు ఆ డబ్బు ఎంత కాలం తర్వాత అవసరం అవుతుందో అది. ఆ డబ్బు ఎంత ఒడిదుడుకులను తట్టుకోగలదో నిర్ణయించడానికి ఇది సహాయపడుతుంది."}}'::jsonb, null,null,'live','ai'),
  ('invest-time-horizon-002','invest', array['time-horizon','risk-and-return'], 'bronze','mcq', '{"en":{"prompt":"Why can money for a goal many years away usually handle more ups and downs?","options":["There is more time to recover from falls","Long-term options never fall in value","Prices stop changing after five years","Banks guarantee all long-term investments"],"answer":"A","explanation":"Values can fall in the short run, but a long gap before you need the money gives time for them to recover. Recovery is still not guaranteed."},"hi":{"prompt":"कई साल दूर के लक्ष्य वाला पैसा आम तौर पर ज़्यादा उतार-चढ़ाव क्यों झेल सकता है?","options":["गिरावट से संभलने के लिए ज़्यादा समय होता है","लंबे समय के विकल्पों की वैल्यू कभी नहीं गिरती","पाँच साल बाद दाम बदलना बंद हो जाते हैं","बैंक लंबे समय के सभी निवेशों की गारंटी देते हैं"],"answer":"A","explanation":"थोड़े समय में वैल्यू गिर सकती है, लेकिन पैसे की ज़रूरत पड़ने में लंबा समय हो तो उसे वापस संभलने का मौका मिलता है। फिर भी, वापस संभलने की कोई गारंटी नहीं है।"},"te":{"prompt":"చాలా సంవత్సరాల తర్వాత ఉన్న లక్ష్యం కోసం పెట్టిన డబ్బు సాధారణంగా ఎక్కువ ఒడిదుడుకులను ఎందుకు తట్టుకోగలదు?","options":["పడిపోయిన విలువ తిరిగి కోలుకోవడానికి ఎక్కువ సమయం ఉంటుంది","దీర్ఘకాలిక ఆప్షన్ల విలువ ఎప్పుడూ తగ్గదు","ఐదు సంవత్సరాల తర్వాత ధరలు మారడం ఆగిపోతుంది","బ్యాంకులు అన్ని దీర్ఘకాలిక పెట్టుబడులకు గ్యారంటీ ఇస్తాయి"],"answer":"A","explanation":"తక్కువ కాలంలో విలువ పడిపోవచ్చు, కానీ డబ్బు అవసరం అయ్యేందుకు చాలా సమయం ఉంటే అది తిరిగి కోలుకునే అవకాశం ఉంటుంది. అయినా కోలుకుంటుందని గ్యారంటీ లేదు."}}'::jsonb, null,null,'live','ai'),
  ('invest-mutual-fund-basics-001','invest', array['mutual-fund-basics'], 'bronze','mcq', '{"en":{"prompt":"What is a mutual fund, in simple words?","options":["A loan a bank gives to students","A savings account with a fixed interest rate","A government scheme that promises double money","Money pooled from many people and managed together"],"answer":"D","explanation":"A mutual fund collects money from many people and a manager invests it in many things. Its value can go up or down."},"hi":{"prompt":"आसान शब्दों में, म्यूचुअल फ़ंड क्या है?","options":["बैंक द्वारा छात्रों को दिया जाने वाला लोन","तय ब्याज दर वाला बचत खाता","सरकार की एक योजना जो पैसा दोगुना करने का वादा करती है","कई लोगों से इकट्ठा करके एक साथ संभाला जाने वाला पैसा"],"answer":"D","explanation":"म्यूचुअल फ़ंड कई लोगों से पैसा इकट्ठा करता है और एक मैनेजर उसे कई चीज़ों में निवेश करता है। इसकी वैल्यू ऊपर या नीचे जा सकती है।"},"te":{"prompt":"సులభమైన మాటల్లో, మ్యూచువల్ ఫండ్ అంటే ఏమిటి?","options":["బ్యాంకు విద్యార్థులకు ఇచ్చే లోన్","స్థిర వడ్డీ రేటు ఉన్న సేవింగ్స్ ఖాతా","డబ్బు రెట్టింపు చేస్తానని హామీ ఇచ్చే ప్రభుత్వ పథకం","చాలా మంది నుండి సేకరించి, కలిపి నిర్వహించే డబ్బు"],"answer":"D","explanation":"మ్యూచువల్ ఫండ్ చాలా మంది నుండి డబ్బు సేకరిస్తుంది, ఒక మేనేజర్ దాన్ని రకరకాల వాటిలో పెట్టుబడి పెడతారు. దాని విలువ పెరగవచ్చు లేదా తగ్గవచ్చు."}}'::jsonb, null,null,'live','ai'),
  ('invest-mutual-fund-basics-002','invest', array['mutual-fund-basics'], 'bronze','mcq', '{"en":{"prompt":"In investing, what does \"SIP\" stand for?","options":["Safe Interest Payment","Savings Insurance Policy","Systematic Investment Plan","Simple Income Profit"],"answer":"C","explanation":"SIP means Systematic Investment Plan. It is a way of putting a fixed amount into a fund at regular times, such as every month."},"hi":{"prompt":"निवेश में \"SIP\" का पूरा नाम क्या है?","options":["Safe Interest Payment","Savings Insurance Policy","Systematic Investment Plan","Simple Income Profit"],"answer":"C","explanation":"SIP का मतलब है Systematic Investment Plan (सिस्टमैटिक इन्वेस्टमेंट प्लान)। यह हर महीने जैसे नियमित समय पर किसी फ़ंड में एक तय रकम डालने का तरीका है।"},"te":{"prompt":"పెట్టుబడిలో \"SIP\" పూర్తి రూపం ఏమిటి?","options":["Safe Interest Payment","Savings Insurance Policy","Systematic Investment Plan","Simple Income Profit"],"answer":"C","explanation":"SIP అంటే Systematic Investment Plan (సిస్టమాటిక్ ఇన్వెస్ట్‌మెంట్ ప్లాన్). ప్రతి నెలా లాంటి క్రమమైన సమయాల్లో ఒక ఫండ్‌లో నిర్ణీత మొత్తాన్ని పెట్టే పద్ధతి ఇది."}}'::jsonb, null,null,'live','ai'),
  ('invest-stocks-basics-001','invest', array['stocks-basics'], 'bronze','mcq', '{"en":{"prompt":"If you own one share of a company, what do you actually own?","options":["A loan you gave to that company","A fixed deposit with that company","A small part of that company","A promise of the company''s profits"],"answer":"C","explanation":"A share is a small piece of ownership in a company. Its price can rise or fall with how the company and market do."},"hi":{"prompt":"अगर आपके पास किसी कंपनी का एक शेयर है, तो असल में आप किस चीज़ के मालिक हैं?","options":["उस कंपनी को दिया गया एक लोन","उस कंपनी के पास एक फ़िक्स्ड डिपॉज़िट","उस कंपनी का एक छोटा हिस्सा","कंपनी के मुनाफ़े का एक वादा"],"answer":"C","explanation":"शेयर किसी कंपनी में मालिकाना हक़ का एक छोटा हिस्सा है। कंपनी और बाज़ार के प्रदर्शन के हिसाब से इसका दाम बढ़ या घट सकता है।"},"te":{"prompt":"మీ దగ్గర ఒక కంపెనీ షేరు ఒకటి ఉంటే, నిజానికి మీరు దేనికి యజమాని?","options":["ఆ కంపెనీకి మీరు ఇచ్చిన లోన్","ఆ కంపెనీ దగ్గర ఉన్న ఫిక్స్‌డ్ డిపాజిట్","ఆ కంపెనీలో ఒక చిన్న భాగం","కంపెనీ లాభాలు ఇస్తామనే హామీ"],"answer":"C","explanation":"షేరు అంటే ఒక కంపెనీ యాజమాన్యంలో ఒక చిన్న భాగం. కంపెనీ, మార్కెట్ ఎలా నడుస్తాయో దాన్ని బట్టి దాని ధర పెరగవచ్చు లేదా తగ్గవచ్చు."}}'::jsonb, null,null,'live','ai'),
  ('invest-stocks-basics-002','invest', array['stocks-basics'], 'bronze','mcq', '{"en":{"prompt":"Can a company''s share price fall below the price you paid for it?","options":["No, share prices only rise over time","Yes, share prices can go down as well as up","No, the government fixes all share prices","Only if the company shuts down completely"],"answer":"B","explanation":"Share prices change every day based on buying and selling. They can fall below your buying price, so a loss is possible."},"hi":{"prompt":"क्या किसी कंपनी के शेयर का दाम आपके खरीदे गए दाम से नीचे जा सकता है?","options":["नहीं, शेयर के दाम समय के साथ सिर्फ़ बढ़ते हैं","हाँ, शेयर के दाम ऊपर के साथ-साथ नीचे भी जा सकते हैं","नहीं, सरकार सभी शेयरों के दाम तय करती है","सिर्फ़ तब, जब कंपनी पूरी तरह बंद हो जाए"],"answer":"B","explanation":"शेयरों के दाम खरीद-बिक्री के आधार पर हर दिन बदलते हैं। वे आपके खरीदे दाम से नीचे जा सकते हैं, इसलिए नुकसान हो सकता है।"},"te":{"prompt":"ఒక కంపెనీ షేరు ధర మీరు కొన్న ధర కంటే తగ్గిపోగలదా?","options":["లేదు, కాలం గడిచే కొద్దీ షేరు ధరలు పెరుగుతాయి మాత్రమే","అవును, షేరు ధరలు పెరగనూ వచ్చు, తగ్గనూ వచ్చు","లేదు, అన్ని షేరు ధరలను ప్రభుత్వం నిర్ణయిస్తుంది","కంపెనీ పూర్తిగా మూతపడితే మాత్రమే"],"answer":"B","explanation":"కొనడం, అమ్మడం బట్టి షేరు ధరలు ప్రతిరోజూ మారుతాయి. అవి మీరు కొన్న ధర కంటే తగ్గవచ్చు, కాబట్టి నష్టం రావచ్చు."}}'::jsonb, null,null,'live','ai'),
  ('invest-gold-and-fd-001','invest', array['gold-and-fd'], 'bronze','mcq', '{"en":{"prompt":"Gold prices go up and down from day to day. What does this mean for someone who owns gold?","options":["Its value can rise or fall over time","Its value can only go up","It pays a fixed interest every month","It works exactly like cash in a bank"],"answer":"A","explanation":"Gold pays no fixed interest, and its price changes with demand. Its value can fall as well as rise."},"hi":{"prompt":"सोने के दाम रोज़ ऊपर-नीचे होते हैं। जिसके पास सोना है, उसके लिए इसका क्या मतलब है?","options":["समय के साथ इसकी वैल्यू बढ़ या घट सकती है","इसकी वैल्यू सिर्फ़ बढ़ सकती है","यह हर महीने तय ब्याज देता है","यह बिल्कुल बैंक में रखे नकद पैसे की तरह काम करता है"],"answer":"A","explanation":"सोना कोई तय ब्याज नहीं देता, और इसका दाम माँग के हिसाब से बदलता है। इसकी वैल्यू बढ़ भी सकती है और घट भी सकती है।"},"te":{"prompt":"బంగారం ధరలు రోజురోజుకూ పెరుగుతూ తగ్గుతూ ఉంటాయి. బంగారం ఉన్నవారికి దీని అర్థం ఏమిటి?","options":["కాలక్రమంలో దాని విలువ పెరగవచ్చు లేదా తగ్గవచ్చు","దాని విలువ పెరగడం మాత్రమే జరుగుతుంది","అది ప్రతి నెలా స్థిరమైన వడ్డీ ఇస్తుంది","అది అచ్చం బ్యాంకులో ఉన్న నగదు లాగే పనిచేస్తుంది"],"answer":"A","explanation":"బంగారం స్థిరమైన వడ్డీ ఏమీ ఇవ్వదు, దాని ధర డిమాండ్‌ను బట్టి మారుతుంది. దాని విలువ పెరగనూ వచ్చు, తగ్గనూ వచ్చు."}}'::jsonb, null,null,'live','ai'),
  ('invest-gold-and-fd-002','invest', array['gold-and-fd'], 'bronze','mcq', '{"en":{"prompt":"Which statement about the price of gold is true?","options":["It only ever goes up each year","The bank fixes it once every year","It stays the same for ten years at a time","It goes up and down; it is not fixed"],"answer":"D","explanation":"Gold''s price changes with demand and world events. It can fall as well as rise."},"hi":{"prompt":"सोने के दाम के बारे में कौन-सी बात सही है?","options":["यह हर साल सिर्फ़ बढ़ता ही है","बैंक इसे साल में एक बार तय करता है","यह दस-दस साल तक एक जैसा रहता है","यह ऊपर-नीचे होता है; यह तय नहीं है"],"answer":"D","explanation":"सोने का दाम माँग और दुनिया की घटनाओं के हिसाब से बदलता है। यह बढ़ भी सकता है और घट भी सकता है।"},"te":{"prompt":"బంగారం ధర గురించి ఏ వాక్యం నిజం?","options":["అది ప్రతి సంవత్సరం పెరుగుతుంది మాత్రమే","బ్యాంకు దాన్ని సంవత్సరానికి ఒకసారి నిర్ణయిస్తుంది","అది ఒకేసారి పది సంవత్సరాల పాటు మారకుండా ఉంటుంది","అది పెరుగుతూ తగ్గుతూ ఉంటుంది; స్థిరంగా ఉండదు"],"answer":"D","explanation":"డిమాండ్, ప్రపంచంలో జరిగే సంఘటనలను బట్టి బంగారం ధర మారుతుంది. అది పెరగనూ వచ్చు, తగ్గనూ వచ్చు."}}'::jsonb, null,null,'live','ai'),
  ('invest-gold-and-fd-003','invest', array['gold-and-fd','risk-and-return'], 'bronze','mcq', '{"en":{"prompt":"Compared with shares, why is a bank FD usually called lower risk?","options":["It always earns more than shares","Its value rises whenever markets rise","It has no rules about taking money out","Its interest rate is fixed when you open it"],"answer":"D","explanation":"An FD''s rate is agreed at the start, so you know what it will pay. Share prices move every day, so their value is less certain."},"hi":{"prompt":"शेयरों की तुलना में, बैंक FD को आम तौर पर कम रिस्क वाला क्यों कहा जाता है?","options":["यह हमेशा शेयरों से ज़्यादा कमाती है","जब भी बाज़ार बढ़ता है, इसकी वैल्यू बढ़ती है","इसमें पैसा निकालने के कोई नियम नहीं हैं","इसे खोलते समय ही इसकी ब्याज दर तय हो जाती है"],"answer":"D","explanation":"FD की दर शुरू में ही तय हो जाती है, इसलिए आपको पता होता है कि यह कितना देगी। शेयरों के दाम हर दिन बदलते हैं, इसलिए उनकी वैल्यू उतनी पक्की नहीं होती।"},"te":{"prompt":"షేర్లతో పోలిస్తే, బ్యాంకు FDని సాధారణంగా తక్కువ రిస్క్ అని ఎందుకు అంటారు?","options":["అది ఎప్పుడూ షేర్ల కంటే ఎక్కువ సంపాదిస్తుంది","మార్కెట్లు పెరిగినప్పుడల్లా దాని విలువ పెరుగుతుంది","డబ్బు తీసుకోవడానికి దానికి ఎలాంటి నియమాలు లేవు","దాన్ని తెరిచినప్పుడే దాని వడ్డీ రేటు స్థిరపడుతుంది"],"answer":"D","explanation":"FD రేటు మొదట్లోనే ఒప్పుకున్నది కాబట్టి, అది ఎంత ఇస్తుందో మీకు ముందే తెలుస్తుంది. షేరు ధరలు ప్రతిరోజూ మారుతాయి, కాబట్టి వాటి విలువ అంత ఖచ్చితంగా ఉండదు."}}'::jsonb, null,null,'live','ai'),
  ('invest-mutual-fund-basics-003','invest', array['mutual-fund-basics','diversification'], 'bronze','mcq', '{"en":{"prompt":"Why does one mutual fund usually hold shares of many different companies?","options":["So the fund can promise fixed returns","So investors never pay any charges","So one company''s fall hurts the fund less","So the fund''s value can never go down"],"answer":"C","explanation":"Holding many companies spreads risk, so one bad company has a smaller effect. The fund''s value can still go down."},"hi":{"prompt":"एक म्यूचुअल फ़ंड आम तौर पर कई अलग-अलग कंपनियों के शेयर क्यों रखता है?","options":["ताकि फ़ंड तय रिटर्न का वादा कर सके","ताकि निवेशकों को कभी कोई चार्ज न देना पड़े","ताकि एक कंपनी के गिरने से फ़ंड को कम नुकसान हो","ताकि फ़ंड की वैल्यू कभी नीचे न जा सके"],"answer":"C","explanation":"कई कंपनियों में पैसा रखने से रिस्क बँट जाता है, इसलिए एक खराब कंपनी का असर कम होता है। फिर भी फ़ंड की वैल्यू नीचे जा सकती है।"},"te":{"prompt":"ఒక మ్యూచువల్ ఫండ్ సాధారణంగా చాలా వేర్వేరు కంపెనీల షేర్లను ఎందుకు కలిగి ఉంటుంది?","options":["ఫండ్ స్థిరమైన రిటర్న్‌కు హామీ ఇవ్వగలిగేలా","పెట్టుబడిదారులు ఎప్పుడూ ఏ ఛార్జీలూ కట్టనవసరం లేకుండా","ఒక కంపెనీ పడిపోయినా ఫండ్‌కు తక్కువ నష్టం కలిగేలా","ఫండ్ విలువ ఎప్పటికీ తగ్గకుండా"],"answer":"C","explanation":"చాలా కంపెనీల్లో పెట్టడం వల్ల రిస్క్ పంచబడుతుంది, కాబట్టి ఒక చెడ్డ కంపెనీ ప్రభావం తక్కువగా ఉంటుంది. అయినా ఫండ్ విలువ తగ్గవచ్చు."}}'::jsonb, null,null,'live','ai'),
  ('invest-risk-and-return-003','invest', array['risk-and-return'], 'bronze','mcq', '{"en":{"prompt":"What is \"survivorship bias\" in stories about money?","options":["Saving money to survive emergencies","Hearing only from winners, not from people who lost","Choosing safe options to avoid every loss","Believing old companies can never fail"],"answer":"B","explanation":"People who made money share their stories, while those who lost often stay quiet. So risky bets can look safer than they really are."},"hi":{"prompt":"पैसे से जुड़ी कहानियों में \"सर्वाइवरशिप बायस\" क्या है?","options":["इमरजेंसी में काम आने के लिए पैसे बचाना","सिर्फ़ जीतने वालों की बातें सुनना, हारने वालों की नहीं","हर नुकसान से बचने के लिए सुरक्षित विकल्प चुनना","यह मानना कि पुरानी कंपनियाँ कभी फ़ेल नहीं हो सकतीं"],"answer":"B","explanation":"जिन लोगों ने पैसा कमाया, वे अपनी कहानियाँ सुनाते हैं, जबकि जिन्होंने गँवाया, वे अक्सर चुप रहते हैं। इसलिए जोखिम भरे दाँव असल से ज़्यादा सुरक्षित लगने लगते हैं।"},"te":{"prompt":"డబ్బు గురించిన కథల్లో \"సర్వైవర్‌షిప్ బయాస్\" అంటే ఏమిటి?","options":["అత్యవసర పరిస్థితుల్లో నెట్టుకురావడానికి డబ్బు పొదుపు చేయడం","గెలిచినవాళ్ల మాటలు మాత్రమే వినడం, నష్టపోయినవాళ్లవి కాదు","ప్రతి నష్టాన్నీ తప్పించుకోవడానికి సురక్షితమైన ఆప్షన్లు ఎంచుకోవడం","పాత కంపెనీలు ఎప్పటికీ విఫలం కావని నమ్మడం"],"answer":"B","explanation":"డబ్బు సంపాదించినవాళ్లు తమ కథలు చెప్పుకుంటారు, నష్టపోయినవాళ్లు తరచూ మౌనంగా ఉంటారు. అందుకే రిస్క్ ఉన్న పందేలు నిజంగా ఉన్నదానికంటే సురక్షితంగా కనిపిస్తాయి."}}'::jsonb, null,null,'live','ai'),
  ('invest-time-horizon-003','invest', array['time-horizon','risk-and-return'], 'silver','mcq', '{"en":{"prompt":"Shreya needs ₹5,000 for exam fees in two months. Why could a high-risk option be a poor fit for this money?","options":["Its value could be down when she needs it","Risky options cannot be sold for a year","Exam fees cannot be paid from investments","Risky options always lose money in two months"],"answer":"A","explanation":"In a short time, a risky option may be below what she put in. She would then have less than ₹5,000 for her fees."},"hi":{"prompt":"श्रेया को दो महीने में परीक्षा फ़ीस के लिए ₹5,000 चाहिए। इस पैसे के लिए ज़्यादा रिस्क वाला विकल्प ठीक क्यों नहीं हो सकता?","options":["जब उसे ज़रूरत हो, तब इसकी वैल्यू घटी हुई हो सकती है","रिस्क वाले विकल्प एक साल तक बेचे नहीं जा सकते","परीक्षा फ़ीस निवेश से नहीं भरी जा सकती","रिस्क वाले विकल्प दो महीने में हमेशा पैसा गँवाते हैं"],"answer":"A","explanation":"थोड़े समय में, रिस्क वाले विकल्प की वैल्यू उसके लगाए पैसे से कम हो सकती है। तब उसके पास फ़ीस के लिए ₹5,000 से कम होंगे।"},"te":{"prompt":"శ్రేయకు రెండు నెలల్లో పరీక్ష ఫీజు కోసం ₹5,000 కావాలి. ఈ డబ్బుకు ఎక్కువ రిస్క్ ఉన్న ఆప్షన్ ఎందుకు సరిపోకపోవచ్చు?","options":["ఆమెకు అవసరమైనప్పుడు దాని విలువ తగ్గి ఉండవచ్చు","రిస్క్ ఉన్న ఆప్షన్లను ఒక సంవత్సరం వరకు అమ్మలేరు","పరీక్ష ఫీజును పెట్టుబడుల నుండి కట్టలేరు","రిస్క్ ఉన్న ఆప్షన్లు రెండు నెలల్లో ఎప్పుడూ నష్టపోతాయి"],"answer":"A","explanation":"తక్కువ సమయంలో, రిస్క్ ఉన్న ఆప్షన్ విలువ ఆమె పెట్టిన దానికంటే తక్కువగా ఉండవచ్చు. అప్పుడు ఫీజుకు ఆమె దగ్గర ₹5,000 కంటే తక్కువ ఉంటుంది."}}'::jsonb, null,null,'live','ai'),
  ('invest-diversification-003','invest', array['diversification'], 'silver','mcq', '{"en":{"prompt":"Arjun''s uncle keeps all his savings in shares of the one company he works for. What is the main danger?","options":["If it struggles, he may lose job and savings together","Shares of your own company cannot be sold","He will pay double tax on those shares","There is no danger if he trusts the company"],"answer":"A","explanation":"His salary and his savings both depend on the same company. One bad event could hit both at once."},"hi":{"prompt":"अर्जुन के चाचा अपनी सारी बचत उसी एक कंपनी के शेयरों में रखते हैं जहाँ वे काम करते हैं। सबसे बड़ा खतरा क्या है?","options":["अगर कंपनी मुश्किल में आई, तो नौकरी और बचत दोनों एक साथ जा सकती हैं","अपनी कंपनी के शेयर बेचे नहीं जा सकते","उन्हें उन शेयरों पर दोगुना टैक्स देना होगा","अगर उन्हें कंपनी पर भरोसा है तो कोई खतरा नहीं"],"answer":"A","explanation":"उनकी सैलरी और उनकी बचत दोनों एक ही कंपनी पर निर्भर हैं। एक बुरी घटना दोनों पर एक साथ चोट कर सकती है।"},"te":{"prompt":"అర్జున్ బాబాయి తన పొదుపు మొత్తాన్నీ తను పనిచేసే ఒకే కంపెనీ షేర్లలో పెట్టారు. ప్రధాన ప్రమాదం ఏమిటి?","options":["కంపెనీ కష్టాల్లో పడితే, ఉద్యోగం, పొదుపు రెండూ ఒకేసారి పోవచ్చు","సొంత కంపెనీ షేర్లను అమ్మలేరు","ఆ షేర్లపై ఆయన రెట్టింపు పన్ను కట్టాలి","కంపెనీని నమ్మితే ఎలాంటి ప్రమాదం లేదు"],"answer":"A","explanation":"ఆయన జీతం, పొదుపు రెండూ ఒకే కంపెనీపై ఆధారపడి ఉన్నాయి. ఒక్క చెడు సంఘటన రెండింటినీ ఒకేసారి దెబ్బతీయగలదు."}}'::jsonb, null,null,'live','ai'),
  ('invest-risk-and-return-004','invest', array['risk-and-return'], 'silver','mcq', '{"en":{"prompt":"A message says: \"Invest ₹1,000, get ₹2,000 in one week, zero risk!\" What does the risk-return idea tell you?","options":["It is fine if a friend has already tried it","One week is enough time to double money safely","Small amounts like ₹1,000 carry no risk","High return with no risk is a big warning sign"],"answer":"D","explanation":"Big returns always come with big risk, so a promise of both is not believable. Such offers are often scams."},"hi":{"prompt":"एक मैसेज में लिखा है: \"₹1,000 लगाओ, एक हफ़्ते में ₹2,000 पाओ, ज़ीरो रिस्क!\" रिस्क-रिटर्न का सिद्धांत आपको क्या बताता है?","options":["अगर किसी दोस्त ने आज़माया है तो ठीक है","पैसा सुरक्षित तरीके से दोगुना करने के लिए एक हफ़्ता काफ़ी है","₹1,000 जैसी छोटी रकम में कोई रिस्क नहीं होता","बिना रिस्क के ज़्यादा रिटर्न एक बड़ा खतरे का संकेत है"],"answer":"D","explanation":"बड़े रिटर्न के साथ हमेशा बड़ा रिस्क आता है, इसलिए दोनों का एक साथ वादा भरोसे लायक नहीं है। ऐसे ऑफ़र अक्सर धोखाधड़ी (स्कैम) होते हैं।"},"te":{"prompt":"ఒక మెసేజ్‌లో ఇలా ఉంది: \"₹1,000 పెట్టండి, ఒక వారంలో ₹2,000 పొందండి, జీరో రిస్క్!\" రిస్క్-రిటర్న్ ఆలోచన మీకు ఏం చెబుతుంది?","options":["ఒక స్నేహితుడు ఇప్పటికే ప్రయత్నించి ఉంటే పర్వాలేదు","డబ్బును సురక్షితంగా రెట్టింపు చేయడానికి ఒక వారం చాలు","₹1,000 లాంటి చిన్న మొత్తాలకు రిస్క్ ఉండదు","రిస్క్ లేకుండా ఎక్కువ రిటర్న్ అంటే అది పెద్ద హెచ్చరిక సంకేతం"],"answer":"D","explanation":"పెద్ద రిటర్న్‌తో ఎప్పుడూ పెద్ద రిస్క్ వస్తుంది, కాబట్టి రెండింటినీ కలిపి ఇస్తామన్న హామీ నమ్మదగినది కాదు. ఇలాంటి ఆఫర్లు తరచూ మోసాలు (స్కామ్‌లు)."}}'::jsonb, null,null,'live','ai'),
  ('invest-stocks-basics-003','invest', array['stocks-basics'], 'silver','mcq', '{"en":{"prompt":"Kiran''s friend says a share \"will surely go up\" because it rose a lot last month. What is wrong with this thinking?","options":["Shares that rise must fall the next month","Share prices change only once a year","Past rises do not guarantee future rises","Prices rise only when profits are paid out"],"answer":"C","explanation":"A share''s past movement does not decide what happens next. Nobody can be sure a price will rise."},"hi":{"prompt":"किरण का दोस्त कहता है कि एक शेयर \"पक्का ऊपर जाएगा\", क्योंकि पिछले महीने वह बहुत बढ़ा था। इस सोच में क्या गलत है?","options":["जो शेयर बढ़ते हैं, वे अगले महीने ज़रूर गिरते हैं","शेयर के दाम साल में सिर्फ़ एक बार बदलते हैं","पहले बढ़ने का मतलब यह गारंटी नहीं कि आगे भी बढ़ेगा","दाम तभी बढ़ते हैं जब मुनाफ़ा बाँटा जाता है"],"answer":"C","explanation":"किसी शेयर की पिछली चाल से तय नहीं होता कि आगे क्या होगा। कोई भी पक्का नहीं कह सकता कि दाम बढ़ेगा।"},"te":{"prompt":"ఒక షేరు గత నెల బాగా పెరిగింది కాబట్టి అది \"ఖచ్చితంగా పెరుగుతుంది\" అని కిరణ్ స్నేహితుడు అంటున్నాడు. ఈ ఆలోచనలో తప్పు ఏమిటి?","options":["పెరిగిన షేర్లు తర్వాతి నెల తప్పకుండా పడిపోతాయి","షేరు ధరలు సంవత్సరానికి ఒకసారి మాత్రమే మారుతాయి","గతంలో పెరిగినంత మాత్రాన భవిష్యత్తులో పెరుగుతుందని గ్యారంటీ లేదు","లాభాలు పంచినప్పుడు మాత్రమే ధరలు పెరుగుతాయి"],"answer":"C","explanation":"ఒక షేరు గతంలో ఎలా కదిలిందో దాన్ని బట్టి తర్వాత ఏం జరుగుతుందో నిర్ణయం కాదు. ధర పెరుగుతుందని ఎవరూ ఖచ్చితంగా చెప్పలేరు."}}'::jsonb, null,null,'live','ai'),
  ('invest-mutual-fund-basics-004','invest', array['mutual-fund-basics'], 'silver','mcq', '{"en":{"prompt":"Fatima puts ₹500 into a mutual fund on the 5th of every month. What is this regular way of investing called?","options":["A lump-sum fixed deposit","A SIP (Systematic Investment Plan)","A monthly loan EMI","A one-time share purchase"],"answer":"B","explanation":"Putting a fixed amount into a fund at regular times is a SIP. A lump sum is a single large payment, and an EMI repays a loan."},"hi":{"prompt":"फ़ातिमा हर महीने की 5 तारीख को एक म्यूचुअल फ़ंड में ₹500 डालती है। निवेश के इस नियमित तरीके को क्या कहते हैं?","options":["एकमुश्त (लम्प सम) फ़िक्स्ड डिपॉज़िट","SIP (सिस्टमैटिक इन्वेस्टमेंट प्लान)","लोन की मासिक EMI","एक बार में शेयर खरीदना"],"answer":"B","explanation":"नियमित समय पर किसी फ़ंड में तय रकम डालना SIP कहलाता है। एकमुश्त का मतलब एक ही बार में बड़ी रकम देना है, और EMI से लोन चुकाया जाता है।"},"te":{"prompt":"ఫాతిమా ప్రతి నెలా 5వ తేదీన ఒక మ్యూచువల్ ఫండ్‌లో ₹500 పెడుతుంది. ఇలా క్రమం తప్పకుండా పెట్టుబడి పెట్టే పద్ధతిని ఏమంటారు?","options":["ఒకేసారి పెట్టే (లంప్-సమ్) ఫిక్స్‌డ్ డిపాజిట్","SIP (సిస్టమాటిక్ ఇన్వెస్ట్‌మెంట్ ప్లాన్)","నెలవారీ లోన్ EMI","ఒక్కసారి షేర్లు కొనడం"],"answer":"B","explanation":"క్రమమైన సమయాల్లో ఒక ఫండ్‌లో నిర్ణీత మొత్తం పెట్టడాన్ని SIP అంటారు. లంప్-సమ్ అంటే ఒకేసారి పెద్ద మొత్తం కట్టడం, EMI అంటే లోన్ తిరిగి చెల్లించడం."}}'::jsonb, null,null,'live','ai'),
  ('invest-time-horizon-004','invest', array['time-horizon'], 'silver','mcq', '{"en":{"prompt":"Rahul is saving for a goal 10 years away. Ananya is saving for a phone in 6 months. Who can better handle short-term ups and downs?","options":["Ananya, because her amount is smaller","Rahul, because he has more time to recover","Both equally, since time does not matter","Neither, because values never change"],"answer":"B","explanation":"Rahul will not need his money for years, so a fall today has time to recover. Ananya needs hers soon, so a fall could leave her short."},"hi":{"prompt":"राहुल 10 साल बाद के एक लक्ष्य के लिए बचत कर रहा है। अनन्या 6 महीने में फ़ोन खरीदने के लिए बचत कर रही है। थोड़े समय के उतार-चढ़ाव को कौन बेहतर झेल सकता है?","options":["अनन्या, क्योंकि उसकी रकम छोटी है","राहुल, क्योंकि उसके पास संभलने के लिए ज़्यादा समय है","दोनों बराबर, क्योंकि समय से कोई फ़र्क नहीं पड़ता","कोई नहीं, क्योंकि वैल्यू कभी बदलती ही नहीं"],"answer":"B","explanation":"राहुल को सालों तक अपने पैसे की ज़रूरत नहीं है, इसलिए आज की गिरावट को संभलने का समय मिलेगा। अनन्या को जल्दी पैसा चाहिए, इसलिए गिरावट से उसके पैसे कम पड़ सकते हैं।"},"te":{"prompt":"రాహుల్ 10 సంవత్సరాల తర్వాతి లక్ష్యం కోసం పొదుపు చేస్తున్నాడు. అనన్య 6 నెలల్లో ఫోన్ కొనడానికి పొదుపు చేస్తోంది. తక్కువ కాలపు ఒడిదుడుకులను ఎవరు బాగా తట్టుకోగలరు?","options":["అనన్య, ఎందుకంటే ఆమె మొత్తం చిన్నది","రాహుల్, ఎందుకంటే కోలుకోవడానికి అతనికి ఎక్కువ సమయం ఉంది","ఇద్దరూ సమానంగా, ఎందుకంటే సమయం ముఖ్యం కాదు","ఎవరూ కాదు, ఎందుకంటే విలువలు ఎప్పుడూ మారవు"],"answer":"B","explanation":"రాహుల్‌కు చాలా సంవత్సరాల వరకు డబ్బు అవసరం లేదు, కాబట్టి ఈరోజు పడిపోయినా కోలుకోవడానికి సమయం ఉంటుంది. అనన్యకు డబ్బు త్వరలోనే కావాలి, కాబట్టి విలువ పడిపోతే ఆమెకు డబ్బు తక్కువ పడవచ్చు."}}'::jsonb, null,null,'live','ai'),
  ('invest-diversification-004','invest', array['diversification'], 'silver','mcq', '{"en":{"prompt":"Meena sells only tea at her stall. Her neighbour sells tea, snacks and juice. In a month when tea sales drop, who is likely hurt more?","options":["Meena, because all her income depends on tea","The neighbour, because she has more to manage","Both equally, since tea sales fell for both","Neither, because stalls always earn the same"],"answer":"A","explanation":"Meena has only one source of income, so a fall in tea sales hits all of it. Her neighbour still earns from snacks and juice."},"hi":{"prompt":"मीना अपने स्टॉल पर सिर्फ़ चाय बेचती है। उसकी पड़ोसन चाय, नाश्ता और जूस बेचती है। जिस महीने चाय की बिक्री घटती है, किसका नुकसान ज़्यादा होने की संभावना है?","options":["मीना का, क्योंकि उसकी पूरी कमाई चाय पर टिकी है","पड़ोसन का, क्योंकि उसे ज़्यादा चीज़ें संभालनी पड़ती हैं","दोनों का बराबर, क्योंकि दोनों की चाय की बिक्री घटी","किसी का नहीं, क्योंकि स्टॉल हमेशा एक जितना कमाते हैं"],"answer":"A","explanation":"मीना की कमाई का सिर्फ़ एक ही ज़रिया है, इसलिए चाय की बिक्री घटने से उसकी पूरी कमाई पर असर पड़ता है। उसकी पड़ोसन अब भी नाश्ते और जूस से कमाती है।"},"te":{"prompt":"మీనా తన స్టాల్‌లో టీ మాత్రమే అమ్ముతుంది. ఆమె పక్కింటావిడ టీ, స్నాక్స్, జ్యూస్ అమ్ముతుంది. టీ అమ్మకాలు తగ్గిన నెలలో ఎవరికి ఎక్కువ నష్టం జరిగే అవకాశం ఉంది?","options":["మీనాకు, ఎందుకంటే ఆమె ఆదాయం మొత్తం టీ మీదే ఆధారపడి ఉంది","పక్కింటావిడకు, ఎందుకంటే ఆమె ఎక్కువ వాటిని చూసుకోవాలి","ఇద్దరికీ సమానంగా, ఎందుకంటే ఇద్దరికీ టీ అమ్మకాలు తగ్గాయి","ఎవరికీ కాదు, ఎందుకంటే స్టాల్స్ ఎప్పుడూ ఒకేలా సంపాదిస్తాయి"],"answer":"A","explanation":"మీనాకు ఆదాయం ఒకే మార్గం నుండి వస్తుంది, కాబట్టి టీ అమ్మకాలు తగ్గితే ఆమె ఆదాయం మొత్తం దెబ్బతింటుంది. ఆమె పక్కింటావిడకు ఇంకా స్నాక్స్, జ్యూస్ నుండి ఆదాయం వస్తుంది."}}'::jsonb, null,null,'live','ai'),
  ('invest-gold-and-fd-004','invest', array['gold-and-fd'], 'silver','mcq', '{"en":{"prompt":"Sunita''s grandmother says, \"Gold never loses value.\" Which statement is more accurate?","options":["Gold rises by a fixed amount every year","Banks guarantee the value of gold","Gold loses value only when made into jewellery","Gold prices can fall too, sometimes for years"],"answer":"D","explanation":"Gold''s price moves with demand and world events. It has had long periods of falling or flat prices."},"hi":{"prompt":"सुनीता की दादी कहती हैं, \"सोने की वैल्यू कभी नहीं घटती।\" कौन-सी बात ज़्यादा सही है?","options":["सोना हर साल एक तय मात्रा में बढ़ता है","बैंक सोने की वैल्यू की गारंटी देते हैं","सोना तभी वैल्यू खोता है जब उसके गहने बनते हैं","सोने के दाम भी गिर सकते हैं, कभी-कभी सालों तक"],"answer":"D","explanation":"सोने का दाम माँग और दुनिया की घटनाओं के साथ बदलता है। कई बार लंबे समय तक इसके दाम गिरे हैं या वहीं के वहीं रहे हैं।"},"te":{"prompt":"సునీత నానమ్మ \"బంగారం విలువ ఎప్పుడూ తగ్గదు\" అంటుంది. ఏ వాక్యం ఎక్కువ సరైనది?","options":["బంగారం ప్రతి సంవత్సరం ఒక నిర్ణీత మొత్తంలో పెరుగుతుంది","బంగారం విలువకు బ్యాంకులు గ్యారంటీ ఇస్తాయి","బంగారాన్ని నగలుగా చేసినప్పుడు మాత్రమే అది విలువ కోల్పోతుంది","బంగారం ధరలు కూడా పడిపోవచ్చు, కొన్నిసార్లు సంవత్సరాల పాటు"],"answer":"D","explanation":"డిమాండ్, ప్రపంచ సంఘటనలను బట్టి బంగారం ధర మారుతుంది. చాలా కాలం పాటు దాని ధరలు పడిపోయిన లేదా పెరగకుండా ఉన్న సందర్భాలు ఉన్నాయి."}}'::jsonb, null,null,'live','ai'),
  ('invest-mutual-fund-basics-005','invest', array['mutual-fund-basics','risk-and-return'], 'silver','mcq', '{"en":{"prompt":"A fund advert says, \"Mutual fund investments are subject to market risks.\" What does this mean?","options":["The fund promises you a fixed yearly return","Only the fund manager can lose money","Your money''s value can go down as well as up","Your money can never be taken out"],"answer":"C","explanation":"A fund''s value follows the market, so it can fall. That warning reminds investors that returns are not promised."},"hi":{"prompt":"एक फ़ंड के विज्ञापन में लिखा है, \"म्यूचुअल फ़ंड निवेश बाज़ार के जोखिमों के अधीन हैं।\" इसका क्या मतलब है?","options":["फ़ंड आपको हर साल तय रिटर्न का वादा करता है","सिर्फ़ फ़ंड मैनेजर का पैसा डूब सकता है","आपके पैसे की वैल्यू ऊपर के साथ-साथ नीचे भी जा सकती है","आपका पैसा कभी निकाला नहीं जा सकता"],"answer":"C","explanation":"फ़ंड की वैल्यू बाज़ार के साथ चलती है, इसलिए यह गिर सकती है। यह चेतावनी निवेशकों को याद दिलाती है कि रिटर्न का कोई वादा नहीं है।"},"te":{"prompt":"ఒక ఫండ్ ప్రకటనలో \"మ్యూచువల్ ఫండ్ పెట్టుబడులు మార్కెట్ రిస్క్‌లకు లోబడి ఉంటాయి\" అని ఉంది. దీని అర్థం ఏమిటి?","options":["ఫండ్ మీకు ప్రతి సంవత్సరం స్థిరమైన రిటర్న్ ఇస్తానని హామీ ఇస్తుంది","ఫండ్ మేనేజర్ మాత్రమే డబ్బు నష్టపోగలరు","మీ డబ్బు విలువ పెరగనూ వచ్చు, తగ్గనూ వచ్చు","మీ డబ్బును ఎప్పటికీ బయటకు తీయలేరు"],"answer":"C","explanation":"ఫండ్ విలువ మార్కెట్‌ను అనుసరిస్తుంది, కాబట్టి అది తగ్గవచ్చు. రిటర్న్‌లకు హామీ లేదని ఆ హెచ్చరిక పెట్టుబడిదారులకు గుర్తు చేస్తుంది."}}'::jsonb, null,null,'live','ai'),
  ('invest-risk-and-return-005','invest', array['risk-and-return'], 'silver','mcq', '{"en":{"prompt":"Vikram feels so worried that he cannot sleep when his investment drops 10%. What does this say about his \"risk tolerance\"?","options":["It is high; he enjoys big swings","Risk tolerance cannot be judged from feelings","It is low; big swings make him uneasy","Risk tolerance depends only on a person''s age"],"answer":"C","explanation":"Risk tolerance is how comfortable you are with your money going up and down. Strong worry after a small drop shows low tolerance."},"hi":{"prompt":"जब विक्रम का निवेश 10% गिरता है, तो वह इतना परेशान हो जाता है कि सो नहीं पाता। इससे उसकी \"रिस्क टॉलरेंस\" (जोखिम सहने की क्षमता) के बारे में क्या पता चलता है?","options":["यह ज़्यादा है; उसे बड़े उतार-चढ़ाव पसंद हैं","रिस्क टॉलरेंस को भावनाओं से नहीं परखा जा सकता","यह कम है; बड़े उतार-चढ़ाव से वह बेचैन हो जाता है","रिस्क टॉलरेंस सिर्फ़ इंसान की उम्र पर निर्भर करती है"],"answer":"C","explanation":"रिस्क टॉलरेंस का मतलब है कि अपने पैसे के ऊपर-नीचे होने पर आप कितने सहज रहते हैं। छोटी-सी गिरावट पर बहुत चिंता होना कम टॉलरेंस दिखाता है।"},"te":{"prompt":"విక్రమ్ పెట్టుబడి 10% పడిపోయినప్పుడు, అతనికి నిద్రపట్టనంతగా ఆందోళన కలుగుతుంది. ఇది అతని \"రిస్క్ టాలరెన్స్\" (రిస్క్‌ను తట్టుకునే సామర్థ్యం) గురించి ఏం చెబుతుంది?","options":["అది ఎక్కువ; అతనికి పెద్ద ఒడిదుడుకులు ఇష్టం","భావాలను బట్టి రిస్క్ టాలరెన్స్‌ను అంచనా వేయలేము","అది తక్కువ; పెద్ద ఒడిదుడుకులు అతన్ని ఇబ్బంది పెడతాయి","రిస్క్ టాలరెన్స్ ఒక వ్యక్తి వయసుపై మాత్రమే ఆధారపడుతుంది"],"answer":"C","explanation":"రిస్క్ టాలరెన్స్ అంటే మీ డబ్బు పెరుగుతూ తగ్గుతూ ఉన్నప్పుడు మీరు ఎంత నిశ్చింతగా ఉంటారో అది. చిన్న తగ్గుదలకే బాగా ఆందోళన చెందడం తక్కువ టాలరెన్స్‌ను చూపిస్తుంది."}}'::jsonb, null,null,'live','ai'),
  ('invest-stocks-basics-004','invest', array['stocks-basics'], 'silver','mcq', '{"en":{"prompt":"Lakshmi owns a few shares of a company. News comes that the company''s profits have fallen sharply. What is likely to happen to her shares?","options":["Their price is fixed, so nothing changes","Their price may fall","She must pay a share of the losses","The bank will refund her original amount"],"answer":"B","explanation":"Share prices often fall when a company earns less, because fewer people want to buy. Her loss is limited to what she invested."},"hi":{"prompt":"लक्ष्मी के पास एक कंपनी के कुछ शेयर हैं। खबर आती है कि कंपनी का मुनाफ़ा बहुत घट गया है। उसके शेयरों के साथ क्या होने की संभावना है?","options":["उनका दाम तय है, इसलिए कुछ नहीं बदलेगा","उनका दाम गिर सकता है","उसे नुकसान का एक हिस्सा भरना होगा","बैंक उसका मूल पैसा वापस कर देगा"],"answer":"B","explanation":"जब कोई कंपनी कम कमाती है, तो अक्सर उसके शेयर का दाम गिरता है, क्योंकि कम लोग उसे खरीदना चाहते हैं। उसका नुकसान उतने तक ही सीमित है जितना उसने निवेश किया है।"},"te":{"prompt":"లక్ష్మి దగ్గర ఒక కంపెనీ షేర్లు కొన్ని ఉన్నాయి. ఆ కంపెనీ లాభాలు బాగా తగ్గిపోయాయని వార్త వచ్చింది. ఆమె షేర్లకు ఏం జరిగే అవకాశం ఉంది?","options":["వాటి ధర స్థిరం, కాబట్టి ఏమీ మారదు","వాటి ధర తగ్గవచ్చు","నష్టాల్లో కొంత భాగాన్ని ఆమె కట్టాలి","బ్యాంకు ఆమె అసలు మొత్తాన్ని తిరిగి ఇస్తుంది"],"answer":"B","explanation":"ఒక కంపెనీ తక్కువ సంపాదించినప్పుడు, కొనాలనుకునేవారు తగ్గుతారు కాబట్టి తరచూ దాని షేరు ధర పడిపోతుంది. ఆమె నష్టం ఆమె పెట్టిన మొత్తానికి మించదు."}}'::jsonb, null,null,'live','ai'),
  ('invest-gold-and-fd-005','invest', array['gold-and-fd'], 'silver','mcq', '{"en":{"prompt":"Imran puts ₹10,000 in a 1-year FD but needs the money after 4 months. What usually happens?","options":["He can break it early, often for less interest","He cannot get any money for the full year","He earns extra interest for leaving early","The bank keeps the whole ₹10,000 as a fine"],"answer":"A","explanation":"Most banks let you close an FD early but pay a lower rate or charge a small penalty. His original money is still returned."},"hi":{"prompt":"इमरान ₹10,000 की 1 साल की FD करता है, लेकिन उसे 4 महीने बाद ही पैसे चाहिए। आम तौर पर क्या होता है?","options":["वह इसे पहले तोड़ सकता है, अक्सर कम ब्याज पर","उसे पूरे साल तक कोई पैसा नहीं मिल सकता","जल्दी निकालने पर उसे ज़्यादा ब्याज मिलता है","बैंक जुर्माने के तौर पर पूरे ₹10,000 रख लेता है"],"answer":"A","explanation":"ज़्यादातर बैंक FD को समय से पहले बंद करने देते हैं, लेकिन कम दर पर ब्याज देते हैं या थोड़ा जुर्माना लेते हैं। उसका मूल पैसा फिर भी वापस मिल जाता है।"},"te":{"prompt":"ఇమ్రాన్ ₹10,000తో 1 సంవత్సరం FD వేస్తాడు, కానీ 4 నెలల తర్వాతే అతనికి డబ్బు అవసరం అవుతుంది. సాధారణంగా ఏం జరుగుతుంది?","options":["అతను దాన్ని ముందుగానే బ్రేక్ చేయవచ్చు, తరచూ తక్కువ వడ్డీకి","పూర్తి సంవత్సరం వరకు అతనికి ఏ డబ్బూ రాదు","ముందుగా తీసుకున్నందుకు అతనికి అదనపు వడ్డీ వస్తుంది","బ్యాంకు జరిమానాగా మొత్తం ₹10,000 ఉంచేసుకుంటుంది"],"answer":"A","explanation":"చాలా బ్యాంకులు FDని ముందుగానే మూసేయనిస్తాయి, కానీ తక్కువ రేటు ఇస్తాయి లేదా చిన్న జరిమానా వసూలు చేస్తాయి. అయినా అతని అసలు డబ్బు తిరిగి వస్తుంది."}}'::jsonb, null,null,'live','ai'),
  ('invest-diversification-005','invest', array['diversification'], 'silver','mcq', '{"en":{"prompt":"Which example shows money spread across the widest mix of options?","options":["Ravi puts all savings in one company''s shares","Asha buys gold jewellery with all her savings","Tarun keeps all his savings in one FD","Pooja splits savings across an FD, gold and a fund"],"answer":"D","explanation":"Pooja''s money is in three different types of options. The others have everything in a single option."},"hi":{"prompt":"किस उदाहरण में पैसा सबसे ज़्यादा तरह के विकल्पों में बँटा हुआ है?","options":["रवि सारी बचत एक कंपनी के शेयरों में लगाता है","आशा सारी बचत से सोने के गहने खरीदती है","तरुण सारी बचत एक FD में रखता है","पूजा बचत को FD, सोने और एक फ़ंड में बाँटती है"],"answer":"D","explanation":"पूजा का पैसा तीन अलग-अलग तरह के विकल्पों में है। बाकी सबने सब कुछ एक ही विकल्प में रखा है।"},"te":{"prompt":"ఏ ఉదాహరణలో డబ్బు అత్యధిక రకాల ఆప్షన్లలో పంచబడి ఉంది?","options":["రవి పొదుపు మొత్తాన్ని ఒకే కంపెనీ షేర్లలో పెడతాడు","ఆశ తన పొదుపు మొత్తంతో బంగారు నగలు కొంటుంది","తరుణ్ తన పొదుపు మొత్తాన్ని ఒకే FDలో ఉంచుతాడు","పూజ పొదుపును FD, బంగారం, ఒక ఫండ్‌లో పంచుతుంది"],"answer":"D","explanation":"పూజ డబ్బు మూడు వేర్వేరు రకాల ఆప్షన్లలో ఉంది. మిగతావాళ్లు అంతా ఒకే ఆప్షన్‌లో పెట్టారు."}}'::jsonb, null,null,'live','ai'),
  ('invest-time-horizon-005','invest', array['time-horizon','risk-and-return'], 'silver','mcq', '{"en":{"prompt":"Why do many people lower the risk of their savings as the date of their goal gets close?","options":["Risky options stop working near goal dates","Banks require it in the final year","Low-risk options pay more near a goal date","A fall near the end leaves little time to recover"],"answer":"D","explanation":"Close to the goal, there is no time to wait for prices to come back. Lowering risk then protects the money that is needed soon."},"hi":{"prompt":"लक्ष्य की तारीख पास आने पर बहुत से लोग अपनी बचत का रिस्क कम क्यों कर देते हैं?","options":["लक्ष्य की तारीख के पास रिस्क वाले विकल्प काम करना बंद कर देते हैं","आखिरी साल में बैंक ऐसा करना ज़रूरी बनाते हैं","लक्ष्य की तारीख के पास कम रिस्क वाले विकल्प ज़्यादा देते हैं","आखिर में गिरावट आई तो संभलने का समय कम बचता है"],"answer":"D","explanation":"लक्ष्य के करीब, दाम वापस आने का इंतज़ार करने का समय नहीं होता। तब रिस्क कम करने से वह पैसा सुरक्षित रहता है जिसकी जल्दी ज़रूरत है।"},"te":{"prompt":"లక్ష్యం తేదీ దగ్గర పడుతున్న కొద్దీ చాలా మంది తమ పొదుపు రిస్క్‌ను ఎందుకు తగ్గిస్తారు?","options":["లక్ష్యం తేదీ దగ్గర రిస్క్ ఉన్న ఆప్షన్లు పనిచేయడం ఆగిపోతాయి","చివరి సంవత్సరంలో బ్యాంకులు అలా చేయడం తప్పనిసరి చేస్తాయి","లక్ష్యం తేదీ దగ్గర తక్కువ రిస్క్ ఉన్న ఆప్షన్లు ఎక్కువ ఇస్తాయి","చివర్లో విలువ పడిపోతే కోలుకోవడానికి తక్కువ సమయం మిగులుతుంది"],"answer":"D","explanation":"లక్ష్యానికి దగ్గరగా ఉన్నప్పుడు, ధరలు తిరిగి పెరిగే వరకు ఎదురుచూసే సమయం ఉండదు. అప్పుడు రిస్క్ తగ్గిస్తే త్వరలో అవసరమైన డబ్బు సురక్షితంగా ఉంటుంది."}}'::jsonb, null,null,'live','ai'),
  ('invest-stocks-basics-005','invest', array['stocks-basics'], 'silver','mcq', '{"en":{"prompt":"Siddharth bought a share at ₹200. It is now ₹150, and he has not sold it. What is true?","options":["He has already lost ₹50 in cash for sure","The price must return to ₹200 eventually","His loss is on paper; the price can still change","The company now owes him ₹50"],"answer":"C","explanation":"Until he sells, the ₹50 loss is not final, and the price may rise or fall further. Nothing guarantees it returns to ₹200."},"hi":{"prompt":"सिद्धार्थ ने ₹200 में एक शेयर खरीदा। अब उसका दाम ₹150 है, और उसने उसे बेचा नहीं है। क्या सही है?","options":["उसने पक्का ₹50 नकद गँवा दिए हैं","दाम आखिरकार ₹200 पर लौटना ही चाहिए","उसका नुकसान अभी कागज़ पर है; दाम अभी भी बदल सकता है","अब कंपनी को उसे ₹50 देने हैं"],"answer":"C","explanation":"जब तक वह बेचता नहीं, ₹50 का नुकसान पक्का नहीं है, और दाम आगे बढ़ या घट सकता है। इसकी कोई गारंटी नहीं कि दाम ₹200 पर लौटेगा।"},"te":{"prompt":"సిద్ధార్థ్ ఒక షేరును ₹200కు కొన్నాడు. ఇప్పుడు దాని ధర ₹150, అతను దాన్ని ఇంకా అమ్మలేదు. ఏది నిజం?","options":["అతను ఇప్పటికే ఖచ్చితంగా ₹50 నగదు నష్టపోయాడు","ధర ఎప్పటికైనా ₹200కు తిరిగి రావాల్సిందే","అతని నష్టం ఇప్పటికి కాగితం మీదే; ధర ఇంకా మారవచ్చు","ఇప్పుడు కంపెనీ అతనికి ₹50 బాకీ ఉంది"],"answer":"C","explanation":"అతను అమ్మే వరకు ₹50 నష్టం ఫైనల్ కాదు, ధర ఇంకా పెరగవచ్చు లేదా తగ్గవచ్చు. ధర ₹200కు తిరిగి వస్తుందని ఏ గ్యారంటీ లేదు."}}'::jsonb, null,null,'live','ai'),
  ('invest-diversification-006','invest', array['diversification','risk-and-return'], 'gold','mcq', '{"en":{"prompt":"A fruit seller earns ₹300 a day each from mangoes, bananas and apples. Mango season fails, and mango income becomes zero. How much does she still earn per day?","options":["₹0","₹600","₹300","₹900"],"answer":"B","explanation":"Only the ₹300 from mangoes is lost, so bananas and apples still bring ₹600. Selling three fruits meant one bad season did not wipe her out."},"hi":{"prompt":"एक फल वाली आम, केले और सेब — हर एक से रोज़ ₹300 कमाती है। आम का मौसम खराब जाता है, और आम से कमाई शून्य हो जाती है। अब वह रोज़ कितना कमाती है?","options":["₹0","₹600","₹300","₹900"],"answer":"B","explanation":"सिर्फ़ आम से होने वाले ₹300 गए, इसलिए केले और सेब से अब भी ₹600 आते हैं। तीन तरह के फल बेचने से एक खराब मौसम में सब कुछ खत्म नहीं हुआ।"},"te":{"prompt":"ఒక పండ్ల వ్యాపారి మామిడి, అరటి, ఆపిల్ — ఒక్కోదాని నుండి రోజుకు ₹300 సంపాదిస్తుంది. మామిడి సీజన్ దెబ్బతిని, మామిడి ఆదాయం సున్నా అవుతుంది. ఆమె ఇప్పటికీ రోజుకు ఎంత సంపాదిస్తుంది?","options":["₹0","₹600","₹300","₹900"],"answer":"B","explanation":"మామిడి నుండి వచ్చే ₹300 మాత్రమే పోయింది, కాబట్టి అరటి, ఆపిల్ నుండి ఇంకా ₹600 వస్తుంది. మూడు రకాల పండ్లు అమ్మడం వల్ల ఒక్క చెడ్డ సీజన్ ఆమెను పూర్తిగా దెబ్బతీయలేదు."}}'::jsonb, 'invest-risk-and-diversification',null,'live','ai'),
  ('invest-risk-and-return-006','invest', array['risk-and-return'], 'gold','mcq', '{"en":{"prompt":"Priya''s ₹10,000 investment falls 20% in year one and rises 20% in year two. What is it worth now? (Example numbers; ignore fees.)","options":["₹9,600","₹10,000","₹8,000","₹10,400"],"answer":"A","explanation":"After the fall it is ₹8,000, and 20% of ₹8,000 is ₹1,600, giving ₹9,600. A rise has to be bigger than the fall to get back to the start."},"hi":{"prompt":"प्रिया का ₹10,000 का निवेश पहले साल 20% गिरता है और दूसरे साल 20% बढ़ता है। अब इसकी वैल्यू कितनी है? (उदाहरण के आँकड़े; फ़ीस को छोड़ दें।)","options":["₹9,600","₹10,000","₹8,000","₹10,400"],"answer":"A","explanation":"गिरने के बाद यह ₹8,000 रह जाता है, और ₹8,000 का 20% ₹1,600 है, जिससे यह ₹9,600 होता है। शुरुआती रकम पर लौटने के लिए बढ़त, गिरावट से बड़ी होनी चाहिए।"},"te":{"prompt":"ప్రియ పెట్టిన ₹10,000 మొదటి సంవత్సరం 20% పడిపోయి, రెండో సంవత్సరం 20% పెరుగుతుంది. ఇప్పుడు దాని విలువ ఎంత? (ఉదాహరణ సంఖ్యలు; ఫీజులను లెక్కలోకి తీసుకోవద్దు.)","options":["₹9,600","₹10,000","₹8,000","₹10,400"],"answer":"A","explanation":"పడిపోయిన తర్వాత అది ₹8,000 అవుతుంది, ₹8,000లో 20% అంటే ₹1,600, కాబట్టి మొత్తం ₹9,600. మొదటి మొత్తానికి తిరిగి రావాలంటే, పెరుగుదల తగ్గుదల కంటే పెద్దదిగా ఉండాలి."}}'::jsonb, null,null,'live','ai'),
  ('invest-diversification-007','invest', array['diversification'], 'gold','mcq', '{"en":{"prompt":"Ravi puts ₹5,000 in option X and ₹5,000 in option Y. In one example year, X falls 10% and Y rises 6%. What is his total at year end?","options":["₹9,800","₹9,000","₹10,600","₹9,600"],"answer":"A","explanation":"X becomes ₹4,500 and Y becomes ₹5,300, which adds to ₹9,800. Splitting the money made the loss smaller than putting it all in X."},"hi":{"prompt":"रवि ₹5,000 विकल्प X में और ₹5,000 विकल्प Y में लगाता है। एक उदाहरण वाले साल में X 10% गिरता है और Y 6% बढ़ता है। साल के आखिर में उसके पास कुल कितना है?","options":["₹9,800","₹9,000","₹10,600","₹9,600"],"answer":"A","explanation":"X ₹4,500 हो जाता है और Y ₹5,300, जो मिलाकर ₹9,800 है। पैसा बाँटने से नुकसान उससे कम हुआ, जितना सारा पैसा X में लगाने पर होता।"},"te":{"prompt":"రవి ₹5,000 ఆప్షన్ Xలో, ₹5,000 ఆప్షన్ Yలో పెడతాడు. ఒక ఉదాహరణ సంవత్సరంలో X 10% పడిపోతుంది, Y 6% పెరుగుతుంది. సంవత్సరం చివరికి అతని దగ్గర మొత్తం ఎంత ఉంటుంది?","options":["₹9,800","₹9,000","₹10,600","₹9,600"],"answer":"A","explanation":"X ₹4,500 అవుతుంది, Y ₹5,300 అవుతుంది, రెండూ కలిపి ₹9,800. డబ్బును పంచడం వల్ల, మొత్తం Xలోనే పెట్టి ఉంటే వచ్చే నష్టం కంటే తక్కువ నష్టం వచ్చింది."}}'::jsonb, null,null,'live','ai'),
  ('invest-gold-and-fd-006','invest', array['gold-and-fd'], 'gold','mcq', '{"en":{"prompt":"Anjali puts ₹20,000 in a 1-year FD. Assume 7% interest a year and ignore tax. How much will she have at the end?","options":["₹20,140","₹27,000","₹21,000","₹21,400"],"answer":"D","explanation":"7% of ₹20,000 is ₹1,400, so she ends with ₹21,400. A fixed rate makes the FD result easy to know in advance."},"hi":{"prompt":"अंजलि ₹20,000 की 1 साल की FD करती है। मान लें कि ब्याज 7% सालाना है और टैक्स को छोड़ दें। आखिर में उसके पास कितने होंगे?","options":["₹20,140","₹27,000","₹21,000","₹21,400"],"answer":"D","explanation":"₹20,000 का 7% ₹1,400 है, इसलिए आखिर में उसके पास ₹21,400 होंगे। तय दर की वजह से FD का नतीजा पहले से जानना आसान होता है।"},"te":{"prompt":"అంజలి ₹20,000తో 1 సంవత్సరం FD వేస్తుంది. వడ్డీ సంవత్సరానికి 7% అనుకోండి, పన్నును లెక్కలోకి తీసుకోవద్దు. చివరికి ఆమె దగ్గర ఎంత ఉంటుంది?","options":["₹20,140","₹27,000","₹21,000","₹21,400"],"answer":"D","explanation":"₹20,000లో 7% అంటే ₹1,400, కాబట్టి చివరికి ఆమె దగ్గర ₹21,400 ఉంటుంది. స్థిర రేటు వల్ల FD ఫలితం ముందుగానే తెలుసుకోవడం సులభం."}}'::jsonb, null,null,'live','ai'),
  ('invest-mutual-fund-basics-006','invest', array['mutual-fund-basics','time-horizon'], 'gold','mcq', '{"en":{"prompt":"Kavya invests ₹500 every month through a SIP for 3 years. How much money has she put in, before any gains or losses?","options":["₹1,500","₹6,000","₹18,000","₹15,000"],"answer":"C","explanation":"3 years is 36 months, and 36 × ₹500 = ₹18,000. The fund''s value could end above or below this amount."},"hi":{"prompt":"काव्या 3 साल तक हर महीने SIP के ज़रिए ₹500 निवेश करती है। किसी भी फ़ायदे या नुकसान से पहले, उसने कुल कितना पैसा लगाया है?","options":["₹1,500","₹6,000","₹18,000","₹15,000"],"answer":"C","explanation":"3 साल यानी 36 महीने, और 36 × ₹500 = ₹18,000। फ़ंड की वैल्यू आखिर में इस रकम से ज़्यादा या कम हो सकती है।"},"te":{"prompt":"కావ్య 3 సంవత్సరాల పాటు ప్రతి నెలా SIP ద్వారా ₹500 పెట్టుబడి పెడుతుంది. లాభనష్టాలకు ముందు, ఆమె మొత్తం ఎంత డబ్బు పెట్టింది?","options":["₹1,500","₹6,000","₹18,000","₹15,000"],"answer":"C","explanation":"3 సంవత్సరాలు అంటే 36 నెలలు, 36 × ₹500 = ₹18,000. చివరికి ఫండ్ విలువ ఈ మొత్తం కంటే ఎక్కువ లేదా తక్కువ ఉండవచ్చు."}}'::jsonb, null,null,'live','ai'),
  ('invest-risk-and-return-007','invest', array['risk-and-return'], 'platinum','mcq', '{"en":{"prompt":"Option A grows about 6% each year with small changes. Option B has averaged more, but in some years fell 15%. What is the main trade-off? (Example numbers.)","options":["A is riskier because it grows slowly","B may grow more but can drop sharply","B is safer because its average is higher","There is no trade-off; B is simply better"],"answer":"B","explanation":"B''s higher average comes with bigger falls, while A is steadier but grows slowly. Choosing between them means weighing growth against the chance of loss."},"hi":{"prompt":"विकल्प A हर साल लगभग 6% बढ़ता है, छोटे-मोटे बदलावों के साथ। विकल्प B का औसत ज़्यादा रहा है, लेकिन कुछ सालों में यह 15% गिरा। मुख्य ट्रेड-ऑफ़ (किसके बदले क्या छोड़ना पड़ता है) क्या है? (उदाहरण के आँकड़े।)","options":["A ज़्यादा रिस्की है क्योंकि यह धीरे बढ़ता है","B ज़्यादा बढ़ सकता है, लेकिन तेज़ी से गिर भी सकता है","B ज़्यादा सुरक्षित है क्योंकि इसका औसत ज़्यादा है","कोई ट्रेड-ऑफ़ नहीं; B बस बेहतर है"],"answer":"B","explanation":"B के ज़्यादा औसत के साथ बड़ी गिरावटें भी आती हैं, जबकि A स्थिर है पर धीरे बढ़ता है। इनमें से चुनने का मतलब है बढ़त और नुकसान की संभावना को तौलना।"},"te":{"prompt":"ఆప్షన్ A ప్రతి సంవత్సరం చిన్న మార్పులతో దాదాపు 6% పెరుగుతుంది. ఆప్షన్ B సగటు ఎక్కువే, కానీ కొన్ని సంవత్సరాల్లో అది 15% పడిపోయింది. ప్రధాన ట్రేడ్-ఆఫ్ (ఒకటి పొందాలంటే మరొకటి వదులుకోవడం) ఏమిటి? (ఉదాహరణ సంఖ్యలు.)","options":["A నెమ్మదిగా పెరుగుతుంది కాబట్టి అదే ఎక్కువ రిస్క్","B ఎక్కువగా పెరగవచ్చు, కానీ ఒక్కసారిగా పడిపోవచ్చు కూడా","B సగటు ఎక్కువ కాబట్టి అదే సురక్షితం","ట్రేడ్-ఆఫ్ ఏమీ లేదు; B నే మంచిది"],"answer":"B","explanation":"B ఎక్కువ సగటుతో పాటు పెద్ద పతనాలు కూడా వస్తాయి, A స్థిరంగా ఉంటుంది కానీ నెమ్మదిగా పెరుగుతుంది. వాటి మధ్య ఎంచుకోవడం అంటే పెరుగుదలను, నష్టం వచ్చే అవకాశాన్ని బేరీజు వేయడం."}}'::jsonb, null,'invest-risk-and-return','live','ai'),
  ('invest-time-horizon-006','invest', array['time-horizon','risk-and-return'], 'platinum','mcq', '{"en":{"prompt":"Neha needs ₹30,000 in 6 months. Arvind''s goal is 12 years away. Both look at an option that can fall 20% in a bad year. Why might it suit them differently?","options":["Neha''s smaller goal makes a loss impossible","Arvind has time to recover; Neha may not","Arvind''s long wait guarantees him a profit","It suits both equally; time doesn''t matter"],"answer":"B","explanation":"A bad year just before Neha needs her money could leave her short. Arvind has years for prices to recover, though even that is not guaranteed."},"hi":{"prompt":"नेहा को 6 महीने में ₹30,000 चाहिए। अरविंद का लक्ष्य 12 साल दूर है। दोनों एक ऐसा विकल्प देखते हैं जो किसी बुरे साल में 20% गिर सकता है। यह दोनों के लिए अलग-अलग तरह से सही क्यों हो सकता है?","options":["नेहा का छोटा लक्ष्य नुकसान को नामुमकिन बना देता है","अरविंद के पास संभलने का समय है; नेहा के पास शायद नहीं","अरविंद का लंबा इंतज़ार उसे मुनाफ़े की गारंटी देता है","यह दोनों के लिए बराबर है; समय से फ़र्क नहीं पड़ता"],"answer":"B","explanation":"नेहा को पैसे की ज़रूरत पड़ने से ठीक पहले बुरा साल आया तो उसके पैसे कम पड़ सकते हैं। अरविंद के पास दाम संभलने के लिए कई साल हैं, हालाँकि उसकी भी गारंटी नहीं है।"},"te":{"prompt":"నేహాకు 6 నెలల్లో ₹30,000 కావాలి. అరవింద్ లక్ష్యం 12 సంవత్సరాల దూరంలో ఉంది. చెడ్డ సంవత్సరంలో 20% పడిపోగల ఒక ఆప్షన్‌ను ఇద్దరూ చూస్తున్నారు. అది వారిద్దరికీ వేర్వేరుగా ఎందుకు సరిపోవచ్చు?","options":["నేహా లక్ష్యం చిన్నది కాబట్టి నష్టం రావడం అసాధ్యం","అరవింద్‌కు కోలుకునే సమయం ఉంది; నేహాకు ఉండకపోవచ్చు","ఎక్కువ కాలం ఆగడం వల్ల అరవింద్‌కు లాభం గ్యారంటీ","ఇద్దరికీ సమానంగా సరిపోతుంది; సమయం ముఖ్యం కాదు"],"answer":"B","explanation":"నేహాకు డబ్బు అవసరమయ్యే ముందే చెడ్డ సంవత్సరం వస్తే, ఆమెకు డబ్బు తక్కువ పడవచ్చు. అరవింద్‌కు ధరలు కోలుకోవడానికి చాలా సంవత్సరాలు ఉన్నాయి, అయినా అది కూడా గ్యారంటీ కాదు."}}'::jsonb, null,'invest-risk-and-return','live','ai'),
  ('invest-time-horizon-007','invest', array['time-horizon','risk-and-return'], 'platinum','mcq', '{"en":{"prompt":"Divya and Karan invest in the same option for 10 years. After a 15% fall, Divya stays invested while Karan sells in panic. Whose choice locks in the loss?","options":["Karan''s, because selling makes the fall final","Divya''s, because staying makes losses bigger","Neither, since losses are final once prices fall","Both equally, since selling changes nothing"],"answer":"A","explanation":"A fall is only a loss on paper until you sell. By selling, Karan turned it into a real loss, while Divya''s value can still change."},"hi":{"prompt":"दिव्या और करण एक ही विकल्प में 10 साल के लिए निवेश करते हैं। 15% गिरावट के बाद दिव्या निवेश में बनी रहती है, जबकि करण घबराकर बेच देता है। किसके फ़ैसले से नुकसान पक्का हो जाता है?","options":["करण के, क्योंकि बेचने से गिरावट पक्की हो जाती है","दिव्या के, क्योंकि बने रहने से नुकसान बढ़ता है","किसी के नहीं, क्योंकि दाम गिरते ही नुकसान पक्का हो जाता है","दोनों के बराबर, क्योंकि बेचने से कुछ नहीं बदलता"],"answer":"A","explanation":"जब तक आप बेचते नहीं, गिरावट सिर्फ़ कागज़ी नुकसान है। बेचकर करण ने इसे असली नुकसान बना दिया, जबकि दिव्या की वैल्यू अभी भी बदल सकती है।"},"te":{"prompt":"దివ్య, కరణ్ ఒకే ఆప్షన్‌లో 10 సంవత్సరాల కోసం పెట్టుబడి పెడతారు. 15% పతనం తర్వాత దివ్య పెట్టుబడిని కొనసాగిస్తుంది, కరణ్ భయంతో అమ్మేస్తాడు. ఎవరి నిర్ణయం నష్టాన్ని ఖాయం చేస్తుంది?","options":["కరణ్‌ది, ఎందుకంటే అమ్మడం వల్ల పతనం ఫైనల్ అవుతుంది","దివ్యది, ఎందుకంటే కొనసాగించడం నష్టాలను పెంచుతుంది","ఎవరిదీ కాదు, ఎందుకంటే ధరలు పడిపోగానే నష్టాలు ఫైనల్","ఇద్దరిదీ సమానంగా, ఎందుకంటే అమ్మడం వల్ల ఏమీ మారదు"],"answer":"A","explanation":"మీరు అమ్మే వరకు పతనం కేవలం కాగితంపై నష్టమే. అమ్మడం ద్వారా కరణ్ దాన్ని నిజమైన నష్టంగా మార్చాడు, దివ్య పెట్టుబడి విలువ ఇంకా మారవచ్చు."}}'::jsonb, null,'invest-risk-and-return','live','ai'),
  ('invest-risk-and-return-008','invest', array['risk-and-return'], 'platinum','mcq', '{"en":{"prompt":"Ramesh''s FD earns an assumed 5% a year, while prices rise 6% a year. Why is his \"safe\" FD losing value in real terms?","options":["The bank cuts 6% from his deposit yearly","Share market falls reduce his FD by 1%","Interest is paid only when prices fall","Prices rise faster than his money grows"],"answer":"D","explanation":"His money grows 5%, but things cost 6% more, so it buys a little less each year. Low risk does not always mean no loss of buying power."},"hi":{"prompt":"मान लें रमेश की FD पर 5% सालाना ब्याज मिलता है, जबकि दाम हर साल 6% बढ़ते हैं। असल मायनों में उसकी \"सुरक्षित\" FD की वैल्यू क्यों घट रही है?","options":["बैंक हर साल उसकी जमा राशि से 6% काट लेता है","शेयर बाज़ार की गिरावट उसकी FD को 1% घटा देती है","ब्याज सिर्फ़ तब मिलता है जब दाम गिरते हैं","दाम उसके पैसे से ज़्यादा तेज़ी से बढ़ते हैं"],"answer":"D","explanation":"उसका पैसा 5% बढ़ता है, लेकिन चीज़ें 6% महँगी हो जाती हैं, इसलिए हर साल वह उससे थोड़ा कम खरीद पाता है। कम रिस्क का मतलब हमेशा यह नहीं कि खरीदने की ताकत नहीं घटेगी।"},"te":{"prompt":"రమేష్ FDకి సంవత్సరానికి 5% వడ్డీ వస్తుందని అనుకోండి, కానీ ధరలు సంవత్సరానికి 6% పెరుగుతున్నాయి. అతని \"సురక్షితమైన\" FD అసలు విలువ ఎందుకు తగ్గుతోంది?","options":["బ్యాంకు ప్రతి సంవత్సరం అతని డిపాజిట్ నుండి 6% కోస్తుంది","షేర్ మార్కెట్ పతనాలు అతని FDని 1% తగ్గిస్తాయి","ధరలు తగ్గినప్పుడు మాత్రమే వడ్డీ చెల్లిస్తారు","అతని డబ్బు పెరిగే దానికంటే ధరలు వేగంగా పెరుగుతున్నాయి"],"answer":"D","explanation":"అతని డబ్బు 5% పెరుగుతుంది, కానీ వస్తువుల ధరలు 6% పెరుగుతాయి, కాబట్టి ప్రతి సంవత్సరం దానితో కొంచెం తక్కువే కొనగలడు. తక్కువ రిస్క్ అంటే కొనుగోలు శక్తి తగ్గదని ఎప్పుడూ కాదు."}}'::jsonb, null,'invest-risk-and-return','live','ai'),
  ('invest-time-horizon-008','invest', array['time-horizon','risk-and-return'], 'platinum','mcq', '{"en":{"prompt":"Sana has ₹15,000: ₹10,000 is her emergency fund and ₹5,000 is for a goal 8 years away. Why might she treat these two parts differently?","options":["The larger part should always take more risk","Both parts have the same time horizon","Emergency money must be ready; long-term money can ride ups and downs","Long-term money must be kept as cash at home"],"answer":"C","explanation":"An emergency can come any day, so that money must not be down when needed. Money for 8 years ahead has time to handle some swings."},"hi":{"prompt":"सना के पास ₹15,000 हैं: ₹10,000 उसका इमरजेंसी फ़ंड है और ₹5,000 8 साल बाद के एक लक्ष्य के लिए हैं। वह इन दोनों हिस्सों को अलग-अलग तरह से क्यों संभाल सकती है?","options":["बड़े हिस्से को हमेशा ज़्यादा रिस्क लेना चाहिए","दोनों हिस्सों का टाइम होराइज़न एक ही है","इमरजेंसी का पैसा तुरंत मिलना चाहिए; लंबे समय का पैसा उतार-चढ़ाव झेल सकता है","लंबे समय का पैसा घर पर नकद ही रखना चाहिए"],"answer":"C","explanation":"इमरजेंसी किसी भी दिन आ सकती है, इसलिए ज़रूरत के समय वह पैसा घटा हुआ नहीं होना चाहिए। 8 साल बाद के पैसे के पास कुछ उतार-चढ़ाव झेलने का समय है।"},"te":{"prompt":"సనా దగ్గర ₹15,000 ఉన్నాయి: ₹10,000 ఆమె ఎమర్జెన్సీ ఫండ్, ₹5,000 8 సంవత్సరాల తర్వాతి లక్ష్యం కోసం. ఈ రెండు భాగాలను ఆమె ఎందుకు వేర్వేరుగా చూడవచ్చు?","options":["పెద్ద భాగం ఎప్పుడూ ఎక్కువ రిస్క్ తీసుకోవాలి","రెండు భాగాలకూ ఒకే టైమ్ హొరైజన్ ఉంది","ఎమర్జెన్సీ డబ్బు వెంటనే అందుబాటులో ఉండాలి; దీర్ఘకాలిక డబ్బు ఒడిదుడుకులను తట్టుకోగలదు","దీర్ఘకాలిక డబ్బును ఇంట్లో నగదుగానే ఉంచాలి"],"answer":"C","explanation":"ఎమర్జెన్సీ ఏ రోజైనా రావచ్చు, కాబట్టి అవసరమైనప్పుడు ఆ డబ్బు విలువ తగ్గి ఉండకూడదు. 8 సంవత్సరాల తర్వాత కావాల్సిన డబ్బుకు కొన్ని ఒడిదుడుకులను తట్టుకునే సమయం ఉంది."}}'::jsonb, null,'invest-risk-and-return','live','ai'),
  ('invest-diversification-008','invest', array['diversification'], 'platinum','mcq', '{"en":{"prompt":"Portfolio A has 5 shares, all banks. Portfolio B has 5 shares from banking, medicine, food, phones and power. Which is more diversified, and why?","options":["A, because banks are always safe","Both, because each holds five shares","B, because one industry''s trouble hits less of it","A, because fewer industries are easier to track"],"answer":"C","explanation":"If banks have a bad year, all of A suffers but only one-fifth of B does. Diversifying across industries spreads that risk."},"hi":{"prompt":"पोर्टफ़ोलियो A में 5 शेयर हैं, सभी बैंकों के। पोर्टफ़ोलियो B में बैंकिंग, दवा, खाना, फ़ोन और बिजली से 5 शेयर हैं। कौन ज़्यादा डाइवर्सिफ़ाइड है, और क्यों?","options":["A, क्योंकि बैंक हमेशा सुरक्षित होते हैं","दोनों, क्योंकि दोनों में पाँच-पाँच शेयर हैं","B, क्योंकि किसी एक उद्योग की मुसीबत उसके छोटे हिस्से पर ही असर डालती है","A, क्योंकि कम उद्योगों पर नज़र रखना आसान है"],"answer":"C","explanation":"अगर बैंकों का साल खराब रहा, तो पूरा A नुकसान में होगा, लेकिन B का सिर्फ़ पाँचवाँ हिस्सा। अलग-अलग उद्योगों में पैसा बाँटने से वह रिस्क बँट जाता है।"},"te":{"prompt":"పోర్ట్‌ఫోలియో Aలో 5 షేర్లు ఉన్నాయి, అన్నీ బ్యాంకులవే. పోర్ట్‌ఫోలియో Bలో బ్యాంకింగ్, మందులు, ఆహారం, ఫోన్లు, విద్యుత్ రంగాల నుండి 5 షేర్లు ఉన్నాయి. ఏది ఎక్కువ డైవర్సిఫైడ్, ఎందుకు?","options":["A, ఎందుకంటే బ్యాంకులు ఎప్పుడూ సురక్షితం","రెండూ, ఎందుకంటే ప్రతిదానిలో ఐదు షేర్లు ఉన్నాయి","B, ఎందుకంటే ఒక పరిశ్రమకు కష్టం వస్తే దానిలో తక్కువ భాగమే దెబ్బతింటుంది","A, ఎందుకంటే తక్కువ పరిశ్రమలను గమనించడం సులభం"],"answer":"C","explanation":"బ్యాంకులకు చెడ్డ సంవత్సరం వస్తే, A మొత్తం నష్టపోతుంది కానీ Bలో ఐదో వంతు మాత్రమే నష్టపోతుంది. వేర్వేరు పరిశ్రమల్లో పంచడం వల్ల ఆ రిస్క్ పంచబడుతుంది."}}'::jsonb, null,'invest-diversification','live','ai'),
  ('invest-diversification-009','invest', array['diversification'], 'platinum','mcq', '{"en":{"prompt":"Diversification is useful, but there are limits. Which of these can diversification NOT do?","options":["Reduce harm from one bad investment","Guarantee that you never lose money","Spread your money across different options","Make one company''s failure hurt less"],"answer":"B","explanation":"Diversification softens losses from any one option. When most markets fall together, a spread-out mix can still lose money."},"hi":{"prompt":"डाइवर्सिफ़िकेशन फ़ायदेमंद है, लेकिन इसकी सीमाएँ हैं। इनमें से कौन-सा काम डाइवर्सिफ़िकेशन नहीं कर सकता?","options":["एक खराब निवेश से होने वाला नुकसान कम करना","गारंटी देना कि आपको कभी नुकसान नहीं होगा","आपके पैसे को अलग-अलग विकल्पों में बाँटना","किसी एक कंपनी के फ़ेल होने का असर कम करना"],"answer":"B","explanation":"डाइवर्सिफ़िकेशन किसी एक विकल्प से होने वाले नुकसान को कम करता है। जब ज़्यादातर बाज़ार एक साथ गिरते हैं, तो बँटा हुआ पैसा भी घट सकता है।"},"te":{"prompt":"డైవర్సిఫికేషన్ ఉపయోగకరమే, కానీ దానికి పరిమితులు ఉన్నాయి. వీటిలో డైవర్సిఫికేషన్ ఏది చేయలేదు?","options":["ఒక చెడ్డ పెట్టుబడి వల్ల జరిగే హానిని తగ్గించడం","మీకు ఎప్పుడూ నష్టం రాదని గ్యారంటీ ఇవ్వడం","మీ డబ్బును వేర్వేరు ఆప్షన్లలో పంచడం","ఒక కంపెనీ విఫలమైతే దాని ప్రభావాన్ని తగ్గించడం"],"answer":"B","explanation":"డైవర్సిఫికేషన్ ఏ ఒక్క ఆప్షన్ నుండి వచ్చే నష్టాన్నైనా తగ్గిస్తుంది. చాలా మార్కెట్లు ఒకేసారి పడిపోయినప్పుడు, పంచి పెట్టిన డబ్బు కూడా నష్టపోవచ్చు."}}'::jsonb, null,'invest-diversification','live','ai'),
  ('invest-diversification-010','invest', array['diversification'], 'platinum','mcq', '{"en":{"prompt":"Spreading money across many options lowers risk. What is the trade-off?","options":["You won''t get the full gain of the top performer","Your money becomes locked for many years","Your total return is guaranteed to be lower","You must pay extra tax on each option"],"answer":"A","explanation":"Only part of your money is in whichever option does best, so your gain is smaller than if it were all there. In return, a single failure hurts less."},"hi":{"prompt":"पैसे को कई विकल्पों में बाँटने से रिस्क कम होता है। इसका ट्रेड-ऑफ़ (बदले में क्या छोड़ना पड़ता है) क्या है?","options":["सबसे अच्छा करने वाले विकल्प का पूरा फ़ायदा आपको नहीं मिलेगा","आपका पैसा कई सालों के लिए बंद हो जाता है","आपका कुल रिटर्न पक्का कम ही होगा","हर विकल्प पर आपको अलग से ज़्यादा टैक्स देना होगा"],"answer":"A","explanation":"जो विकल्प सबसे अच्छा करता है, उसमें आपके पैसे का सिर्फ़ एक हिस्सा होता है, इसलिए फ़ायदा उससे कम होता है जितना सारा पैसा वहाँ होने पर होता। बदले में, किसी एक के फ़ेल होने से कम नुकसान होता है।"},"te":{"prompt":"డబ్బును చాలా ఆప్షన్లలో పంచితే రిస్క్ తగ్గుతుంది. దీనికి ట్రేడ్-ఆఫ్ (బదులుగా వదులుకోవాల్సింది) ఏమిటి?","options":["అన్నింటికంటే బాగా పెరిగిన ఆప్షన్ పూర్తి లాభం మీకు రాదు","మీ డబ్బు చాలా సంవత్సరాల పాటు లాక్ అయిపోతుంది","మీ మొత్తం రిటర్న్ తక్కువగా ఉంటుందని ఖాయం","ప్రతి ఆప్షన్‌పై మీరు అదనపు పన్ను కట్టాలి"],"answer":"A","explanation":"బాగా పెరిగిన ఆప్షన్‌లో మీ డబ్బులో కొంత భాగమే ఉంటుంది, కాబట్టి మొత్తం అక్కడే ఉంటే వచ్చేదానికంటే లాభం తక్కువ. దానికి బదులుగా, ఏదో ఒకటి విఫలమైతే జరిగే నష్టం తక్కువ."}}'::jsonb, null,'invest-diversification','live','ai'),
  ('invest-diversification-011','invest', array['diversification'], 'platinum','mcq', '{"en":{"prompt":"Asif puts ₹10,000 into one option. Bhavna splits ₹10,000 equally across five options, including Asif''s. That option falls to zero; the others stay flat. How much does each lose?","options":["Both lose ₹10,000","Asif ₹10,000; Bhavna ₹5,000","Asif ₹2,000; Bhavna ₹10,000","Asif ₹10,000; Bhavna ₹2,000"],"answer":"D","explanation":"Bhavna had only ₹10,000 ÷ 5 = ₹2,000 in the failed option. Asif had everything in it, so he lost it all."},"hi":{"prompt":"आसिफ़ ₹10,000 एक विकल्प में लगाता है। भावना ₹10,000 को पाँच विकल्पों में बराबर बाँटती है, जिनमें आसिफ़ वाला विकल्प भी है। वह विकल्प शून्य हो जाता है; बाकी वैसे ही रहते हैं। हर एक को कितना नुकसान होता है?","options":["दोनों को ₹10,000","आसिफ़ को ₹10,000; भावना को ₹5,000","आसिफ़ को ₹2,000; भावना को ₹10,000","आसिफ़ को ₹10,000; भावना को ₹2,000"],"answer":"D","explanation":"भावना का उस डूबे विकल्प में सिर्फ़ ₹10,000 ÷ 5 = ₹2,000 था। आसिफ़ का सारा पैसा उसी में था, इसलिए उसने सब गँवा दिया।"},"te":{"prompt":"ఆసిఫ్ ₹10,000 ఒకే ఆప్షన్‌లో పెడతాడు. భావన ₹10,000ను ఆసిఫ్ ఆప్షన్‌తో సహా ఐదు ఆప్షన్లలో సమానంగా పంచుతుంది. ఆ ఆప్షన్ సున్నాకు పడిపోతుంది; మిగతావి మారకుండా ఉంటాయి. ఒక్కొక్కరు ఎంత నష్టపోతారు?","options":["ఇద్దరూ ₹10,000","ఆసిఫ్ ₹10,000; భావన ₹5,000","ఆసిఫ్ ₹2,000; భావన ₹10,000","ఆసిఫ్ ₹10,000; భావన ₹2,000"],"answer":"D","explanation":"విఫలమైన ఆప్షన్‌లో భావనకు ₹10,000 ÷ 5 = ₹2,000 మాత్రమే ఉంది. ఆసిఫ్ మొత్తం డబ్బు దానిలోనే ఉంది, కాబట్టి అతను అంతా పోగొట్టుకున్నాడు."}}'::jsonb, null,'invest-diversification','live','ai'),
  ('invest-diversification-012','invest', array['diversification','mutual-fund-basics'], 'platinum','mcq', '{"en":{"prompt":"Gopal owns two mutual funds and thinks he is well diversified. But both funds mostly hold the same ten big companies. What is the problem?","options":["Owning two funds is against the rules","Funds holding big companies cannot fall","He is spread across too many companies","His money is still bunched in the same companies"],"answer":"D","explanation":"If the same ten companies do badly, both funds fall together. Real diversification means holding things that don''t all depend on the same companies."},"hi":{"prompt":"गोपाल के पास दो म्यूचुअल फ़ंड हैं और उसे लगता है कि उसका पैसा अच्छी तरह डाइवर्सिफ़ाइड है। लेकिन दोनों फ़ंड ज़्यादातर उन्हीं दस बड़ी कंपनियों के शेयर रखते हैं। समस्या क्या है?","options":["दो फ़ंड रखना नियमों के खिलाफ़ है","बड़ी कंपनियों वाले फ़ंड गिर नहीं सकते","उसका पैसा बहुत ज़्यादा कंपनियों में बँटा है","उसका पैसा अब भी उन्हीं कंपनियों में सिमटा हुआ है"],"answer":"D","explanation":"अगर वही दस कंपनियाँ खराब करें, तो दोनों फ़ंड एक साथ गिरेंगे। असली डाइवर्सिफ़िकेशन का मतलब है ऐसी चीज़ें रखना जो सब एक ही कंपनियों पर निर्भर न हों।"},"te":{"prompt":"గోపాల్ దగ్గర రెండు మ్యూచువల్ ఫండ్లు ఉన్నాయి, తన డబ్బు బాగా డైవర్సిఫై అయిందని అతను అనుకుంటున్నాడు. కానీ రెండు ఫండ్లూ ఎక్కువగా అవే పది పెద్ద కంపెనీల షేర్లను కలిగి ఉన్నాయి. సమస్య ఏమిటి?","options":["రెండు ఫండ్లు ఉంచుకోవడం నిబంధనలకు విరుద్ధం","పెద్ద కంపెనీలు ఉన్న ఫండ్లు పడిపోవు","అతని డబ్బు చాలా ఎక్కువ కంపెనీల్లో పంచబడి ఉంది","అతని డబ్బు ఇంకా అవే కంపెనీల్లో కూడి ఉంది"],"answer":"D","explanation":"అవే పది కంపెనీలు నష్టపోతే, రెండు ఫండ్లూ కలిసి పడిపోతాయి. నిజమైన డైవర్సిఫికేషన్ అంటే అన్నీ అవే కంపెనీలపై ఆధారపడని వాటిని కలిగి ఉండటం."}}'::jsonb, null,'invest-diversification','live','ai'),
  ('invest-time-horizon-009','invest', array['time-horizon','risk-and-return'], 'diamond','mcq', '{"en":{"prompt":"Farah has ₹40,000. She needs ₹15,000 for fees next month and wants ₹10,000 kept ready for emergencies. The rest is for a goal 6 years away. How much is free for that long-term goal?","options":["₹25,000","₹30,000","₹15,000","₹40,000"],"answer":"C","explanation":"Fees and emergencies need ₹15,000 + ₹10,000 = ₹25,000, leaving ₹40,000 − ₹25,000 = ₹15,000. Only money not needed soon can wait out ups and downs."},"hi":{"prompt":"फ़राह के पास ₹40,000 हैं। उसे अगले महीने फ़ीस के लिए ₹15,000 चाहिए और वह इमरजेंसी के लिए ₹10,000 तैयार रखना चाहती है। बाकी पैसा 6 साल बाद के एक लक्ष्य के लिए है। उस लंबे समय के लक्ष्य के लिए कितना पैसा बचा है?","options":["₹25,000","₹30,000","₹15,000","₹40,000"],"answer":"C","explanation":"फ़ीस और इमरजेंसी के लिए ₹15,000 + ₹10,000 = ₹25,000 चाहिए, जिससे ₹40,000 − ₹25,000 = ₹15,000 बचते हैं। सिर्फ़ वही पैसा उतार-चढ़ाव के बीत जाने का इंतज़ार कर सकता है, जिसकी जल्दी ज़रूरत न हो।"},"te":{"prompt":"ఫరా దగ్గర ₹40,000 ఉన్నాయి. వచ్చే నెల ఫీజుకు ఆమెకు ₹15,000 కావాలి, ఎమర్జెన్సీ కోసం ₹10,000 సిద్ధంగా ఉంచాలనుకుంటోంది. మిగతాది 6 సంవత్సరాల తర్వాతి లక్ష్యం కోసం. ఆ దీర్ఘకాలిక లక్ష్యానికి ఎంత డబ్బు మిగిలి ఉంది?","options":["₹25,000","₹30,000","₹15,000","₹40,000"],"answer":"C","explanation":"ఫీజు, ఎమర్జెన్సీలకు ₹15,000 + ₹10,000 = ₹25,000 కావాలి, కాబట్టి ₹40,000 − ₹25,000 = ₹15,000 మిగులుతుంది. త్వరలో అవసరం లేని డబ్బు మాత్రమే ఒడిదుడుకులు తగ్గే వరకు ఎదురుచూడగలదు."}}'::jsonb, null,null,'live','ai'),
  ('invest-mutual-fund-basics-007','invest', array['mutual-fund-basics','time-horizon'], 'diamond','mcq', '{"en":{"prompt":"Manoj wants ₹24,000 in 2 years, saved equally each month through a SIP. He gets a ₹4,800 gift to start. Ignoring gains and losses, how much must he add monthly?","options":["₹1,000","₹800","₹1,600","₹200"],"answer":"B","explanation":"He still needs ₹24,000 − ₹4,800 = ₹19,200 over 24 months, which is ₹800 a month. Real returns could make the final amount higher or lower."},"hi":{"prompt":"मनोज को 2 साल में ₹24,000 चाहिए, जो वह SIP के ज़रिए हर महीने बराबर रकम डालकर जमा करेगा। शुरुआत के लिए उसे ₹4,800 का तोहफ़ा मिलता है। फ़ायदे और नुकसान को छोड़कर, उसे हर महीने कितना डालना होगा?","options":["₹1,000","₹800","₹1,600","₹200"],"answer":"B","explanation":"उसे अब भी 24 महीनों में ₹24,000 − ₹4,800 = ₹19,200 चाहिए, यानी हर महीने ₹800। असली रिटर्न की वजह से आखिरी रकम ज़्यादा या कम हो सकती है।"},"te":{"prompt":"మనోజ్‌కు 2 సంవత్సరాల్లో ₹24,000 కావాలి, దాన్ని SIP ద్వారా ప్రతి నెలా సమాన మొత్తం పెట్టి కూడబెడతాడు. మొదలుపెట్టడానికి అతనికి ₹4,800 బహుమతిగా వస్తుంది. లాభనష్టాలను పక్కన పెడితే, అతను ప్రతి నెలా ఎంత పెట్టాలి?","options":["₹1,000","₹800","₹1,600","₹200"],"answer":"B","explanation":"అతనికి ఇంకా ₹24,000 − ₹4,800 = ₹19,200 కావాలి, 24 నెలల్లో, అంటే నెలకు ₹800. నిజమైన రిటర్న్‌ల వల్ల చివరి మొత్తం ఎక్కువ లేదా తక్కువ కావచ్చు."}}'::jsonb, null,null,'live','ai'),
  ('invest-diversification-013','invest', array['diversification','gold-and-fd'], 'diamond','mcq', '{"en":{"prompt":"Nisha splits ₹20,000: ₹10,000 in an FD at an assumed 7%, ₹5,000 in gold and ₹5,000 in a share fund. In one example year, gold rises 10% and the fund falls 20%. Year-end total?","options":["₹20,200","₹19,800","₹19,400","₹21,200"],"answer":"A","explanation":"The FD becomes ₹10,700, gold ₹5,500 and the fund ₹4,000, totalling ₹20,200. Each part''s change must be applied to its own amount."},"hi":{"prompt":"निशा ₹20,000 को बाँटती है: ₹10,000 FD में (मान लें 7% ब्याज), ₹5,000 सोने में और ₹5,000 एक शेयर फ़ंड में। एक उदाहरण वाले साल में सोना 10% बढ़ता है और फ़ंड 20% गिरता है। साल के आखिर में कुल कितना?","options":["₹20,200","₹19,800","₹19,400","₹21,200"],"answer":"A","explanation":"FD ₹10,700, सोना ₹5,500 और फ़ंड ₹4,000 हो जाता है, कुल ₹20,200। हर हिस्से का बदलाव उसकी अपनी रकम पर लगाना होता है।"},"te":{"prompt":"నిషా ₹20,000ను ఇలా పంచుతుంది: ₹10,000 FDలో (7% వడ్డీ అనుకోండి), ₹5,000 బంగారంలో, ₹5,000 ఒక షేర్ ఫండ్‌లో. ఒక ఉదాహరణ సంవత్సరంలో బంగారం 10% పెరుగుతుంది, ఫండ్ 20% పడిపోతుంది. సంవత్సరం చివరికి మొత్తం ఎంత?","options":["₹20,200","₹19,800","₹19,400","₹21,200"],"answer":"A","explanation":"FD ₹10,700, బంగారం ₹5,500, ఫండ్ ₹4,000 అవుతాయి, మొత్తం ₹20,200. ప్రతి భాగం మార్పును దాని సొంత మొత్తానికే లెక్కించాలి."}}'::jsonb, null,null,'live','ai'),
  ('invest-risk-and-return-009','invest', array['risk-and-return'], 'diamond','mcq', '{"en":{"prompt":"Rohan invests ₹10,000. In example years, it rises 50%, then falls 50%, then rises 20%. Ignoring fees, what is it worth after three years?","options":["₹9,000","₹12,000","₹7,500","₹10,000"],"answer":"A","explanation":"₹10,000 becomes ₹15,000, then ₹7,500, then ₹9,000. A 50% fall undoes more than a 50% rise, so the percentages cannot simply be added."},"hi":{"prompt":"रोहन ₹10,000 निवेश करता है। उदाहरण वाले सालों में यह 50% बढ़ता है, फिर 50% गिरता है, फिर 20% बढ़ता है। फ़ीस को छोड़कर, तीन साल बाद इसकी वैल्यू कितनी है?","options":["₹9,000","₹12,000","₹7,500","₹10,000"],"answer":"A","explanation":"₹10,000 पहले ₹15,000, फिर ₹7,500, फिर ₹9,000 हो जाता है। 50% की गिरावट 50% की बढ़त से ज़्यादा असर करती है, इसलिए प्रतिशतों को सीधे जोड़ा नहीं जा सकता।"},"te":{"prompt":"రోహన్ ₹10,000 పెట్టుబడి పెడతాడు. ఉదాహరణ సంవత్సరాల్లో అది 50% పెరిగి, తర్వాత 50% పడిపోయి, ఆ తర్వాత 20% పెరుగుతుంది. ఫీజులను పక్కన పెడితే, మూడు సంవత్సరాల తర్వాత దాని విలువ ఎంత?","options":["₹9,000","₹12,000","₹7,500","₹10,000"],"answer":"A","explanation":"₹10,000 మొదట ₹15,000, తర్వాత ₹7,500, ఆ తర్వాత ₹9,000 అవుతుంది. 50% పతనం 50% పెరుగుదల కంటే ఎక్కువ ప్రభావం చూపిస్తుంది, కాబట్టి శాతాలను నేరుగా కూడలేము."}}'::jsonb, null,null,'live','ai'),
  ('invest-stocks-basics-006','invest', array['stocks-basics'], 'diamond','mcq', '{"en":{"prompt":"Tanvi buys 20 shares at ₹100 each. She gets ₹40 in total dividends (a share of company profits), then sells all at ₹110 each. Ignoring fees and tax, what is her total return?","options":["10%","2%","14%","12%"],"answer":"D","explanation":"She paid ₹2,000 and gained ₹200 from the price rise plus ₹40 in dividends, so ₹240. ₹240 ÷ ₹2,000 = 12%."},"hi":{"prompt":"तन्वी ₹100 प्रति शेयर के दाम पर 20 शेयर खरीदती है। उसे कुल ₹40 डिविडेंड (कंपनी के मुनाफ़े का हिस्सा) मिलता है, फिर वह सारे शेयर ₹110 प्रति शेयर पर बेच देती है। फ़ीस और टैक्स को छोड़कर, उसका कुल रिटर्न कितना है?","options":["10%","2%","14%","12%"],"answer":"D","explanation":"उसने ₹2,000 दिए और दाम बढ़ने से ₹200 तथा डिविडेंड से ₹40 कमाए, यानी कुल ₹240। ₹240 ÷ ₹2,000 = 12%।"},"te":{"prompt":"తన్వి ఒక్కోటి ₹100 చొప్పున 20 షేర్లు కొంటుంది. ఆమెకు మొత్తం ₹40 డివిడెండ్లు (కంపెనీ లాభాల్లో వాటా) వస్తాయి, తర్వాత ఆమె అన్ని షేర్లను ఒక్కోటి ₹110 చొప్పున అమ్మేస్తుంది. ఫీజులు, పన్ను పక్కన పెడితే, ఆమె మొత్తం రిటర్న్ ఎంత?","options":["10%","2%","14%","12%"],"answer":"D","explanation":"ఆమె ₹2,000 చెల్లించింది; ధర పెరగడం వల్ల ₹200, డివిడెండ్ల నుండి ₹40, మొత్తం ₹240 లాభం వచ్చింది. ₹240 ÷ ₹2,000 = 12%."}}'::jsonb, null,null,'live','ai'),
  ('safety-otp-and-pin-001','safety', array['otp-and-pin','upi-fraud'], 'bronze','mcq', '{"en":{"prompt":"A caller says he is from your bank and your KYC expires today. He asks for the OTP you just received. What should you do?","options":["Share it fast so your account is not blocked","Share only the first two digits","Hang up and call the number on your bank card","Ask him to send the request by message"],"answer":"C","explanation":"Banks never ask for your OTP, PIN or password on a call or message. Hang up and call your bank yourself on the number printed on your card."},"hi":{"prompt":"एक कॉलर कहता है कि वह आपके बैंक से है और आपका KYC आज खत्म हो रहा है। वह अभी आया OTP माँगता है। आपको क्या करना चाहिए?","options":["अकाउंट ब्लॉक न हो, इसलिए जल्दी से बता दें","सिर्फ पहले दो अंक बताएँ","फोन काटें और अपने बैंक कार्ड पर लिखे नंबर पर कॉल करें","उससे कहें कि रिक्वेस्ट मैसेज से भेजे"],"answer":"C","explanation":"बैंक कभी भी कॉल या मैसेज पर आपका OTP, PIN या पासवर्ड नहीं माँगते। फोन काटें और अपने कार्ड पर छपे नंबर पर खुद बैंक को कॉल करें।"},"te":{"prompt":"ఒక వ్యక్తి ఫోన్ చేసి, తాను మీ బ్యాంక్ నుంచి మాట్లాడుతున్నానని, మీ KYC ఈరోజుతో ముగుస్తుందని చెప్పాడు. మీకు ఇప్పుడే వచ్చిన OTP చెప్పమని అడుగుతున్నాడు. మీరు ఏం చేయాలి?","options":["అకౌంట్ బ్లాక్ కాకుండా వెంటనే చెప్పేయాలి","మొదటి రెండు అంకెలు మాత్రమే చెప్పాలి","ఫోన్ కట్ చేసి, మీ బ్యాంక్ కార్డు మీద ఉన్న నంబర్‌కు కాల్ చేయాలి","రిక్వెస్ట్‌ను మెసేజ్‌లో పంపమని అడగాలి"],"answer":"C","explanation":"బ్యాంకులు ఎప్పుడూ కాల్‌లో గానీ మెసేజ్‌లో గానీ మీ OTP, PIN లేదా పాస్‌వర్డ్ అడగవు. ఫోన్ కట్ చేసి, మీ కార్డు మీద ముద్రించిన నంబర్‌కు మీరే బ్యాంక్‌కు కాల్ చేయండి."}}'::jsonb, 'safety-never-share-otp',null,'live','ai'),
  ('safety-phishing-001','safety', array['phishing','ponzi-and-chit-scams'], 'bronze','mcq', '{"en":{"prompt":"A message says: \"You won ₹25 lakh! Pay a ₹2,000 processing fee to claim it.\" What is the biggest red flag?","options":["You must pay money first to get the prize","The prize amount is too small to be real","The message did not ask for your OTP","It came as a message, not a letter"],"answer":"A","explanation":"Real prizes never charge you a fee before you get them. Asking you to pay first is a classic scam sign."},"hi":{"prompt":"एक मैसेज आता है: \"आपने ₹25 लाख जीते हैं! इनाम पाने के लिए ₹2,000 प्रोसेसिंग फीस भरें।\" सबसे बड़ा खतरे का संकेत क्या है?","options":["इनाम पाने से पहले आपको पैसे भरने होंगे","इनाम की रकम इतनी छोटी है कि असली नहीं लगती","मैसेज ने आपका OTP नहीं माँगा","यह चिट्ठी की जगह मैसेज से आया"],"answer":"A","explanation":"असली इनाम देने से पहले कभी फीस नहीं ली जाती। पहले पैसे भरने को कहना ठगी का जाना-पहचाना संकेत है।"},"te":{"prompt":"ఒక మెసేజ్ ఇలా ఉంది: \"మీరు ₹25 లక్షలు గెలిచారు! బహుమతి పొందడానికి ₹2,000 ప్రాసెసింగ్ ఫీజు కట్టండి.\" ఇందులో అతి పెద్ద ప్రమాద సంకేతం ఏది?","options":["బహుమతి పొందే ముందే మీరు డబ్బు కట్టాలి","బహుమతి మొత్తం నిజమని నమ్మలేనంత చిన్నది","మెసేజ్ మీ OTP అడగలేదు","ఇది ఉత్తరం కాకుండా మెసేజ్‌గా వచ్చింది"],"answer":"A","explanation":"నిజమైన బహుమతులు ఇచ్చే ముందు ఎప్పుడూ ఫీజు తీసుకోరు. ముందు డబ్బు కట్టమనడం మోసానికి బాగా తెలిసిన సంకేతం."}}'::jsonb, 'safety-spot-the-scam',null,'live','ai'),
  ('safety-upi-fraud-001','safety', array['upi-fraud','otp-and-pin'], 'bronze','mcq', '{"en":{"prompt":"Kavya is selling old books. The buyer says, \"Enter your UPI PIN so you can receive ₹300.\" What is true?","options":["You must enter your PIN to receive any money","You never need a UPI PIN to receive money","A PIN is needed only for amounts above ₹200","A PIN is needed only when the buyer is a stranger"],"answer":"B","explanation":"Money comes into your account without your PIN. Entering your UPI PIN always approves money going out."},"hi":{"prompt":"काव्या अपनी पुरानी किताबें बेच रही है। खरीदार कहता है, \"₹300 पाने के लिए अपना UPI PIN डालो।\" क्या सही है?","options":["कोई भी पैसा पाने के लिए PIN डालना ज़रूरी है","पैसे पाने के लिए कभी UPI PIN की ज़रूरत नहीं होती","PIN सिर्फ ₹200 से ज़्यादा की रकम के लिए चाहिए","PIN सिर्फ तब चाहिए जब खरीदार अनजान हो"],"answer":"B","explanation":"पैसा आपके PIN के बिना ही आपके अकाउंट में आ जाता है। UPI PIN डालने का मतलब हमेशा पैसा बाहर भेजने की मंज़ूरी देना है।"},"te":{"prompt":"కావ్య తన పాత పుస్తకాలు అమ్ముతోంది. కొనే వ్యక్తి \"₹300 రావాలంటే మీ UPI PIN ఎంటర్ చేయండి\" అంటున్నాడు. ఏది నిజం?","options":["ఏ డబ్బు అందుకోవాలన్నా PIN ఎంటర్ చేయాలి","డబ్బు అందుకోవడానికి UPI PIN ఎప్పుడూ అవసరం లేదు","₹200 కంటే ఎక్కువ మొత్తానికి మాత్రమే PIN అవసరం","కొనే వ్యక్తి తెలియనివాడైతేనే PIN అవసరం"],"answer":"B","explanation":"మీ PIN లేకుండానే డబ్బు మీ అకౌంట్‌లోకి వస్తుంది. UPI PIN ఎంటర్ చేశారంటే ఎప్పుడూ డబ్బు బయటకు వెళ్లడానికి అనుమతి ఇస్తున్నారని అర్థం."}}'::jsonb, null,'safety-upi-and-otp','live','ai'),
  ('safety-otp-and-pin-002','safety', array['otp-and-pin'], 'bronze','mcq', '{"en":{"prompt":"Your bank sends you a one-time password (OTP). Who is it meant for?","options":["Bank staff who call to check your account","A delivery person who asks for it at the door","A friend helping you set up your app","Only you, to approve your own payment or login"],"answer":"D","explanation":"An OTP proves that you yourself are approving an action. Anyone who has it can act as you, so it is never shared."},"hi":{"prompt":"आपका बैंक आपको एक वन-टाइम पासवर्ड (OTP) भेजता है। यह किसके लिए है?","options":["बैंक स्टाफ के लिए, जो आपका अकाउंट चेक करने के लिए कॉल करते हैं","डिलीवरी वाले के लिए, जो दरवाज़े पर इसे माँगता है","उस दोस्त के लिए, जो आपका ऐप सेट करने में मदद कर रहा है","सिर्फ आपके लिए, अपना पेमेंट या लॉगिन मंज़ूर करने के लिए"],"answer":"D","explanation":"OTP यह साबित करता है कि कोई काम आप खुद मंज़ूर कर रहे हैं। जिसके पास यह हो, वह आपकी जगह काम कर सकता है, इसलिए इसे कभी किसी को नहीं बताया जाता।"},"te":{"prompt":"మీ బ్యాంక్ మీకు వన్-టైమ్ పాస్‌వర్డ్ (OTP) పంపుతుంది. అది ఎవరి కోసం?","options":["మీ అకౌంట్ చెక్ చేయడానికి కాల్ చేసే బ్యాంక్ సిబ్బంది కోసం","ఇంటి దగ్గరికి వచ్చి అడిగే డెలివరీ వ్యక్తి కోసం","మీ యాప్ సెటప్ చేయడంలో సాయం చేస్తున్న ఫ్రెండ్ కోసం","మీ ఒక్కరి కోసమే, మీ పేమెంట్ లేదా లాగిన్‌ను మీరు ఆమోదించడానికి"],"answer":"D","explanation":"ఒక పనిని మీరే స్వయంగా ఆమోదిస్తున్నారని OTP రుజువు చేస్తుంది. అది ఎవరి దగ్గర ఉన్నా వాళ్లు మీలాగా పనులు చేయగలరు, అందుకే దాన్ని ఎప్పుడూ ఎవరికీ చెప్పకూడదు."}}'::jsonb, null,'safety-upi-and-otp','live','ai'),
  ('safety-upi-fraud-002','safety', array['upi-fraud'], 'bronze','mcq', '{"en":{"prompt":"On a UPI app, what happens when you approve a \"collect request\" with your UPI PIN?","options":["Money comes into your account","Your KYC details get updated","Money goes out of your account","You receive a cashback reward"],"answer":"C","explanation":"A collect request asks you to pay someone. Approving it with your PIN sends money from your account to them."},"hi":{"prompt":"UPI ऐप पर जब आप किसी \"कलेक्ट रिक्वेस्ट\" को अपने UPI PIN से मंज़ूर करते हैं, तो क्या होता है?","options":["आपके अकाउंट में पैसा आता है","आपकी KYC जानकारी अपडेट हो जाती है","आपके अकाउंट से पैसा बाहर जाता है","आपको कैशबैक इनाम मिलता है"],"answer":"C","explanation":"कलेक्ट रिक्वेस्ट आपसे किसी को पेमेंट करने को कहती है। PIN से इसे मंज़ूर करने पर आपके अकाउंट से पैसा उनके पास चला जाता है।"},"te":{"prompt":"UPI యాప్‌లో \"కలెక్ట్ రిక్వెస్ట్\"ను మీ UPI PINతో ఆమోదిస్తే ఏం జరుగుతుంది?","options":["మీ అకౌంట్‌లోకి డబ్బు వస్తుంది","మీ KYC వివరాలు అప్‌డేట్ అవుతాయి","మీ అకౌంట్ నుంచి డబ్బు బయటకు వెళ్తుంది","మీకు క్యాష్‌బ్యాక్ రివార్డ్ వస్తుంది"],"answer":"C","explanation":"కలెక్ట్ రిక్వెస్ట్ అంటే ఎవరికైనా డబ్బు చెల్లించమని మిమ్మల్ని అడగడం. PINతో దాన్ని ఆమోదిస్తే మీ అకౌంట్ నుంచి డబ్బు వాళ్లకు వెళ్తుంది."}}'::jsonb, null,'safety-upi-and-otp','live','ai'),
  ('safety-otp-and-pin-003','safety', array['otp-and-pin','upi-fraud'], 'bronze','mcq', '{"en":{"prompt":"Who should know your UPI PIN?","options":["Only you","You and your bank''s customer care","You and your closest friend","Anyone who sends you money"],"answer":"A","explanation":"Your UPI PIN works like the key to your account. No real bank, friend or buyer ever needs it."},"hi":{"prompt":"आपका UPI PIN किसे पता होना चाहिए?","options":["सिर्फ आपको","आपको और आपके बैंक के कस्टमर केयर को","आपको और आपके सबसे करीबी दोस्त को","हर उस व्यक्ति को जो आपको पैसे भेजता है"],"answer":"A","explanation":"आपका UPI PIN आपके अकाउंट की चाबी जैसा है। किसी असली बैंक, दोस्त या खरीदार को इसकी कभी ज़रूरत नहीं होती।"},"te":{"prompt":"మీ UPI PIN ఎవరికి తెలిసి ఉండాలి?","options":["మీకు మాత్రమే","మీకు, మీ బ్యాంక్ కస్టమర్ కేర్‌కు","మీకు, మీ బెస్ట్ ఫ్రెండ్‌కు","మీకు డబ్బు పంపే ప్రతి ఒక్కరికీ"],"answer":"A","explanation":"మీ UPI PIN మీ అకౌంట్ తాళం చెవి లాంటిది. నిజమైన బ్యాంక్‌కు గానీ, ఫ్రెండ్‌కు గానీ, కొనేవాళ్లకు గానీ అది ఎప్పుడూ అవసరం లేదు."}}'::jsonb, null,'safety-upi-and-otp','live','ai'),
  ('safety-otp-and-pin-004','safety', array['otp-and-pin','upi-fraud'], 'bronze','mcq', '{"en":{"prompt":"Which of these is the safest habit for your UPI PIN?","options":["Use your birth year so it is easy to remember","Cover the keypad and never write the PIN down","Save it in your phone notes for quick access","Use 1234 so you can type it fast"],"answer":"B","explanation":"Hiding the keypad and keeping the PIN only in your memory stops others from seeing or finding it. Birth years and simple numbers are easy to guess."},"hi":{"prompt":"आपके UPI PIN के लिए इनमें से सबसे सुरक्षित आदत कौन-सी है?","options":["अपना जन्म का साल रखें ताकि याद रखना आसान हो","कीपैड को ढककर रखें और PIN कभी कहीं न लिखें","जल्दी देखने के लिए इसे फोन के नोट्स में सेव करें","1234 रखें ताकि जल्दी टाइप कर सकें"],"answer":"B","explanation":"कीपैड छिपाकर रखने और PIN सिर्फ अपनी याद में रखने से कोई उसे देख या ढूँढ नहीं पाता। जन्म का साल और आसान नंबर आसानी से अंदाज़ा लगाए जा सकते हैं।"},"te":{"prompt":"మీ UPI PIN విషయంలో వీటిలో అత్యంత సురక్షితమైన అలవాటు ఏది?","options":["గుర్తుంచుకోవడం సులువని మీ పుట్టిన సంవత్సరం పెట్టుకోవడం","కీప్యాడ్‌ను కవర్ చేసి, PIN ఎక్కడా రాయకపోవడం","త్వరగా చూసుకోవడానికి ఫోన్ నోట్స్‌లో సేవ్ చేయడం","వేగంగా టైప్ చేయడానికి 1234 పెట్టుకోవడం"],"answer":"B","explanation":"కీప్యాడ్ కనిపించకుండా చేసి, PIN మీ జ్ఞాపకంలో మాత్రమే ఉంచితే వేరేవాళ్లు దాన్ని చూడలేరు, కనిపెట్టలేరు. పుట్టిన సంవత్సరం, సులువైన నంబర్లను ఈజీగా ఊహించేయొచ్చు."}}'::jsonb, null,'safety-upi-and-otp','live','ai'),
  ('safety-insurance-basics-001','safety', array['insurance-basics'], 'bronze','mcq', '{"en":{"prompt":"What is insurance mainly for?","options":["Growing your money quickly like a business","Getting a fixed income every month","Protecting you from a big loss you cannot afford","Avoiding all taxes on your savings"],"answer":"C","explanation":"With insurance, many people pay small amounts so that the few who face a big loss get help. Its job is protection, not growing money."},"hi":{"prompt":"बीमा (इंश्योरेंस) मुख्य रूप से किसलिए होता है?","options":["किसी बिज़नेस की तरह पैसा जल्दी बढ़ाने के लिए","हर महीने एक तय आमदनी पाने के लिए","ऐसे बड़े नुकसान से बचाने के लिए जिसे आप झेल नहीं सकते","अपनी बचत पर सारे टैक्स से बचने के लिए"],"answer":"C","explanation":"बीमा में बहुत-से लोग थोड़ी-थोड़ी रकम भरते हैं, ताकि जिन कुछ लोगों को बड़ा नुकसान हो, उन्हें मदद मिल सके। इसका काम सुरक्षा देना है, पैसा बढ़ाना नहीं।"},"te":{"prompt":"ఇన్సూరెన్స్ (బీమా) ముఖ్యంగా దేని కోసం?","options":["ఒక బిజినెస్ లాగా డబ్బును త్వరగా పెంచడానికి","ప్రతి నెలా స్థిరమైన ఆదాయం పొందడానికి","మీరు భరించలేని పెద్ద నష్టం నుంచి మిమ్మల్ని కాపాడడానికి","మీ పొదుపుపై అన్ని పన్నుల నుంచి తప్పించుకోవడానికి"],"answer":"C","explanation":"ఇన్సూరెన్స్‌లో చాలామంది చిన్న చిన్న మొత్తాలు కడతారు, దాంతో పెద్ద నష్టం వచ్చిన కొద్దిమందికి సాయం అందుతుంది. దీని పని రక్షణ ఇవ్వడం, డబ్బు పెంచడం కాదు."}}'::jsonb, null,null,'live','ai'),
  ('safety-insurance-basics-002','safety', array['insurance-basics'], 'bronze','mcq', '{"en":{"prompt":"In insurance, what is a \"premium\"?","options":["The money the insurer pays you after a claim","A bonus for staying healthy all year","A fine for making a claim late","The amount you pay to keep your cover active"],"answer":"D","explanation":"The premium is what you pay, yearly or monthly, to stay insured. The money the insurer pays you is the claim amount."},"hi":{"prompt":"बीमा में \"प्रीमियम\" क्या होता है?","options":["क्लेम के बाद बीमा कंपनी आपको जो पैसा देती है","पूरे साल स्वस्थ रहने का बोनस","देर से क्लेम करने पर लगने वाला जुर्माना","अपना कवर चालू रखने के लिए आप जो रकम भरते हैं"],"answer":"D","explanation":"प्रीमियम वह रकम है जो आप बीमा चालू रखने के लिए सालाना या हर महीने भरते हैं। बीमा कंपनी आपको जो पैसा देती है, वह क्लेम की रकम होती है।"},"te":{"prompt":"ఇన్సూరెన్స్‌లో \"ప్రీమియం\" అంటే ఏమిటి?","options":["క్లెయిమ్ తర్వాత ఇన్సూరెన్స్ కంపెనీ మీకు ఇచ్చే డబ్బు","ఏడాదంతా ఆరోగ్యంగా ఉన్నందుకు ఇచ్చే బోనస్","క్లెయిమ్ ఆలస్యంగా చేసినందుకు వేసే జరిమానా","మీ కవర్ కొనసాగడానికి మీరు కట్టే మొత్తం"],"answer":"D","explanation":"ప్రీమియం అంటే ఇన్సూరెన్స్ కొనసాగడానికి మీరు ఏడాదికి లేదా నెలకు కట్టే డబ్బు. ఇన్సూరెన్స్ కంపెనీ మీకు ఇచ్చే డబ్బును క్లెయిమ్ మొత్తం అంటారు."}}'::jsonb, null,null,'live','ai'),
  ('safety-phishing-002','safety', array['phishing'], 'bronze','mcq', '{"en":{"prompt":"What is phishing?","options":["An official SMS from your bank about a new rule","A fake message pretending to be trusted, to steal details","A virus that only affects computers","A loan offer from a registered bank"],"answer":"B","explanation":"Phishing messages copy the look of a bank or company to trick you. They try to get your passwords, OTPs or card details."},"hi":{"prompt":"फ़िशिंग क्या है?","options":["नए नियम के बारे में आपके बैंक का आधिकारिक SMS","भरोसेमंद होने का दिखावा करने वाला नकली मैसेज, जो आपकी जानकारी चुराता है","एक वायरस जो सिर्फ कंप्यूटर पर असर करता है","किसी रजिस्टर्ड बैंक का लोन ऑफ़र"],"answer":"B","explanation":"फ़िशिंग मैसेज आपको धोखा देने के लिए किसी बैंक या कंपनी जैसे दिखते हैं। वे आपके पासवर्ड, OTP या कार्ड की जानकारी हासिल करने की कोशिश करते हैं।"},"te":{"prompt":"ఫిషింగ్ అంటే ఏమిటి?","options":["కొత్త రూల్ గురించి మీ బ్యాంక్ పంపే అధికారిక SMS","నమ్మదగినదిలా నటిస్తూ మీ వివరాలు దొంగిలించే నకిలీ మెసేజ్","కంప్యూటర్లపై మాత్రమే ప్రభావం చూపే వైరస్","రిజిస్టర్డ్ బ్యాంక్ ఇచ్చే లోన్ ఆఫర్"],"answer":"B","explanation":"ఫిషింగ్ మెసేజ్‌లు మిమ్మల్ని మోసం చేయడానికి బ్యాంక్ లేదా కంపెనీ లాగా కనిపిస్తాయి. అవి మీ పాస్‌వర్డ్‌లు, OTPలు లేదా కార్డు వివరాలు రాబట్టడానికి ప్రయత్నిస్తాయి."}}'::jsonb, null,null,'live','ai'),
  ('safety-phishing-003','safety', array['phishing'], 'bronze','mcq', '{"en":{"prompt":"An SMS says your bank account will be blocked and gives a link like \"bank-kyc-update.xyz\". What should you do?","options":["Tap it and fill in details if the logo looks right","Reply to the SMS to ask if it is genuine","Tap it but do not enter your PIN","Ignore the link and check your bank''s official app"],"answer":"D","explanation":"Links in urgent messages often lead to fake pages that steal your details. Checking through your bank''s own app or number is the safe way."},"hi":{"prompt":"एक SMS कहता है कि आपका बैंक अकाउंट ब्लॉक हो जाएगा और \"bank-kyc-update.xyz\" जैसा एक लिंक देता है। आपको क्या करना चाहिए?","options":["लोगो सही दिखे तो उस पर टैप करके जानकारी भर दें","SMS का जवाब देकर पूछें कि यह असली है या नहीं","टैप करें लेकिन अपना PIN न डालें","लिंक को छोड़ दें और अपने बैंक का आधिकारिक ऐप चेक करें"],"answer":"D","explanation":"जल्दबाज़ी वाले मैसेज के लिंक अक्सर नकली पेज पर ले जाते हैं जो आपकी जानकारी चुराते हैं। अपने बैंक के अपने ऐप या नंबर से चेक करना ही सुरक्षित तरीका है।"},"te":{"prompt":"మీ బ్యాంక్ అకౌంట్ బ్లాక్ అవుతుందని ఒక SMS వచ్చింది, అందులో \"bank-kyc-update.xyz\" లాంటి లింక్ ఉంది. మీరు ఏం చేయాలి?","options":["లోగో సరిగ్గా ఉంటే దాన్ని ట్యాప్ చేసి వివరాలు నింపాలి","అది నిజమో కాదో అడుగుతూ SMSకు రిప్లై ఇవ్వాలి","ట్యాప్ చేయాలి కానీ PIN ఎంటర్ చేయకూడదు","లింక్‌ను పట్టించుకోకుండా మీ బ్యాంక్ అధికారిక యాప్‌లో చెక్ చేయాలి"],"answer":"D","explanation":"తొందరపెట్టే మెసేజ్‌లలోని లింక్‌లు తరచూ మీ వివరాలు దొంగిలించే నకిలీ పేజీలకు తీసుకెళ్తాయి. మీ బ్యాంక్ సొంత యాప్ లేదా నంబర్ ద్వారా చెక్ చేయడమే సురక్షితమైన మార్గం."}}'::jsonb, null,null,'live','ai'),
  ('safety-fake-loan-apps-001','safety', array['fake-loan-apps'], 'bronze','mcq', '{"en":{"prompt":"Which of these is a warning sign of a fake loan app?","options":["It asks to access all your contacts and photos","It shows the interest rate clearly before you borrow","It asks for your documents to check who you are","It names an RBI-registered lender you can verify"],"answer":"A","explanation":"Fake loan apps take your contacts and photos so they can harass and shame you later. A real lender has no need for them."},"hi":{"prompt":"इनमें से कौन-सा नकली लोन ऐप का चेतावनी संकेत है?","options":["यह आपके सारे कॉन्टैक्ट्स और फ़ोटो की एक्सेस माँगता है","यह उधार लेने से पहले ब्याज दर साफ़-साफ़ दिखाता है","यह आपकी पहचान जाँचने के लिए डॉक्यूमेंट माँगता है","यह RBI में रजिस्टर्ड किसी लेंडर का नाम बताता है, जिसे आप जाँच सकते हैं"],"answer":"A","explanation":"नकली लोन ऐप आपके कॉन्टैक्ट्स और फ़ोटो इसलिए लेते हैं ताकि बाद में आपको परेशान और शर्मिंदा कर सकें। असली लेंडर को इनकी कोई ज़रूरत नहीं होती।"},"te":{"prompt":"వీటిలో నకిలీ లోన్ యాప్‌కు హెచ్చరిక సంకేతం ఏది?","options":["మీ కాంటాక్ట్‌లు, ఫోటోలు అన్నింటికీ యాక్సెస్ అడుగుతుంది","అప్పు తీసుకునే ముందే వడ్డీ రేటును స్పష్టంగా చూపిస్తుంది","మీరెవరో చెక్ చేయడానికి మీ డాక్యుమెంట్లు అడుగుతుంది","మీరు వెరిఫై చేయగలిగే RBI రిజిస్టర్డ్ లెండర్ పేరు చెబుతుంది"],"answer":"A","explanation":"నకిలీ లోన్ యాప్‌లు తర్వాత మిమ్మల్ని వేధించి, అవమానించడానికే మీ కాంటాక్ట్‌లు, ఫోటోలు తీసుకుంటాయి. నిజమైన లెండర్‌కు వాటి అవసరం ఉండదు."}}'::jsonb, null,null,'live','ai'),
  ('safety-ponzi-and-chit-scams-001','safety', array['ponzi-and-chit-scams'], 'bronze','mcq', '{"en":{"prompt":"A scheme pays its old members using money from new members, not from real earnings. What is this called?","options":["A Ponzi scheme","A fixed deposit","A recurring deposit","An insurance policy"],"answer":"A","explanation":"A Ponzi scheme pays old members with new members'' money. It collapses when new money stops coming in."},"hi":{"prompt":"एक स्कीम अपने पुराने सदस्यों को असली कमाई से नहीं, बल्कि नए सदस्यों के पैसे से भुगतान करती है। इसे क्या कहते हैं?","options":["पोंज़ी स्कीम","फ़िक्स्ड डिपॉज़िट","रिकरिंग डिपॉज़िट","बीमा पॉलिसी"],"answer":"A","explanation":"पोंज़ी स्कीम पुराने सदस्यों को नए सदस्यों के पैसे से भुगतान करती है। जब नया पैसा आना बंद हो जाता है, तो यह ढह जाती है।"},"te":{"prompt":"ఒక స్కీమ్ తన పాత సభ్యులకు నిజమైన సంపాదన నుంచి కాకుండా, కొత్త సభ్యుల డబ్బుతో చెల్లిస్తుంది. దీన్ని ఏమంటారు?","options":["పోంజీ స్కీమ్","ఫిక్స్‌డ్ డిపాజిట్","రికరింగ్ డిపాజిట్","ఇన్సూరెన్స్ పాలసీ"],"answer":"A","explanation":"పోంజీ స్కీమ్ పాత సభ్యులకు కొత్త సభ్యుల డబ్బుతో చెల్లిస్తుంది. కొత్త డబ్బు రావడం ఆగిపోగానే అది కుప్పకూలిపోతుంది."}}'::jsonb, null,null,'live','ai'),
  ('safety-ponzi-and-chit-scams-002','safety', array['ponzi-and-chit-scams'], 'bronze','mcq', '{"en":{"prompt":"Which promise is the clearest sign of an investment scam?","options":["Returns can go up or down","Please read all documents carefully","Past returns do not promise future returns","Your money will surely double in one month"],"answer":"D","explanation":"No one can guarantee such high returns, so a sure-shot promise is a big red flag. Honest offers warn you that returns can change."},"hi":{"prompt":"इनमें से कौन-सा वादा निवेश ठगी का सबसे साफ़ संकेत है?","options":["रिटर्न ऊपर या नीचे जा सकते हैं","कृपया सारे डॉक्यूमेंट ध्यान से पढ़ें","पिछले रिटर्न आगे के रिटर्न की गारंटी नहीं हैं","आपका पैसा एक महीने में पक्का दोगुना हो जाएगा"],"answer":"D","explanation":"इतने ऊँचे रिटर्न की गारंटी कोई नहीं दे सकता, इसलिए \"पक्का\" वाला वादा बड़ा खतरे का संकेत है। ईमानदार ऑफ़र आपको बताते हैं कि रिटर्न बदल सकते हैं।"},"te":{"prompt":"వీటిలో ఏ హామీ పెట్టుబడి మోసానికి అత్యంత స్పష్టమైన సంకేతం?","options":["రిటర్న్స్ పెరగొచ్చు లేదా తగ్గొచ్చు","దయచేసి అన్ని డాక్యుమెంట్లు జాగ్రత్తగా చదవండి","గతంలో వచ్చిన రిటర్న్స్ భవిష్యత్తు రిటర్న్స్‌కు హామీ కాదు","మీ డబ్బు ఒక్క నెలలో ఖచ్చితంగా రెట్టింపు అవుతుంది"],"answer":"D","explanation":"ఇంత ఎక్కువ రిటర్న్స్‌కు ఎవరూ గ్యారెంటీ ఇవ్వలేరు, అందుకే \"ఖచ్చితంగా\" అనే హామీ పెద్ద ప్రమాద సంకేతం. నిజాయితీగల ఆఫర్లు రిటర్న్స్ మారొచ్చని మిమ్మల్ని హెచ్చరిస్తాయి."}}'::jsonb, null,null,'live','ai'),
  ('safety-upi-fraud-003','safety', array['upi-fraud'], 'bronze','mcq', '{"en":{"prompt":"If you lose money in an online fraud, which national cybercrime helpline should you call?","options":["108","101","1930","139"],"answer":"C","explanation":"1930 is the national cybercrime helpline, and you can also report at cybercrime.gov.in. Calling quickly gives the best chance of stopping the money."},"hi":{"prompt":"अगर ऑनलाइन ठगी में आपका पैसा चला जाए, तो आपको किस राष्ट्रीय साइबर क्राइम हेल्पलाइन पर कॉल करना चाहिए?","options":["108","101","1930","139"],"answer":"C","explanation":"1930 राष्ट्रीय साइबर क्राइम हेल्पलाइन है, और आप cybercrime.gov.in पर भी शिकायत कर सकते हैं। जल्दी कॉल करने से पैसा रुकवाने की सबसे अच्छी संभावना रहती है।"},"te":{"prompt":"ఆన్‌లైన్ మోసంలో మీరు డబ్బు పోగొట్టుకుంటే, ఏ జాతీయ సైబర్ క్రైమ్ హెల్ప్‌లైన్‌కు కాల్ చేయాలి?","options":["108","101","1930","139"],"answer":"C","explanation":"1930 జాతీయ సైబర్ క్రైమ్ హెల్ప్‌లైన్, cybercrime.gov.inలో కూడా మీరు ఫిర్యాదు చేయవచ్చు. త్వరగా కాల్ చేస్తే డబ్బును ఆపే అవకాశం ఎక్కువగా ఉంటుంది."}}'::jsonb, null,'safety-money-mule','live','ai'),
  ('safety-upi-fraud-004','safety', array['upi-fraud'], 'silver','mcq', '{"en":{"prompt":"Someone online offers Arjun ₹5,000 to let money pass through his bank account and forward it on. Arjun will not steal anything himself. What is the risk?","options":["None, because Arjun does not steal anything","He becomes part of a fraud; his account can be frozen","Only the person paying him can get in trouble","He only has to pay a little tax on ₹5,000"],"answer":"B","explanation":"Stolen money moving through your account makes you a \"money mule\" and the trail leads to you. Your account can be frozen and you can face a police case."},"hi":{"prompt":"ऑनलाइन कोई अर्जुन को ₹5,000 देने की बात करता है, बस उसे अपने बैंक अकाउंट से पैसा गुज़रने देना है और आगे भेज देना है। अर्जुन खुद कुछ नहीं चुराएगा। इसमें खतरा क्या है?","options":["कोई खतरा नहीं, क्योंकि अर्जुन कुछ नहीं चुराता","वह ठगी का हिस्सा बन जाता है; उसका अकाउंट फ़्रीज़ हो सकता है","सिर्फ उसे पैसे देने वाला ही मुसीबत में पड़ सकता है","उसे ₹5,000 पर बस थोड़ा-सा टैक्स भरना होगा"],"answer":"B","explanation":"चोरी का पैसा आपके अकाउंट से गुज़रे तो आप \"मनी म्यूल\" बन जाते हैं और पैसे का रास्ता आप तक पहुँचता है। आपका अकाउंट फ़्रीज़ हो सकता है और आप पर पुलिस केस भी हो सकता है।"},"te":{"prompt":"ఆన్‌లైన్‌లో ఒకరు అర్జున్‌కు ₹5,000 ఇస్తామంటున్నారు. అతను చేయాల్సిందల్లా తన బ్యాంక్ అకౌంట్‌లోకి వచ్చే డబ్బును ముందుకు పంపడమే. అర్జున్ స్వయంగా ఏమీ దొంగిలించడు. ఇందులో ప్రమాదం ఏమిటి?","options":["ఏ ప్రమాదం లేదు, ఎందుకంటే అర్జున్ ఏమీ దొంగిలించడు","అతను మోసంలో భాగమవుతాడు; అతని అకౌంట్ ఫ్రీజ్ కావచ్చు","అతనికి డబ్బు ఇచ్చే వ్యక్తి మాత్రమే ఇబ్బందుల్లో పడతాడు","₹5,000 మీద కొంచెం పన్ను కడితే చాలు"],"answer":"B","explanation":"దొంగ డబ్బు మీ అకౌంట్ ద్వారా వెళ్తే మీరు \"మనీ మ్యూల్\" అవుతారు, ఆ డబ్బు జాడ మీ దగ్గరికే వస్తుంది. మీ అకౌంట్ ఫ్రీజ్ కావచ్చు, మీపై పోలీస్ కేసు కూడా నమోదు కావచ్చు."}}'::jsonb, 'safety-money-mule',null,'live','ai'),
  ('safety-phishing-004','safety', array['phishing'], 'silver','mcq', '{"en":{"prompt":"Rahul gets an SMS: \"Your electricity will be cut at 9 pm today. Call this mobile number to update your bill.\" What is the safest move?","options":["Call the number quickly to avoid the power cut","Pay the bill through the link in the SMS","Check the bill on the official board website or office","Share his account number so they can verify him"],"answer":"C","explanation":"Scammers use fear and a short deadline to rush you. Checking through the official website or office tells you if any bill is really due."},"hi":{"prompt":"राहुल को SMS आता है: \"आज रात 9 बजे आपकी बिजली काट दी जाएगी। बिल अपडेट करने के लिए इस मोबाइल नंबर पर कॉल करें।\" सबसे सुरक्षित कदम क्या है?","options":["बिजली कटने से बचने के लिए जल्दी से उस नंबर पर कॉल करे","SMS में दिए लिंक से बिल भर दे","बिजली बोर्ड की आधिकारिक वेबसाइट या ऑफ़िस से बिल चेक करे","वेरिफ़ाई करने के लिए अपना अकाउंट नंबर बता दे"],"answer":"C","explanation":"ठग डर और कम समय का दबाव डालकर आपको जल्दबाज़ी में डालते हैं। आधिकारिक वेबसाइट या ऑफ़िस से चेक करने पर पता चलता है कि सच में कोई बिल बाकी है या नहीं।"},"te":{"prompt":"రాహుల్‌కు ఒక SMS వచ్చింది: \"ఈరోజు రాత్రి 9 గంటలకు మీ కరెంట్ కట్ చేస్తాం. బిల్ అప్‌డేట్ చేయడానికి ఈ మొబైల్ నంబర్‌కు కాల్ చేయండి.\" అత్యంత సురక్షితమైన పని ఏది?","options":["కరెంట్ కట్ కాకుండా వెంటనే ఆ నంబర్‌కు కాల్ చేయడం","SMSలో ఉన్న లింక్ ద్వారా బిల్ కట్టడం","అధికారిక విద్యుత్ బోర్డు వెబ్‌సైట్ లేదా ఆఫీసులో బిల్ చెక్ చేయడం","వెరిఫై చేయడానికి తన అకౌంట్ నంబర్ ఇవ్వడం"],"answer":"C","explanation":"మోసగాళ్లు భయం, తక్కువ గడువు చూపించి మిమ్మల్ని తొందరపెడతారు. అధికారిక వెబ్‌సైట్ లేదా ఆఫీసులో చెక్ చేస్తే నిజంగా బిల్ బాకీ ఉందో లేదో తెలుస్తుంది."}}'::jsonb, null,'safety-spot-the-scam','live','ai'),
  ('safety-fake-loan-apps-002','safety', array['fake-loan-apps'], 'silver','mcq', '{"en":{"prompt":"Imran needs ₹3,000. An app offers \"Instant loan, no documents, approved in 2 minutes\" and wants access to his contacts. How should he see this?","options":["It is fast, so it must be modern and safe","No documents means the lender is friendly","It is fine if he deletes the app after the loan","These are warning signs; check if the lender is RBI-registered"],"answer":"D","explanation":"No checks, very fast approval and contact access are typical signs of a fake loan app. Real lenders are registered with the RBI and check documents."},"hi":{"prompt":"इमरान को ₹3,000 चाहिए। एक ऐप \"तुरंत लोन, कोई डॉक्यूमेंट नहीं, 2 मिनट में मंज़ूर\" ऑफ़र करता है और उसके कॉन्टैक्ट्स की एक्सेस माँगता है। उसे इसे कैसे देखना चाहिए?","options":["यह तेज़ है, तो ज़रूर मॉडर्न और सुरक्षित होगा","कोई डॉक्यूमेंट नहीं, मतलब लेंडर मददगार है","लोन के बाद ऐप डिलीट कर दे तो कोई दिक्कत नहीं","ये चेतावनी संकेत हैं; जाँचे कि लेंडर RBI में रजिस्टर्ड है या नहीं"],"answer":"D","explanation":"कोई जाँच नहीं, बहुत तेज़ मंज़ूरी और कॉन्टैक्ट्स की एक्सेस नकली लोन ऐप के आम संकेत हैं। असली लेंडर RBI में रजिस्टर्ड होते हैं और डॉक्यूमेंट जाँचते हैं।"},"te":{"prompt":"ఇమ్రాన్‌కు ₹3,000 కావాలి. ఒక యాప్ \"తక్షణ లోన్, డాక్యుమెంట్లు అక్కర్లేదు, 2 నిమిషాల్లో ఆమోదం\" అని ఆఫర్ ఇస్తూ, అతని కాంటాక్ట్‌లకు యాక్సెస్ అడుగుతోంది. అతను దీన్ని ఎలా చూడాలి?","options":["ఇది వేగంగా ఉంది కాబట్టి మోడర్న్‌గా, సురక్షితంగా ఉంటుంది","డాక్యుమెంట్లు అక్కర్లేదంటే లెండర్ మంచివాడని అర్థం","లోన్ తీసుకున్నాక యాప్ డిలీట్ చేస్తే సరిపోతుంది","ఇవి హెచ్చరిక సంకేతాలు; లెండర్ RBIలో రిజిస్టర్ అయ్యాడో లేదో చెక్ చేయాలి"],"answer":"D","explanation":"ఎలాంటి చెకింగ్ లేకపోవడం, చాలా వేగమైన ఆమోదం, కాంటాక్ట్‌ల యాక్సెస్ అడగడం నకిలీ లోన్ యాప్‌ల సాధారణ సంకేతాలు. నిజమైన లెండర్లు RBIలో రిజిస్టర్ అయి ఉంటారు, డాక్యుమెంట్లు చెక్ చేస్తారు."}}'::jsonb, null,'safety-spot-the-scam','live','ai'),
  ('safety-ponzi-and-chit-scams-003','safety', array['ponzi-and-chit-scams'], 'silver','mcq', '{"en":{"prompt":"Lakshmi''s neighbour says: \"Pay ₹1,000 to join, then earn ₹500 for every friend you bring in.\" There is no real product. What is this most likely?","options":["A pyramid-style scheme that will collapse","A safe savings plan","A bank recurring deposit","A government welfare scheme"],"answer":"A","explanation":"When earnings come only from recruiting new people, the scheme runs out of new members and collapses. Most people who join late lose their money."},"hi":{"prompt":"लक्ष्मी के पड़ोसी का कहना है: \"जुड़ने के लिए ₹1,000 दो, फिर हर दोस्त को लाने पर ₹500 कमाओ।\" कोई असली प्रोडक्ट नहीं है। यह सबसे ज़्यादा क्या हो सकता है?","options":["पिरामिड जैसी स्कीम, जो ढह जाएगी","एक सुरक्षित बचत योजना","बैंक का रिकरिंग डिपॉज़िट","सरकार की कल्याण योजना"],"answer":"A","explanation":"जब कमाई सिर्फ नए लोगों को जोड़ने से होती है, तो एक समय नए सदस्य मिलना बंद हो जाते हैं और स्कीम ढह जाती है। देर से जुड़ने वाले ज़्यादातर लोगों का पैसा डूब जाता है।"},"te":{"prompt":"లక్ష్మి పక్కింటి వాళ్లు ఇలా అంటున్నారు: \"చేరడానికి ₹1,000 కట్టు, తర్వాత నువ్వు తెచ్చే ప్రతి ఫ్రెండ్‌కు ₹500 సంపాదించు.\" అసలు ఏ ప్రొడక్ట్ లేదు. ఇది ఎక్కువగా ఏది అయ్యుండొచ్చు?","options":["కుప్పకూలిపోయే పిరమిడ్ తరహా స్కీమ్","సురక్షితమైన పొదుపు పథకం","బ్యాంక్ రికరింగ్ డిపాజిట్","ప్రభుత్వ సంక్షేమ పథకం"],"answer":"A","explanation":"కొత్తవాళ్లను చేర్పించడం ద్వారా మాత్రమే సంపాదన వస్తే, కొత్త సభ్యులు దొరకడం ఆగిపోయి స్కీమ్ కుప్పకూలుతుంది. ఆలస్యంగా చేరిన చాలామంది తమ డబ్బు పోగొట్టుకుంటారు."}}'::jsonb, null,'safety-spot-the-scam','live','ai'),
  ('safety-ponzi-and-chit-scams-004','safety', array['ponzi-and-chit-scams'], 'silver','mcq', '{"en":{"prompt":"Sunita''s aunt wants to join a chit fund run by someone new to the area. He promises very high returns and shows no papers. What should she ask first?","options":["How many people have already joined?","Can I pay my share in cash?","Is this chit fund officially registered?","Will I get a gift for joining?"],"answer":"C","explanation":"Registered chit funds must follow rules and keep records, so members can complain if something goes wrong. An unregistered one can vanish with everyone''s money."},"hi":{"prompt":"सुनीता की चाची एक चिट फ़ंड से जुड़ना चाहती हैं, जिसे इलाके में नया आया एक आदमी चला रहा है। वह बहुत ऊँचे रिटर्न का वादा करता है और कोई कागज़ नहीं दिखाता। उन्हें सबसे पहले क्या पूछना चाहिए?","options":["अब तक कितने लोग जुड़ चुके हैं?","क्या मैं अपना हिस्सा नकद में दे सकती हूँ?","क्या यह चिट फ़ंड आधिकारिक रूप से रजिस्टर्ड है?","क्या जुड़ने पर मुझे कोई गिफ़्ट मिलेगा?"],"answer":"C","explanation":"रजिस्टर्ड चिट फ़ंड को नियम मानने पड़ते हैं और रिकॉर्ड रखना पड़ता है, इसलिए कुछ गलत होने पर सदस्य शिकायत कर सकते हैं। बिना रजिस्ट्रेशन वाला चिट फ़ंड सबका पैसा लेकर गायब हो सकता है।"},"te":{"prompt":"సునీత అత్తయ్య ఆ ప్రాంతానికి కొత్తగా వచ్చిన ఒక వ్యక్తి నడుపుతున్న చిట్ ఫండ్‌లో చేరాలనుకుంటోంది. అతను చాలా ఎక్కువ రిటర్న్స్ ఇస్తానంటున్నాడు, కానీ ఏ కాగితాలూ చూపించడం లేదు. ఆమె ముందుగా ఏం అడగాలి?","options":["ఇప్పటికే ఎంతమంది చేరారు?","నా వాటాను నగదుగా కట్టొచ్చా?","ఈ చిట్ ఫండ్ అధికారికంగా రిజిస్టర్ అయిందా?","చేరితే నాకు ఏదైనా గిఫ్ట్ ఇస్తారా?"],"answer":"C","explanation":"రిజిస్టర్డ్ చిట్ ఫండ్‌లు నియమాలు పాటించాలి, రికార్డులు ఉంచాలి, కాబట్టి ఏదైనా తప్పు జరిగితే సభ్యులు ఫిర్యాదు చేయవచ్చు. రిజిస్టర్ కాని చిట్ ఫండ్ అందరి డబ్బుతో మాయమైపోవచ్చు."}}'::jsonb, null,'safety-spot-the-scam','live','ai'),
  ('safety-ponzi-and-chit-scams-005','safety', array['ponzi-and-chit-scams','phishing'], 'silver','mcq', '{"en":{"prompt":"Divya joins an online task: \"Like videos, earn ₹200 each.\" She is paid ₹200 at first. Now she is asked to deposit ₹5,000 to unlock \"premium tasks\". What is happening?","options":["This is a normal step in online part-time jobs","The small payment built trust before a bigger scam","Her earnings are being taxed by the company","The company is checking that her bank works"],"answer":"B","explanation":"Task scams pay a little at first so you trust them. Then they ask you to put in bigger amounts and disappear with it."},"hi":{"prompt":"दिव्या एक ऑनलाइन टास्क से जुड़ती है: \"वीडियो लाइक करो, हर एक पर ₹200 कमाओ।\" शुरू में उसे ₹200 मिलते हैं। अब उससे \"प्रीमियम टास्क\" अनलॉक करने के लिए ₹5,000 जमा करने को कहा जा रहा है। क्या हो रहा है?","options":["ऑनलाइन पार्ट-टाइम जॉब में यह एक आम कदम है","छोटे भुगतान से भरोसा जीता गया, अब बड़ी ठगी की तैयारी है","कंपनी उसकी कमाई पर टैक्स काट रही है","कंपनी चेक कर रही है कि उसका बैंक ठीक चलता है या नहीं"],"answer":"B","explanation":"टास्क वाली ठगी में शुरू में थोड़ा पैसा दिया जाता है ताकि आप भरोसा करें। फिर वे आपसे बड़ी रकम डलवाते हैं और उसे लेकर गायब हो जाते हैं।"},"te":{"prompt":"దివ్య ఒక ఆన్‌లైన్ టాస్క్‌లో చేరింది: \"వీడియోలు లైక్ చేయండి, ఒక్కోదానికి ₹200 సంపాదించండి.\" మొదట్లో ఆమెకు ₹200 వచ్చాయి. ఇప్పుడు \"ప్రీమియం టాస్క్‌లు\" అన్‌లాక్ చేయడానికి ₹5,000 డిపాజిట్ చేయమని అడుగుతున్నారు. ఏం జరుగుతోంది?","options":["ఆన్‌లైన్ పార్ట్-టైమ్ జాబ్‌లలో ఇది మామూలు స్టెప్","చిన్న చెల్లింపుతో నమ్మకం కలిగించి, పెద్ద మోసానికి సిద్ధం చేశారు","కంపెనీ ఆమె సంపాదనపై పన్ను వేస్తోంది","ఆమె బ్యాంక్ పనిచేస్తోందో లేదో కంపెనీ చెక్ చేస్తోంది"],"answer":"B","explanation":"టాస్క్ మోసాల్లో మొదట కొంచెం డబ్బు ఇచ్చి మీకు నమ్మకం కలిగిస్తారు. తర్వాత పెద్ద మొత్తాలు పెట్టమని అడిగి, ఆ డబ్బుతో మాయమైపోతారు."}}'::jsonb, null,'safety-spot-the-scam','live','ai'),
  ('safety-upi-fraud-005','safety', array['upi-fraud'], 'silver','mcq', '{"en":{"prompt":"Mohan is selling his old phone online. The buyer sends a QR code and says, \"Scan this and enter your PIN to receive ₹4,000.\" What is true?","options":["Scanning and entering the PIN is how you receive money","Scan it, but try a small amount first","Scanning a QR code and entering a PIN sends money out","Scan it only if the buyer seems polite"],"answer":"C","explanation":"Scanning a QR code is for paying, not receiving. You never need to scan anything or enter a PIN to get money."},"hi":{"prompt":"मोहन अपना पुराना फोन ऑनलाइन बेच रहा है। खरीदार एक QR कोड भेजता है और कहता है, \"₹4,000 पाने के लिए इसे स्कैन करो और अपना PIN डालो।\" क्या सही है?","options":["स्कैन करके PIN डालना ही पैसे पाने का तरीका है","स्कैन करे, लेकिन पहले छोटी रकम से आज़माए","QR कोड स्कैन करके PIN डालने से पैसा बाहर जाता है","खरीदार अच्छे से बात करे, तभी स्कैन करे"],"answer":"C","explanation":"QR कोड स्कैन करना पेमेंट करने के लिए होता है, पैसे पाने के लिए नहीं। पैसे पाने के लिए आपको कभी कुछ स्कैन करने या PIN डालने की ज़रूरत नहीं होती।"},"te":{"prompt":"మోహన్ తన పాత ఫోన్‌ను ఆన్‌లైన్‌లో అమ్ముతున్నాడు. కొనే వ్యక్తి ఒక QR కోడ్ పంపి, \"₹4,000 రావాలంటే దీన్ని స్కాన్ చేసి మీ PIN ఎంటర్ చేయండి\" అంటున్నాడు. ఏది నిజం?","options":["స్కాన్ చేసి PIN ఎంటర్ చేయడమే డబ్బు అందుకునే పద్ధతి","స్కాన్ చేయాలి, కానీ ముందు చిన్న మొత్తంతో ట్రై చేయాలి","QR కోడ్ స్కాన్ చేసి PIN ఎంటర్ చేస్తే డబ్బు బయటకు వెళ్తుంది","కొనే వ్యక్తి మర్యాదగా మాట్లాడితేనే స్కాన్ చేయాలి"],"answer":"C","explanation":"QR కోడ్ స్కాన్ చేసేది డబ్బు చెల్లించడానికి, అందుకోవడానికి కాదు. డబ్బు అందుకోవడానికి మీరు ఏదీ స్కాన్ చేయాల్సిన అవసరం గానీ, PIN ఎంటర్ చేయాల్సిన అవసరం గానీ ఉండదు."}}'::jsonb, null,null,'live','ai'),
  ('safety-otp-and-pin-005','safety', array['otp-and-pin'], 'silver','mcq', '{"en":{"prompt":"A \"customer care\" caller asks Pooja to install a screen-sharing app so he can fix her failed payment. What should she do?","options":["Refuse; such apps let strangers control her phone","Install it so they can fix the problem faster","Install it but close it after five minutes","Install it if the caller knows her name"],"answer":"A","explanation":"Screen-sharing apps let the caller see your OTPs and PIN and even control your phone. Real support never needs this."},"hi":{"prompt":"एक \"कस्टमर केयर\" कॉलर पूजा से एक स्क्रीन-शेयरिंग ऐप इंस्टॉल करने को कहता है, ताकि वह उसका फ़ेल हुआ पेमेंट ठीक कर सके। उसे क्या करना चाहिए?","options":["मना कर दे; ऐसे ऐप से अनजान लोग उसका फोन कंट्रोल कर सकते हैं","इंस्टॉल कर ले ताकि वे समस्या जल्दी ठीक कर सकें","इंस्टॉल करे लेकिन पाँच मिनट बाद बंद कर दे","अगर कॉलर उसका नाम जानता है तो इंस्टॉल कर ले"],"answer":"A","explanation":"स्क्रीन-शेयरिंग ऐप से कॉलर आपके OTP और PIN देख सकता है और आपका फोन कंट्रोल भी कर सकता है। असली सपोर्ट को इसकी कभी ज़रूरत नहीं होती।"},"te":{"prompt":"\"కస్టమర్ కేర్\" నుంచి అంటూ ఒకతను ఫోన్ చేసి, ఫెయిల్ అయిన పేమెంట్ సరిచేయడానికి స్క్రీన్-షేరింగ్ యాప్ ఇన్‌స్టాల్ చేయమని పూజను అడుగుతున్నాడు. ఆమె ఏం చేయాలి?","options":["ఒప్పుకోకూడదు; అలాంటి యాప్‌లతో తెలియనివాళ్లు ఆమె ఫోన్‌ను కంట్రోల్ చేయగలరు","సమస్య త్వరగా సరిచేయడానికి ఇన్‌స్టాల్ చేయాలి","ఇన్‌స్టాల్ చేసి, ఐదు నిమిషాల తర్వాత క్లోజ్ చేయాలి","కాలర్‌కు ఆమె పేరు తెలిస్తే ఇన్‌స్టాల్ చేయాలి"],"answer":"A","explanation":"స్క్రీన్-షేరింగ్ యాప్‌లతో కాలర్ మీ OTPలు, PIN చూడగలడు, మీ ఫోన్‌ను కంట్రోల్ కూడా చేయగలడు. నిజమైన సపోర్ట్ టీమ్‌కు ఇది ఎప్పుడూ అవసరం లేదు."}}'::jsonb, null,null,'live','ai'),
  ('safety-upi-fraud-006','safety', array['upi-fraud'], 'silver','mcq', '{"en":{"prompt":"Ravi''s UPI payment failed. He searches online, finds a \"helpline\" number, and the person asks for his UPI PIN to refund him. What is the right move?","options":["Share the PIN, since he called them himself","Use the help section in the UPI app or bank''s site","Give the PIN but keep the OTP secret","Wait a day and then share the PIN"],"answer":"B","explanation":"Fake helpline numbers are often posted online to catch people. A refund never needs your PIN, so use the help options inside the official app."},"hi":{"prompt":"रवि का UPI पेमेंट फ़ेल हो गया। वह ऑनलाइन सर्च करके एक \"हेल्पलाइन\" नंबर ढूँढता है, और वहाँ का व्यक्ति रिफ़ंड देने के लिए उसका UPI PIN माँगता है। सही कदम क्या है?","options":["PIN बता दे, क्योंकि कॉल उसने खुद किया है","UPI ऐप या बैंक की साइट के हेल्प सेक्शन का इस्तेमाल करे","PIN बता दे लेकिन OTP छिपाकर रखे","एक दिन रुके और फिर PIN बता दे"],"answer":"B","explanation":"लोगों को फँसाने के लिए नकली हेल्पलाइन नंबर अक्सर ऑनलाइन डाले जाते हैं। रिफ़ंड के लिए कभी PIN की ज़रूरत नहीं होती, इसलिए आधिकारिक ऐप के अंदर के हेल्प ऑप्शन इस्तेमाल करें।"},"te":{"prompt":"రవి UPI పేమెంట్ ఫెయిల్ అయింది. అతను ఆన్‌లైన్‌లో వెతికి ఒక \"హెల్ప్‌లైన్\" నంబర్ కనుక్కున్నాడు. అక్కడి వ్యక్తి రీఫండ్ ఇవ్వడానికి అతని UPI PIN అడుగుతున్నాడు. సరైన పని ఏది?","options":["తనే కాల్ చేశాడు కాబట్టి PIN చెప్పేయాలి","UPI యాప్ లేదా బ్యాంక్ సైట్‌లోని హెల్ప్ సెక్షన్ వాడాలి","PIN చెప్పాలి కానీ OTP రహస్యంగా ఉంచాలి","ఒక రోజు ఆగి తర్వాత PIN చెప్పాలి"],"answer":"B","explanation":"జనాన్ని మోసం చేయడానికి నకిలీ హెల్ప్‌లైన్ నంబర్లను తరచూ ఆన్‌లైన్‌లో పెడతారు. రీఫండ్‌కు ఎప్పుడూ PIN అవసరం లేదు, కాబట్టి అధికారిక యాప్‌లోని హెల్ప్ ఆప్షన్లు వాడండి."}}'::jsonb, null,null,'live','ai'),
  ('safety-phishing-005','safety', array['phishing'], 'silver','mcq', '{"en":{"prompt":"A message offers Ayesha a ₹30,000-a-month data entry job. She must first pay a ₹1,500 registration fee. What is the best response?","options":["Pay, since the salary is much bigger than the fee","Pay half now and the rest after joining","Pay only after getting a receipt from them","Do not pay; real employers do not charge to hire"],"answer":"D","explanation":"Real jobs pay you; they do not ask you to pay to get hired. An upfront fee for a job is a common scam."},"hi":{"prompt":"आयशा को एक मैसेज में ₹30,000 महीने की डेटा एंट्री जॉब का ऑफ़र मिलता है। पहले उसे ₹1,500 रजिस्ट्रेशन फीस भरनी होगी। सबसे अच्छा जवाब क्या है?","options":["भर दे, क्योंकि सैलरी फीस से बहुत ज़्यादा है","आधा अभी भरे और बाकी जॉइन करने के बाद","उनसे रसीद मिलने के बाद ही भरे","न भरे; असली कंपनियाँ नौकरी देने के लिए पैसे नहीं लेतीं"],"answer":"D","explanation":"असली नौकरी में आपको पैसे मिलते हैं; नौकरी पाने के लिए आपसे पैसे नहीं माँगे जाते। नौकरी के लिए पहले से फीस माँगना एक आम ठगी है।"},"te":{"prompt":"ఆయేషాకు నెలకు ₹30,000 జీతంతో డేటా ఎంట్రీ జాబ్ ఉందని ఒక మెసేజ్ వచ్చింది. ముందుగా ఆమె ₹1,500 రిజిస్ట్రేషన్ ఫీజు కట్టాలట. ఏం చేయడం ఉత్తమం?","options":["జీతం ఫీజు కంటే చాలా ఎక్కువ కాబట్టి కట్టేయాలి","ఇప్పుడు సగం, జాయిన్ అయ్యాక మిగతా సగం కట్టాలి","వాళ్ల నుంచి రసీదు వచ్చాకే కట్టాలి","కట్టకూడదు; నిజమైన కంపెనీలు ఉద్యోగం ఇవ్వడానికి డబ్బు అడగవు"],"answer":"D","explanation":"నిజమైన ఉద్యోగాల్లో మీకు జీతం ఇస్తారు; ఉద్యోగం కోసం మిమ్మల్ని డబ్బు కట్టమని అడగరు. ఉద్యోగం కోసం ముందే ఫీజు అడగడం చాలా సాధారణమైన మోసం."}}'::jsonb, null,'safety-money-mule','live','ai'),
  ('safety-insurance-basics-003','safety', array['insurance-basics'], 'silver','mcq', '{"en":{"prompt":"Suresh is the only earning member of his family. What problem does life insurance help with?","options":["It pays his family if he dies, replacing lost income","It makes his salary grow faster","It pays for the family''s daily groceries","It returns double the premium every year"],"answer":"A","explanation":"Life insurance pays a sum to the family if the insured person dies. This helps them manage without his income."},"hi":{"prompt":"सुरेश अपने परिवार में अकेला कमाने वाला है। लाइफ़ इंश्योरेंस किस समस्या में मदद करता है?","options":["उसकी मौत होने पर परिवार को पैसा मिलता है, जिससे उसकी कमाई की कमी पूरी होती है","इससे उसकी सैलरी तेज़ी से बढ़ती है","यह परिवार के रोज़ के राशन का खर्च देता है","यह हर साल प्रीमियम का दोगुना लौटाता है"],"answer":"A","explanation":"बीमा वाले व्यक्ति की मौत होने पर लाइफ़ इंश्योरेंस परिवार को एक रकम देता है। इससे परिवार उसकी आमदनी के बिना भी गुज़ारा कर पाता है।"},"te":{"prompt":"సురేష్ తన కుటుంబంలో సంపాదించే ఏకైక వ్యక్తి. లైఫ్ ఇన్సూరెన్స్ ఏ సమస్యలో సాయపడుతుంది?","options":["అతను చనిపోతే కుటుంబానికి డబ్బు అందుతుంది, పోయిన ఆదాయాన్ని భర్తీ చేస్తుంది","అతని జీతం వేగంగా పెరిగేలా చేస్తుంది","కుటుంబం రోజువారీ సరుకుల ఖర్చు చెల్లిస్తుంది","ప్రతి ఏడాది ప్రీమియంకు రెట్టింపు తిరిగి ఇస్తుంది"],"answer":"A","explanation":"ఇన్సూరెన్స్ ఉన్న వ్యక్తి చనిపోతే లైఫ్ ఇన్సూరెన్స్ కుటుంబానికి ఒక మొత్తం చెల్లిస్తుంది. దీంతో అతని ఆదాయం లేకపోయినా కుటుంబం నెట్టుకురాగలుగుతుంది."}}'::jsonb, null,null,'live','ai'),
  ('safety-insurance-basics-004','safety', array['insurance-basics'], 'silver','mcq', '{"en":{"prompt":"Meena''s family has health insurance. Her father needs surgery costing ₹80,000. How does the insurance help?","options":["It gives a loan they must repay with interest","It pays covered costs as per the policy terms","It pays back all the premiums they ever paid","It helps only if they claim a year later"],"answer":"B","explanation":"Health insurance pays for covered hospital costs up to the limits in the policy. That is why reading what is covered matters."},"hi":{"prompt":"मीना के परिवार के पास हेल्थ इंश्योरेंस है। उसके पिता की सर्जरी होनी है, जिसका खर्च ₹80,000 है। इंश्योरेंस कैसे मदद करता है?","options":["यह लोन देता है जो ब्याज के साथ चुकाना पड़ता है","पॉलिसी की शर्तों के अनुसार कवर किए गए खर्च देता है","अब तक भरे सारे प्रीमियम वापस कर देता है","यह तभी मदद करता है जब वे एक साल बाद क्लेम करें"],"answer":"B","explanation":"हेल्थ इंश्योरेंस पॉलिसी में लिखी सीमा तक, कवर किए गए अस्पताल के खर्च देता है। इसलिए यह पढ़ना ज़रूरी है कि क्या-क्या कवर है।"},"te":{"prompt":"మీనా కుటుంబానికి హెల్త్ ఇన్సూరెన్స్ ఉంది. ఆమె నాన్నకు ₹80,000 ఖర్చయ్యే సర్జరీ అవసరం. ఇన్సూరెన్స్ ఎలా సాయపడుతుంది?","options":["వడ్డీతో తిరిగి కట్టాల్సిన లోన్ ఇస్తుంది","పాలసీ నిబంధనల ప్రకారం కవర్ అయిన ఖర్చులు చెల్లిస్తుంది","ఇప్పటిదాకా కట్టిన ప్రీమియంలన్నీ తిరిగి ఇస్తుంది","ఒక ఏడాది తర్వాత క్లెయిమ్ చేస్తేనే సాయపడుతుంది"],"answer":"B","explanation":"పాలసీలో ఉన్న పరిమితి వరకు, కవర్ అయిన హాస్పిటల్ ఖర్చులను హెల్త్ ఇన్సూరెన్స్ చెల్లిస్తుంది. అందుకే ఏమేం కవర్ అవుతాయో చదవడం ముఖ్యం."}}'::jsonb, null,null,'live','ai'),
  ('safety-fake-loan-apps-003','safety', array['fake-loan-apps'], 'silver','mcq', '{"en":{"prompt":"A loan app threatens to send Karthik''s photos to his contacts unless he pays extra \"fees\". What should he do?","options":["Pay quickly so the threats stop","Delete the app and tell no one","Borrow from another app to pay them","Save proof and report at cybercrime.gov.in or 1930"],"answer":"D","explanation":"Paying usually leads to more demands. Keeping proof and reporting to the cybercrime helpline lets officials act against the harassers."},"hi":{"prompt":"एक लोन ऐप धमकी देता है कि अगर कार्तिक ने एक्स्ट्रा \"फीस\" नहीं दी, तो वह उसकी फ़ोटो उसके कॉन्टैक्ट्स को भेज देगा। उसे क्या करना चाहिए?","options":["धमकियाँ रुकवाने के लिए जल्दी पैसे दे दे","ऐप डिलीट कर दे और किसी को न बताए","उन्हें पैसे देने के लिए दूसरे ऐप से उधार ले","सबूत सेव करे और cybercrime.gov.in या 1930 पर शिकायत करे"],"answer":"D","explanation":"पैसे देने पर आमतौर पर और माँगें आती हैं। सबूत रखने और साइबर क्राइम हेल्पलाइन पर शिकायत करने से अधिकारी परेशान करने वालों पर कार्रवाई कर पाते हैं।"},"te":{"prompt":"కార్తీక్ ఎక్స్‌ట్రా \"ఫీజులు\" కట్టకపోతే అతని ఫోటోలను అతని కాంటాక్ట్‌లకు పంపిస్తామని ఒక లోన్ యాప్ బెదిరిస్తోంది. అతను ఏం చేయాలి?","options":["బెదిరింపులు ఆగాలంటే వెంటనే డబ్బు కట్టేయాలి","యాప్ డిలీట్ చేసి, ఎవరికీ చెప్పకూడదు","వాళ్లకు కట్టడానికి ఇంకో యాప్ నుంచి అప్పు తీసుకోవాలి","ఆధారాలు సేవ్ చేసి, cybercrime.gov.in లేదా 1930లో ఫిర్యాదు చేయాలి"],"answer":"D","explanation":"డబ్బు కడితే సాధారణంగా ఇంకా ఎక్కువ డిమాండ్లు వస్తాయి. ఆధారాలు ఉంచుకుని సైబర్ క్రైమ్ హెల్ప్‌లైన్‌కు ఫిర్యాదు చేస్తే, వేధించేవాళ్లపై అధికారులు చర్య తీసుకోగలరు."}}'::jsonb, null,null,'live','ai'),
  ('safety-otp-and-pin-006','safety', array['otp-and-pin'], 'silver','mcq', '{"en":{"prompt":"Nikhil''s friend borrows his phone and asks for the OTP that just arrived \"to log in to a game\". The SMS says it is for a bank payment. What should Nikhil do?","options":["Share it, since it is only a game login","Share it but change his PIN later","Share it if the friend promises to repay","Read the SMS: it is for a payment, so refuse"],"answer":"D","explanation":"An OTP message tells you what it approves, and this one approves a payment. Sharing it would let money leave his account."},"hi":{"prompt":"निखिल का दोस्त उसका फोन लेता है और \"गेम में लॉगिन करने के लिए\" अभी आया OTP माँगता है। SMS में लिखा है कि यह बैंक पेमेंट के लिए है। निखिल को क्या करना चाहिए?","options":["बता दे, क्योंकि यह सिर्फ गेम लॉगिन है","बता दे लेकिन बाद में अपना PIN बदल ले","अगर दोस्त पैसे लौटाने का वादा करे तो बता दे","SMS पढ़े: यह पेमेंट के लिए है, इसलिए मना कर दे"],"answer":"D","explanation":"OTP मैसेज बताता है कि वह किस काम को मंज़ूरी देता है, और यह वाला पेमेंट को मंज़ूरी देता है। इसे बताने से उसके अकाउंट से पैसा निकल सकता है।"},"te":{"prompt":"నిఖిల్ ఫ్రెండ్ అతని ఫోన్ తీసుకుని, \"గేమ్‌లో లాగిన్ అవ్వడానికి\" ఇప్పుడే వచ్చిన OTP అడుగుతున్నాడు. ఆ SMS అది బ్యాంక్ పేమెంట్ కోసమని చెబుతోంది. నిఖిల్ ఏం చేయాలి?","options":["ఇది గేమ్ లాగిన్ మాత్రమే కాబట్టి చెప్పేయాలి","చెప్పేసి, తర్వాత తన PIN మార్చుకోవాలి","ఫ్రెండ్ డబ్బు తిరిగిస్తానని మాట ఇస్తే చెప్పాలి","SMS చదవాలి: ఇది పేమెంట్ కోసం, కాబట్టి ఒప్పుకోకూడదు"],"answer":"D","explanation":"OTP మెసేజ్ అది దేనికి ఆమోదమో చెబుతుంది, ఇది పేమెంట్‌కు ఆమోదం. దాన్ని చెబితే అతని అకౌంట్ నుంచి డబ్బు బయటకు వెళ్లిపోతుంది."}}'::jsonb, null,null,'live','ai'),
  ('safety-upi-fraud-007','safety', array['upi-fraud'], 'silver','mcq', '{"en":{"prompt":"A stranger calls Lata: \"I sent ₹2,000 to your UPI by mistake. Please return it.\" She has not checked her account yet. What should she do?","options":["Check her own balance; if no credit, send nothing","Send ₹2,000 back right away","Approve the collect request he sends","Send half now and half after checking"],"answer":"A","explanation":"Scammers fake \"wrong transfer\" stories with fake SMS or collect requests. Only your own bank app or statement shows whether money really came in."},"hi":{"prompt":"एक अनजान व्यक्ति लता को कॉल करता है: \"मैंने गलती से आपके UPI पर ₹2,000 भेज दिए। प्लीज़ लौटा दीजिए।\" उसने अभी तक अपना अकाउंट चेक नहीं किया है। उसे क्या करना चाहिए?","options":["अपना बैलेंस खुद चेक करे; पैसा नहीं आया तो कुछ न भेजे","तुरंत ₹2,000 वापस भेज दे","वह जो कलेक्ट रिक्वेस्ट भेजे, उसे मंज़ूर कर दे","आधा अभी भेजे और आधा चेक करने के बाद"],"answer":"A","explanation":"ठग नकली SMS या कलेक्ट रिक्वेस्ट से \"गलत ट्रांसफ़र\" की झूठी कहानियाँ बनाते हैं। सिर्फ आपका अपना बैंक ऐप या स्टेटमेंट ही बताता है कि सच में पैसा आया है या नहीं।"},"te":{"prompt":"ఒక తెలియని వ్యక్తి లతకు ఫోన్ చేసి, \"పొరపాటున మీ UPIకి ₹2,000 పంపాను. దయచేసి తిరిగి పంపండి\" అంటున్నాడు. ఆమె ఇంకా తన అకౌంట్ చెక్ చేయలేదు. ఆమె ఏం చేయాలి?","options":["తన బ్యాలెన్స్ తనే చెక్ చేసుకోవాలి; డబ్బు రాకపోతే ఏమీ పంపకూడదు","వెంటనే ₹2,000 తిరిగి పంపాలి","అతను పంపే కలెక్ట్ రిక్వెస్ట్‌ను ఆమోదించాలి","ఇప్పుడు సగం, చెక్ చేశాక మిగతా సగం పంపాలి"],"answer":"A","explanation":"మోసగాళ్లు నకిలీ SMSలు లేదా కలెక్ట్ రిక్వెస్ట్‌లతో \"పొరపాటున ట్రాన్స్‌ఫర్ అయింది\" అనే కథలు అల్లుతారు. నిజంగా డబ్బు వచ్చిందో లేదో మీ సొంత బ్యాంక్ యాప్ లేదా స్టేట్‌మెంట్ మాత్రమే చెబుతుంది."}}'::jsonb, null,'safety-money-mule','live','ai'),
  ('safety-ponzi-and-chit-scams-006','safety', array['ponzi-and-chit-scams'], 'gold','mcq', '{"en":{"prompt":"A scheme promises a \"guaranteed\" 10% return every month. Without compounding, what yearly return is that?","options":["10%","12%","120%","1.2%"],"answer":"C","explanation":"10% a month × 12 months = 120% a year, many times what a bank FD pays (around 6–7% a year; rates vary). A guaranteed return that high is a strong scam sign."},"hi":{"prompt":"एक स्कीम हर महीने 10% \"गारंटीड\" रिटर्न का वादा करती है। कंपाउंडिंग के बिना, यह साल का कितना रिटर्न हुआ?","options":["10%","12%","120%","1.2%"],"answer":"C","explanation":"10% हर महीने × 12 महीने = साल का 120%, जो बैंक FD के रिटर्न से कई गुना है (लगभग 6–7% सालाना; दरें बदलती रहती हैं)। इतने ऊँचे रिटर्न की गारंटी ठगी का मज़बूत संकेत है।"},"te":{"prompt":"ఒక స్కీమ్ ప్రతి నెలా 10% \"గ్యారెంటీ\" రిటర్న్ ఇస్తామని చెబుతోంది. కాంపౌండింగ్ లేకుండా, ఇది ఏడాదికి ఎంత రిటర్న్ అవుతుంది?","options":["10%","12%","120%","1.2%"],"answer":"C","explanation":"నెలకు 10% × 12 నెలలు = ఏడాదికి 120%, ఇది బ్యాంక్ FD ఇచ్చే దానికంటే చాలా రెట్లు ఎక్కువ (ఏడాదికి సుమారు 6–7%; రేట్లు మారుతుంటాయి). ఇంత ఎక్కువ రిటర్న్‌కు గ్యారెంటీ ఇవ్వడం మోసానికి బలమైన సంకేతం."}}'::jsonb, null,null,'live','ai'),
  ('safety-fake-loan-apps-004','safety', array['fake-loan-apps'], 'gold','mcq', '{"en":{"prompt":"A loan app approves ₹5,000 for Rohan but cuts a ₹1,000 \"processing fee\", so he gets ₹4,000. He must repay ₹5,500 in 30 days. How much more does he repay than he received?","options":["₹500","₹1,000","₹5,500","₹1,500"],"answer":"D","explanation":"He repays ₹5,500 but only got ₹4,000, so he pays ₹1,500 extra. That is 37.5% of what he received in just one month."},"hi":{"prompt":"एक लोन ऐप रोहन के लिए ₹5,000 मंज़ूर करता है, लेकिन ₹1,000 \"प्रोसेसिंग फीस\" काट लेता है, तो उसे ₹4,000 मिलते हैं। उसे 30 दिनों में ₹5,500 चुकाने हैं। उसे जितना मिला, उससे कितना ज़्यादा उसे चुकाना होगा?","options":["₹500","₹1,000","₹5,500","₹1,500"],"answer":"D","explanation":"वह ₹5,500 चुकाता है लेकिन उसे मिले सिर्फ ₹4,000, यानी वह ₹1,500 ज़्यादा भरता है। यह सिर्फ एक महीने में, उसे मिली रकम का 37.5% है।"},"te":{"prompt":"ఒక లోన్ యాప్ రోహన్‌కు ₹5,000 ఆమోదించింది, కానీ ₹1,000 \"ప్రాసెసింగ్ ఫీజు\" కట్ చేసింది, కాబట్టి అతనికి ₹4,000 వచ్చాయి. అతను 30 రోజుల్లో ₹5,500 తిరిగి కట్టాలి. అతనికి వచ్చిన దానికంటే ఎంత ఎక్కువ తిరిగి కడుతున్నాడు?","options":["₹500","₹1,000","₹5,500","₹1,500"],"answer":"D","explanation":"అతను ₹5,500 కడుతున్నాడు కానీ అతనికి వచ్చింది ₹4,000 మాత్రమే, అంటే ₹1,500 ఎక్కువ కడుతున్నాడు. ఇది కేవలం ఒక్క నెలలో, అతనికి వచ్చిన మొత్తంలో 37.5%."}}'::jsonb, null,null,'live','ai'),
  ('safety-fake-loan-apps-005','safety', array['fake-loan-apps'], 'gold','mcq', '{"en":{"prompt":"A loan app charges 2% interest per week on a ₹3,000 loan (no compounding). How much interest is due after 8 weeks?","options":["₹60","₹480","₹240","₹600"],"answer":"B","explanation":"2% of ₹3,000 is ₹60 a week, and ₹60 × 8 weeks = ₹480. Weekly rates look small but add up fast."},"hi":{"prompt":"एक लोन ऐप ₹3,000 के लोन पर हर हफ़्ते 2% ब्याज लेता है (कंपाउंडिंग नहीं)। 8 हफ़्तों बाद कितना ब्याज बनेगा?","options":["₹60","₹480","₹240","₹600"],"answer":"B","explanation":"₹3,000 का 2% यानी हर हफ़्ते ₹60, और ₹60 × 8 हफ़्ते = ₹480। हफ़्ते की दरें छोटी लगती हैं, लेकिन जल्दी बढ़ जाती हैं।"},"te":{"prompt":"ఒక లోన్ యాప్ ₹3,000 లోన్‌పై వారానికి 2% వడ్డీ వసూలు చేస్తుంది (కాంపౌండింగ్ లేదు). 8 వారాల తర్వాత ఎంత వడ్డీ కట్టాలి?","options":["₹60","₹480","₹240","₹600"],"answer":"B","explanation":"₹3,000లో 2% అంటే వారానికి ₹60, ₹60 × 8 వారాలు = ₹480. వారపు రేట్లు చిన్నగా కనిపిస్తాయి కానీ త్వరగా పెరిగిపోతాయి."}}'::jsonb, null,null,'live','ai'),
  ('safety-ponzi-and-chit-scams-007','safety', array['ponzi-and-chit-scams'], 'gold','mcq', '{"en":{"prompt":"A scheme must pay old members ₹45,000 every month and earns no real profit. New members join with ₹1,500 each. How many new members must join each month just to cover payouts?","options":["30","3","15","45"],"answer":"A","explanation":"₹45,000 ÷ ₹1,500 = 30 new members every month. When new members stop joining, the payouts stop and the scheme collapses."},"hi":{"prompt":"एक स्कीम को पुराने सदस्यों को हर महीने ₹45,000 देने हैं और उसकी कोई असली कमाई नहीं है। हर नया सदस्य ₹1,500 देकर जुड़ता है। सिर्फ भुगतान पूरा करने के लिए हर महीने कितने नए सदस्य जुड़ने चाहिए?","options":["30","3","15","45"],"answer":"A","explanation":"₹45,000 ÷ ₹1,500 = हर महीने 30 नए सदस्य। जब नए सदस्य जुड़ना बंद कर देते हैं, तो भुगतान रुक जाता है और स्कीम ढह जाती है।"},"te":{"prompt":"ఒక స్కీమ్ పాత సభ్యులకు ప్రతి నెలా ₹45,000 చెల్లించాలి, దానికి అసలు లాభం ఏమీ రాదు. కొత్త సభ్యులు ఒక్కొక్కరు ₹1,500తో చేరతారు. కేవలం చెల్లింపులు కవర్ చేయడానికే ప్రతి నెలా ఎంతమంది కొత్త సభ్యులు చేరాలి?","options":["30","3","15","45"],"answer":"A","explanation":"₹45,000 ÷ ₹1,500 = ప్రతి నెలా 30 మంది కొత్త సభ్యులు. కొత్త సభ్యులు చేరడం ఆగిపోగానే చెల్లింపులు ఆగిపోతాయి, స్కీమ్ కుప్పకూలుతుంది."}}'::jsonb, null,null,'live','ai'),
  ('safety-insurance-basics-005','safety', array['insurance-basics'], 'gold','mcq', '{"en":{"prompt":"Priya''s health policy pays 80% of covered hospital costs. She has a covered bill of ₹50,000. How much of the bill does Priya pay herself?","options":["₹40,000","₹10,000","₹6,000","₹16,000"],"answer":"B","explanation":"The insurer pays 80% of ₹50,000, which is ₹40,000. Priya pays the remaining 20%, which is ₹10,000."},"hi":{"prompt":"प्रिया की हेल्थ पॉलिसी कवर किए गए अस्पताल खर्च का 80% देती है। उसका कवर किया गया बिल ₹50,000 है। बिल का कितना हिस्सा प्रिया खुद भरेगी?","options":["₹40,000","₹10,000","₹6,000","₹16,000"],"answer":"B","explanation":"बीमा कंपनी ₹50,000 का 80%, यानी ₹40,000 देती है। बाकी 20%, यानी ₹10,000, प्रिया खुद भरती है।"},"te":{"prompt":"ప్రియ హెల్త్ పాలసీ కవర్ అయిన హాస్పిటల్ ఖర్చుల్లో 80% చెల్లిస్తుంది. ఆమెకు కవర్ అయిన ₹50,000 బిల్ వచ్చింది. బిల్‌లో ఎంత మొత్తం ప్రియ తనే కట్టాలి?","options":["₹40,000","₹10,000","₹6,000","₹16,000"],"answer":"B","explanation":"ఇన్సూరెన్స్ కంపెనీ ₹50,000లో 80%, అంటే ₹40,000 చెల్లిస్తుంది. మిగతా 20%, అంటే ₹10,000, ప్రియ తనే కడుతుంది."}}'::jsonb, null,null,'live','ai'),
  ('safety-ponzi-and-chit-scams-008','safety', array['ponzi-and-chit-scams'], 'platinum','mcq', '{"en":{"prompt":"Farhan compares two chit groups. Group X is registered, has written rules and gives modest returns. Group Y is unregistered and promises double returns. What is the key trade-off?","options":["Y promises more but gives no legal protection if it vanishes","X is riskier because its returns are lower","Both are equally safe if friends have joined","Y is safer because there is no paperwork to go wrong"],"answer":"A","explanation":"A registered chit fund must follow rules and can be held to account. Y''s bigger promise comes with no protection if the organiser disappears."},"hi":{"prompt":"फ़रहान दो चिट ग्रुप की तुलना करता है। ग्रुप X रजिस्टर्ड है, उसके नियम लिखित हैं और वह मामूली रिटर्न देता है। ग्रुप Y रजिस्टर्ड नहीं है और दोगुने रिटर्न का वादा करता है। मुख्य ट्रेड-ऑफ़ क्या है?","options":["Y ज़्यादा का वादा करता है, लेकिन गायब होने पर कोई कानूनी सुरक्षा नहीं देता","X ज़्यादा जोखिम वाला है क्योंकि उसका रिटर्न कम है","अगर दोस्त जुड़े हैं तो दोनों बराबर सुरक्षित हैं","Y ज़्यादा सुरक्षित है क्योंकि उसमें गड़बड़ होने लायक कोई कागज़ी काम नहीं है"],"answer":"A","explanation":"रजिस्टर्ड चिट फ़ंड को नियम मानने पड़ते हैं और उससे जवाब माँगा जा सकता है। Y के बड़े वादे के साथ, आयोजक के गायब होने पर कोई सुरक्षा नहीं है।"},"te":{"prompt":"ఫర్హాన్ రెండు చిట్ గ్రూపులను పోల్చి చూస్తున్నాడు. గ్రూప్ X రిజిస్టర్ అయింది, రాతపూర్వక నియమాలు ఉన్నాయి, మామూలు రిటర్న్స్ ఇస్తుంది. గ్రూప్ Y రిజిస్టర్ కాలేదు, రెట్టింపు రిటర్న్స్ ఇస్తామంటోంది. ముఖ్యమైన ట్రేడ్-ఆఫ్ ఏమిటి?","options":["Y ఎక్కువ హామీ ఇస్తుంది, కానీ అది మాయమైతే ఎలాంటి చట్టపరమైన రక్షణ ఉండదు","X రిటర్న్స్ తక్కువ కాబట్టి దానికే ఎక్కువ రిస్క్","ఫ్రెండ్స్ చేరి ఉంటే రెండూ సమానంగా సురక్షితం","పేపర్ వర్క్ లేదు కాబట్టి Yలో పొరపాట్లు జరగవు, అదే సురక్షితం"],"answer":"A","explanation":"రిజిస్టర్డ్ చిట్ ఫండ్ నియమాలు పాటించాలి, దాన్ని జవాబుదారీ చేయొచ్చు. Y ఇచ్చే పెద్ద హామీతో పాటు, నిర్వాహకుడు మాయమైతే ఎలాంటి రక్షణా ఉండదు."}}'::jsonb, null,null,'live','ai'),
  ('safety-insurance-basics-006','safety', array['insurance-basics'], 'platinum','mcq', '{"en":{"prompt":"Ananya compares two health policies. Policy 1 costs ₹4,000 a year and covers up to ₹2 lakh. Policy 2 costs ₹2,500 a year and covers up to ₹50,000. What is the main trade-off?","options":["Policy 1 is a waste because its premium is higher","Policy 2 covers more because it is cheaper","Policy 2 saves ₹1,500 yearly but covers big bills less","Both give the same cover; only the price differs"],"answer":"C","explanation":"The cheaper policy saves ₹1,500 a year, but any bill above ₹50,000 would be paid from the family''s pocket. A lower premium usually means less cover."},"hi":{"prompt":"अनन्या दो हेल्थ पॉलिसी की तुलना करती है। पॉलिसी 1 की कीमत ₹4,000 सालाना है और यह ₹2 लाख तक कवर करती है। पॉलिसी 2 की कीमत ₹2,500 सालाना है और यह ₹50,000 तक कवर करती है। मुख्य ट्रेड-ऑफ़ क्या है?","options":["पॉलिसी 1 बेकार है क्योंकि उसका प्रीमियम ज़्यादा है","पॉलिसी 2 सस्ती है, इसलिए ज़्यादा कवर करती है","पॉलिसी 2 से हर साल ₹1,500 बचते हैं, लेकिन बड़े बिल कम कवर होते हैं","दोनों का कवर एक जैसा है; सिर्फ कीमत अलग है"],"answer":"C","explanation":"सस्ती पॉलिसी से साल में ₹1,500 बचते हैं, लेकिन ₹50,000 से ऊपर का कोई भी बिल परिवार को अपनी जेब से भरना होगा। कम प्रीमियम का मतलब आमतौर पर कम कवर होता है।"},"te":{"prompt":"అనన్య రెండు హెల్త్ పాలసీలను పోల్చి చూస్తోంది. పాలసీ 1 ఏడాదికి ₹4,000, ₹2 లక్షల వరకు కవర్ చేస్తుంది. పాలసీ 2 ఏడాదికి ₹2,500, ₹50,000 వరకు కవర్ చేస్తుంది. ముఖ్యమైన ట్రేడ్-ఆఫ్ ఏమిటి?","options":["పాలసీ 1 ప్రీమియం ఎక్కువ కాబట్టి అది వృథా","పాలసీ 2 చౌక కాబట్టి ఎక్కువ కవర్ చేస్తుంది","పాలసీ 2తో ఏడాదికి ₹1,500 ఆదా అవుతుంది, కానీ పెద్ద బిల్లులకు కవర్ తక్కువ","రెండింటి కవర్ ఒకటే; ధర మాత్రమే వేరు"],"answer":"C","explanation":"చౌక పాలసీతో ఏడాదికి ₹1,500 ఆదా అవుతుంది, కానీ ₹50,000 దాటిన ఏ బిల్లైనా కుటుంబం సొంత జేబు నుంచి కట్టాలి. తక్కువ ప్రీమియం అంటే సాధారణంగా తక్కువ కవర్."}}'::jsonb, null,null,'live','ai'),
  ('safety-fake-loan-apps-006','safety', array['fake-loan-apps'], 'platinum','mcq', '{"en":{"prompt":"Vikram needs ₹10,000. A bank takes 3 days and checks documents. An unknown app pays in 2 minutes with no checks but wants his contacts. What does he risk for the app''s speed?","options":["Nothing, since both give the same amount","His privacy, hidden fees and possible harassment","Only a slightly lower credit score","Losing the bank''s cashback offer"],"answer":"B","explanation":"Unchecked instant apps often hide huge fees and misuse contacts to harass borrowers. The bank is slower, but its terms are clear and regulated."},"hi":{"prompt":"विक्रम को ₹10,000 चाहिए। बैंक 3 दिन लेता है और डॉक्यूमेंट जाँचता है। एक अनजान ऐप बिना किसी जाँच के 2 मिनट में पैसे दे देता है, लेकिन उसके कॉन्टैक्ट्स माँगता है। ऐप की तेज़ी के बदले वह क्या जोखिम उठा रहा है?","options":["कुछ नहीं, क्योंकि दोनों एक ही रकम देते हैं","अपनी प्राइवेसी, छिपी हुई फीस और परेशान किए जाने का खतरा","बस थोड़ा कम क्रेडिट स्कोर","बैंक का कैशबैक ऑफ़र छूट जाना"],"answer":"B","explanation":"बिना जाँच वाले इंस्टेंट ऐप अक्सर भारी फीस छिपाते हैं और उधार लेने वालों को परेशान करने के लिए कॉन्टैक्ट्स का गलत इस्तेमाल करते हैं। बैंक धीमा है, लेकिन उसकी शर्तें साफ़ और नियमों के तहत होती हैं।"},"te":{"prompt":"విక్రమ్‌కు ₹10,000 కావాలి. బ్యాంక్ 3 రోజులు తీసుకుంటుంది, డాక్యుమెంట్లు చెక్ చేస్తుంది. ఒక తెలియని యాప్ ఏ చెకింగ్ లేకుండా 2 నిమిషాల్లో డబ్బు ఇస్తుంది, కానీ అతని కాంటాక్ట్‌లు అడుగుతుంది. యాప్ వేగం కోసం అతను దేన్ని రిస్క్‌లో పెడుతున్నాడు?","options":["ఏమీ లేదు, రెండూ ఒకే మొత్తం ఇస్తాయి కాబట్టి","తన ప్రైవసీ, దాచిన ఫీజులు, వేధింపులకు గురయ్యే అవకాశం","కొంచెం తక్కువ క్రెడిట్ స్కోర్ మాత్రమే","బ్యాంక్ క్యాష్‌బ్యాక్ ఆఫర్ పోగొట్టుకోవడం"],"answer":"B","explanation":"చెకింగ్ లేని ఇన్‌స్టంట్ యాప్‌లు తరచూ భారీ ఫీజులు దాచిపెడతాయి, అప్పు తీసుకున్నవాళ్లను వేధించడానికి కాంటాక్ట్‌లను దుర్వినియోగం చేస్తాయి. బ్యాంక్ నెమ్మదిగా ఉన్నా, దాని నిబంధనలు స్పష్టంగా, నియంత్రణలో ఉంటాయి."}}'::jsonb, null,null,'live','ai'),
  ('safety-upi-fraud-008','safety', array['upi-fraud','otp-and-pin'], 'platinum','mcq', '{"en":{"prompt":"Shruti uses UPI every day. She plans to keep only small amounts in the account linked to UPI and the rest in another account. What is the trade-off?","options":["Having two accounts is always unsafe","She will no longer need a UPI PIN","She will earn double interest on her money","Less money is at risk, but moving money takes extra steps"],"answer":"D","explanation":"If her UPI is ever misused, only the small balance is exposed. The cost is the extra effort of moving money when she needs more."},"hi":{"prompt":"श्रुति रोज़ UPI इस्तेमाल करती है। वह सोचती है कि UPI से जुड़े अकाउंट में सिर्फ थोड़े पैसे रखे और बाकी दूसरे अकाउंट में। इसमें ट्रेड-ऑफ़ क्या है?","options":["दो अकाउंट रखना हमेशा असुरक्षित है","उसे अब UPI PIN की ज़रूरत नहीं पड़ेगी","उसे अपने पैसे पर दोगुना ब्याज मिलेगा","कम पैसा खतरे में रहता है, लेकिन पैसे ट्रांसफ़र करने में ज़्यादा कदम लगते हैं"],"answer":"D","explanation":"अगर कभी उसके UPI का गलत इस्तेमाल हो, तो सिर्फ थोड़ा बैलेंस ही खतरे में होगा। इसकी कीमत यह है कि ज़्यादा पैसे चाहिए हों तो उन्हें ट्रांसफ़र करने की मेहनत करनी पड़ती है।"},"te":{"prompt":"శ్రుతి రోజూ UPI వాడుతుంది. UPIకి లింక్ అయిన అకౌంట్‌లో కొంచెం డబ్బు మాత్రమే ఉంచి, మిగతాది వేరే అకౌంట్‌లో ఉంచాలనుకుంటోంది. ఇందులో ట్రేడ్-ఆఫ్ ఏమిటి?","options":["రెండు అకౌంట్లు ఉంచడం ఎప్పుడూ సురక్షితం కాదు","ఇక ఆమెకు UPI PIN అవసరం ఉండదు","ఆమె డబ్బుపై రెట్టింపు వడ్డీ వస్తుంది","తక్కువ డబ్బు రిస్క్‌లో ఉంటుంది, కానీ డబ్బు మార్చడానికి అదనపు స్టెప్స్ పడతాయి"],"answer":"D","explanation":"ఎప్పుడైనా ఆమె UPI దుర్వినియోగమైతే, ఆ చిన్న బ్యాలెన్స్ మాత్రమే రిస్క్‌లో ఉంటుంది. ఎక్కువ డబ్బు కావాల్సినప్పుడు దాన్ని మార్చుకునే అదనపు శ్రమే దీనికి మూల్యం."}}'::jsonb, null,null,'live','ai'),
  ('safety-phishing-006','safety', array['phishing'], 'platinum','mcq', '{"en":{"prompt":"A message from what looks like Gopal''s cousin''s number says: \"Emergency! Send ₹8,000 now, I''ll explain later.\" Calling back takes time. Which choice best balances speed and safety?","options":["Send it now, since family comes first","Call the cousin on a known number before sending","Send ₹4,000 now as a middle path","Ask the sender to share a photo as proof"],"answer":"B","explanation":"A quick call to a number you already know confirms the story in minutes. Scammers can copy names, photos and even hack accounts, so a message alone is not proof."},"hi":{"prompt":"गोपाल के कज़िन के नंबर जैसे दिखने वाले नंबर से मैसेज आता है: \"इमरजेंसी! अभी ₹8,000 भेजो, बाद में बताऊँगा।\" वापस कॉल करने में समय लगता है। कौन-सा विकल्प तेज़ी और सुरक्षा में सबसे अच्छा संतुलन रखता है?","options":["अभी भेज दे, क्योंकि परिवार सबसे पहले है","भेजने से पहले कज़िन को उसके जाने-पहचाने नंबर पर कॉल करे","बीच का रास्ता अपनाकर अभी ₹4,000 भेज दे","भेजने वाले से सबूत के तौर पर फ़ोटो माँगे"],"answer":"B","explanation":"पहले से पता नंबर पर एक छोटी-सी कॉल कुछ ही मिनटों में कहानी की पुष्टि कर देती है। ठग नाम, फ़ोटो कॉपी कर सकते हैं और अकाउंट तक हैक कर सकते हैं, इसलिए सिर्फ मैसेज सबूत नहीं है।"},"te":{"prompt":"గోపాల్ కజిన్ నంబర్‌లా కనిపించే నంబర్ నుంచి ఒక మెసేజ్ వచ్చింది: \"ఎమర్జెన్సీ! ఇప్పుడే ₹8,000 పంపు, తర్వాత చెబుతా.\" తిరిగి కాల్ చేయడానికి టైమ్ పడుతుంది. వేగం, భద్రత రెండింటినీ బాగా బ్యాలెన్స్ చేసే ఎంపిక ఏది?","options":["కుటుంబమే ముఖ్యం కాబట్టి ఇప్పుడే పంపాలి","పంపే ముందు కజిన్‌కు తెలిసిన నంబర్‌లో కాల్ చేయాలి","మధ్యేమార్గంగా ఇప్పుడు ₹4,000 పంపాలి","రుజువుగా ఫోటో పంపమని మెసేజ్ చేసినవాళ్లను అడగాలి"],"answer":"B","explanation":"మీకు ముందే తెలిసిన నంబర్‌కు ఒక్క కాల్ చేస్తే నిమిషాల్లో విషయం నిజమో కాదో తెలుస్తుంది. మోసగాళ్లు పేర్లు, ఫోటోలు కాపీ చేయగలరు, అకౌంట్లను హ్యాక్ కూడా చేయగలరు, కాబట్టి మెసేజ్ ఒక్కటే రుజువు కాదు."}}'::jsonb, null,'safety-money-mule','live','ai'),
  ('safety-upi-fraud-009','safety', array['upi-fraud'], 'diamond','mcq', '{"en":{"prompt":"Sanjay sees ₹15,000 debited by a UPI payment he never made. Which order of actions is best?","options":["Inform bank to block UPI, call 1930, then file online with screenshots","Post on social media, wait for the bank, then call 1930","Delete the messages, change phones, tell the bank next week","Call the receiver''s number and ask for a refund first"],"answer":"A","explanation":"Blocking first stops more money leaving, and a quick 1930 report can help freeze the stolen money. A complaint on cybercrime.gov.in with saved screenshots gives a proper record."},"hi":{"prompt":"संजय देखता है कि एक ऐसे UPI पेमेंट से ₹15,000 कट गए, जो उसने कभी किया ही नहीं। कामों का सबसे अच्छा क्रम कौन-सा है?","options":["बैंक को बताकर UPI ब्लॉक कराए, 1930 पर कॉल करे, फिर स्क्रीनशॉट के साथ ऑनलाइन शिकायत करे","सोशल मीडिया पर पोस्ट करे, बैंक का इंतज़ार करे, फिर 1930 पर कॉल करे","मैसेज डिलीट करे, फोन बदले, अगले हफ़्ते बैंक को बताए","पहले पैसा पाने वाले के नंबर पर कॉल करके रिफ़ंड माँगे"],"answer":"A","explanation":"पहले ब्लॉक करने से और पैसा निकलना रुकता है, और 1930 पर जल्दी शिकायत करने से चोरी का पैसा फ़्रीज़ हो सकता है। सेव किए स्क्रीनशॉट के साथ cybercrime.gov.in पर शिकायत करने से पक्का रिकॉर्ड बनता है।"},"te":{"prompt":"తాను ఎప్పుడూ చేయని ఒక UPI పేమెంట్ ద్వారా ₹15,000 డెబిట్ అయినట్టు సంజయ్ చూశాడు. ఏ వరుసలో పనులు చేయడం ఉత్తమం?","options":["UPI బ్లాక్ చేయమని బ్యాంక్‌కు చెప్పి, 1930కి కాల్ చేసి, తర్వాత స్క్రీన్‌షాట్‌లతో ఆన్‌లైన్‌లో ఫిర్యాదు చేయాలి","సోషల్ మీడియాలో పోస్ట్ చేసి, బ్యాంక్ కోసం ఎదురుచూసి, తర్వాత 1930కి కాల్ చేయాలి","మెసేజ్‌లు డిలీట్ చేసి, ఫోన్ మార్చి, వచ్చే వారం బ్యాంక్‌కు చెప్పాలి","ముందుగా డబ్బు అందుకున్నవాళ్ల నంబర్‌కు కాల్ చేసి రీఫండ్ అడగాలి"],"answer":"A","explanation":"ముందు బ్లాక్ చేస్తే ఇంకా డబ్బు బయటకు వెళ్లకుండా ఆగుతుంది, 1930కి త్వరగా ఫిర్యాదు చేస్తే దొంగిలించిన డబ్బు ఫ్రీజ్ అయ్యే అవకాశం ఉంటుంది. సేవ్ చేసిన స్క్రీన్‌షాట్‌లతో cybercrime.gov.inలో ఫిర్యాదు చేస్తే సరైన రికార్డు ఉంటుంది."}}'::jsonb, null,'safety-money-mule','live','ai'),
  ('safety-otp-and-pin-007','safety', array['otp-and-pin','upi-fraud'], 'diamond','mcq', '{"en":{"prompt":"Neha read out an OTP to a fake \"bank\" caller five minutes ago. No money has left yet. Which plan makes the most sense?","options":["Wait for a debit SMS, then decide whether to call the bank","Call bank to block account, report to 1930, change PIN","Call the caller back and ask him to cancel it","Change her phone number first, tell the bank next month"],"answer":"B","explanation":"Acting before any money moves gives the best chance to stop it. Blocking, reporting and changing her PIN close each door the scammer could use."},"hi":{"prompt":"नेहा ने पाँच मिनट पहले एक नकली \"बैंक\" कॉलर को OTP पढ़कर सुना दिया। अभी तक कोई पैसा नहीं निकला है। कौन-सा प्लान सबसे सही है?","options":["डेबिट का SMS आने का इंतज़ार करे, फिर तय करे कि बैंक को कॉल करना है या नहीं","बैंक को कॉल करके अकाउंट ब्लॉक कराए, 1930 पर शिकायत करे, PIN बदले","कॉलर को वापस कॉल करके उससे इसे कैंसल करने को कहे","पहले अपना फोन नंबर बदले, बैंक को अगले महीने बताए"],"answer":"B","explanation":"पैसा निकलने से पहले कदम उठाने से उसे रोकने की सबसे अच्छी संभावना रहती है। ब्लॉक करना, शिकायत करना और PIN बदलना ठग के हर रास्ते को बंद कर देता है।"},"te":{"prompt":"నేహా ఐదు నిమిషాల క్రితం ఒక నకిలీ \"బ్యాంక్\" కాలర్‌కు OTP చదివి చెప్పేసింది. ఇంకా డబ్బు ఏమీ పోలేదు. ఏ ప్లాన్ అత్యంత సరైనది?","options":["డెబిట్ SMS వచ్చే వరకు ఆగి, తర్వాత బ్యాంక్‌కు కాల్ చేయాలో వద్దో నిర్ణయించుకోవాలి","బ్యాంక్‌కు కాల్ చేసి అకౌంట్ బ్లాక్ చేయించాలి, 1930కి ఫిర్యాదు చేయాలి, PIN మార్చాలి","కాలర్‌కు తిరిగి కాల్ చేసి దాన్ని క్యాన్సిల్ చేయమని అడగాలి","ముందు ఫోన్ నంబర్ మార్చి, వచ్చే నెల బ్యాంక్‌కు చెప్పాలి"],"answer":"B","explanation":"డబ్బు పోకముందే చర్య తీసుకుంటే దాన్ని ఆపే అవకాశం ఎక్కువ. బ్లాక్ చేయడం, ఫిర్యాదు చేయడం, PIN మార్చడం వల్ల మోసగాడు వాడుకోగల ప్రతి దారీ మూసుకుపోతుంది."}}'::jsonb, null,null,'live','ai'),
  ('safety-fake-loan-apps-007','safety', array['fake-loan-apps'], 'diamond','mcq', '{"en":{"prompt":"Zoya borrowed ₹2,000 from a loan app. It now demands ₹9,000 and threatens to message her contacts. Which plan is best?","options":["Pay ₹9,000 now, then uninstall the app","Borrow from a second app to repay the first","Save threats, tell family, report to 1930, remove app permissions","Ignore it and only change her phone number"],"answer":"C","explanation":"Paying or borrowing more feeds the trap, while proof and an official report let police act. Telling family early also takes away the scammer''s power to shame her."},"hi":{"prompt":"ज़ोया ने एक लोन ऐप से ₹2,000 उधार लिए थे। अब ऐप ₹9,000 माँग रहा है और उसके कॉन्टैक्ट्स को मैसेज भेजने की धमकी दे रहा है। सबसे अच्छा प्लान कौन-सा है?","options":["अभी ₹9,000 दे दे, फिर ऐप अनइंस्टॉल कर दे","पहले ऐप को चुकाने के लिए दूसरे ऐप से उधार ले","धमकियाँ सेव करे, परिवार को बताए, 1930 पर शिकायत करे, ऐप की परमिशन हटाए","इसे अनदेखा करे और बस अपना फोन नंबर बदल ले"],"answer":"C","explanation":"पैसे देने या और उधार लेने से जाल और गहरा होता है, जबकि सबूत और आधिकारिक शिकायत से पुलिस कार्रवाई कर पाती है। परिवार को जल्दी बताने से ठग की उसे शर्मिंदा करने की ताकत भी खत्म हो जाती है।"},"te":{"prompt":"జోయా ఒక లోన్ యాప్ నుంచి ₹2,000 అప్పు తీసుకుంది. ఇప్పుడు అది ₹9,000 డిమాండ్ చేస్తూ, ఆమె కాంటాక్ట్‌లకు మెసేజ్‌లు పంపుతామని బెదిరిస్తోంది. ఏ ప్లాన్ ఉత్తమం?","options":["ఇప్పుడే ₹9,000 కట్టి, తర్వాత యాప్ అన్‌ఇన్‌స్టాల్ చేయాలి","మొదటి యాప్‌కు కట్టడానికి రెండో యాప్ నుంచి అప్పు తీసుకోవాలి","బెదిరింపులు సేవ్ చేసి, ఇంట్లో చెప్పి, 1930కి ఫిర్యాదు చేసి, యాప్ పర్మిషన్లు తీసేయాలి","పట్టించుకోకుండా ఫోన్ నంబర్ మాత్రమే మార్చుకోవాలి"],"answer":"C","explanation":"డబ్బు కట్టడం లేదా ఇంకా అప్పు చేయడం ఉచ్చును ఇంకా బిగిస్తుంది, ఆధారాలు, అధికారిక ఫిర్యాదు ఉంటే పోలీసులు చర్య తీసుకోగలరు. ఇంట్లో ముందే చెప్పేస్తే, ఆమెను అవమానిస్తామనే మోసగాడి బెదిరింపుకు బలం ఉండదు."}}'::jsonb, null,null,'live','ai'),
  ('safety-ponzi-and-chit-scams-009','safety', array['ponzi-and-chit-scams'], 'diamond','mcq', '{"en":{"prompt":"Raju put ₹20,000 into a scheme promising 5% a week. It paid him ₹1,000 a week for 6 weeks, then asked for ₹10,000 more to \"unlock\" his money. Which plan is wisest?","options":["Pay ₹10,000, since he has already earned ₹6,000","Stop paying, keep records, report it; he is still ₹14,000 down","Bring in friends so he can recover ₹14,000","Pay only ₹5,000 to reduce his risk"],"answer":"B","explanation":"He got back ₹6,000 of his ₹20,000, so he is ₹14,000 down, and paying more only adds to the loss. Keeping records and reporting is the only step that can help."},"hi":{"prompt":"राजू ने हर हफ़्ते 5% का वादा करने वाली एक स्कीम में ₹20,000 लगाए। स्कीम ने 6 हफ़्ते तक उसे हर हफ़्ते ₹1,000 दिए, फिर उसका पैसा \"अनलॉक\" करने के लिए ₹10,000 और माँगे। सबसे समझदारी वाला प्लान कौन-सा है?","options":["₹10,000 दे दे, क्योंकि वह पहले ही ₹6,000 कमा चुका है","पैसे देना बंद करे, रिकॉर्ड रखे, शिकायत करे; वह अभी भी ₹14,000 के नुकसान में है","दोस्तों को जोड़े ताकि ₹14,000 वापस मिल सकें","जोखिम कम करने के लिए सिर्फ ₹5,000 दे"],"answer":"B","explanation":"उसे अपने ₹20,000 में से ₹6,000 वापस मिले, यानी वह ₹14,000 के नुकसान में है, और ज़्यादा पैसे देने से नुकसान बस बढ़ेगा। रिकॉर्ड रखना और शिकायत करना ही ऐसा कदम है जो मदद कर सकता है।"},"te":{"prompt":"రాజు వారానికి 5% ఇస్తామన్న ఒక స్కీమ్‌లో ₹20,000 పెట్టాడు. అది 6 వారాల పాటు అతనికి వారానికి ₹1,000 ఇచ్చింది, తర్వాత అతని డబ్బు \"అన్‌లాక్\" చేయడానికి ఇంకా ₹10,000 అడిగింది. ఏ ప్లాన్ అత్యంత తెలివైనది?","options":["ఇప్పటికే ₹6,000 సంపాదించాడు కాబట్టి ₹10,000 కట్టాలి","కట్టడం ఆపేసి, రికార్డులు ఉంచి, ఫిర్యాదు చేయాలి; అతను ఇంకా ₹14,000 నష్టంలో ఉన్నాడు","₹14,000 తిరిగి రాబట్టడానికి ఫ్రెండ్స్‌ను చేర్పించాలి","రిస్క్ తగ్గించడానికి ₹5,000 మాత్రమే కట్టాలి"],"answer":"B","explanation":"అతని ₹20,000లో ₹6,000 మాత్రమే తిరిగి వచ్చాయి, అంటే అతను ₹14,000 నష్టంలో ఉన్నాడు, ఇంకా కడితే నష్టం పెరుగుతుందే తప్ప తగ్గదు. రికార్డులు ఉంచుకుని ఫిర్యాదు చేయడం ఒక్కటే సాయపడే మార్గం."}}'::jsonb, null,null,'live','ai'),
  ('safety-insurance-basics-007','safety', array['insurance-basics'], 'diamond','mcq', '{"en":{"prompt":"Hari''s family wants protection against a big hospital bill. Which order of steps makes the most sense?","options":["Pick the cheapest policy, then read the terms after a claim","Buy whatever policy a friend has, without reading it","Wait until someone falls sick, then buy a policy","List needs, compare cover and exclusions, then check claim process"],"answer":"D","explanation":"Knowing what you need and what each policy covers or leaves out avoids nasty surprises later. Checking how claims work makes sure help arrives when needed."},"hi":{"prompt":"हरि का परिवार अस्पताल के बड़े बिल से सुरक्षा चाहता है। कौन-सा क्रम सबसे सही है?","options":["सबसे सस्ती पॉलिसी चुनें, फिर क्लेम के बाद शर्तें पढ़ें","दोस्त के पास जो पॉलिसी है, वही बिना पढ़े ले लें","किसी के बीमार होने का इंतज़ार करें, फिर पॉलिसी लें","ज़रूरतें लिखें, कवर और एक्सक्लूज़न की तुलना करें, फिर क्लेम का तरीका जाँचें"],"answer":"D","explanation":"आपको क्या चाहिए और हर पॉलिसी क्या कवर करती है या क्या छोड़ देती है, यह जानने से बाद में बुरे सरप्राइज़ नहीं मिलते। क्लेम का तरीका जाँचने से ज़रूरत के समय मदद पक्का मिलती है।"},"te":{"prompt":"హరి కుటుంబం పెద్ద హాస్పిటల్ బిల్లు నుంచి రక్షణ కావాలనుకుంటోంది. ఏ వరుసలో అడుగులు వేయడం అత్యంత సరైనది?","options":["అన్నిటికంటే చౌకైన పాలసీ ఎంచుకుని, క్లెయిమ్ తర్వాత నిబంధనలు చదవాలి","ఫ్రెండ్ దగ్గర ఉన్న పాలసీనే చదవకుండా తీసుకోవాలి","ఎవరైనా జబ్బు పడే వరకు ఆగి, తర్వాత పాలసీ తీసుకోవాలి","అవసరాలు రాసుకుని, కవర్, మినహాయింపులు పోల్చి, తర్వాత క్లెయిమ్ ప్రక్రియ చెక్ చేయాలి"],"answer":"D","explanation":"మీకు ఏం కావాలో, ప్రతి పాలసీ ఏం కవర్ చేస్తుందో, ఏం వదిలేస్తుందో తెలుసుకుంటే తర్వాత చేదు అనుభవాలు ఉండవు. క్లెయిమ్ ఎలా పనిచేస్తుందో చెక్ చేస్తే అవసరమైనప్పుడు సాయం అందుతుంది."}}'::jsonb, null,null,'live','ai'),
  ('save-emergency-fund-001','save', array['emergency-fund'], 'bronze','mcq', '{"en":{"prompt":"In the reel, Peter A paid his ₹3,000 phone repair with zero stress. What had he done?","options":["Saved ₹200 a month in a separate pot","Borrowed the money from a friend","Took a loan from an instant-loan app","Spent his pocket money on games"],"answer":"A","explanation":"Peter A had been saving ₹200 every month in a separate \"don''t touch\" pot. When the phone broke, the money was already there."},"hi":{"prompt":"रील में Peter A ने अपने फ़ोन की ₹3,000 की रिपेयरिंग बिना किसी टेंशन के करवा ली। उसने पहले से क्या किया था?","options":["हर महीने ₹200 एक अलग डिब्बे में बचाए","दोस्त से पैसे उधार लिए","इंस्टेंट-लोन ऐप से लोन लिया","अपनी पॉकेट मनी गेम्स पर खर्च कर दी"],"answer":"A","explanation":"Peter A हर महीने ₹200 एक अलग \"इसे मत छूना\" वाले डिब्बे में बचा रहा था। जब फ़ोन टूटा, तो पैसे पहले से तैयार थे।"},"te":{"prompt":"రీల్‌లో Peter A తన ఫోన్ రిపేర్‌కి ₹3,000 ఏ టెన్షన్ లేకుండా కట్టేశాడు. అతను ముందే ఏం చేశాడు?","options":["నెలకు ₹200 వేరే డబ్బాలో దాచాడు","ఫ్రెండ్ దగ్గర డబ్బు అప్పు తీసుకున్నాడు","ఇన్‌స్టంట్-లోన్ యాప్ నుంచి లోన్ తీసుకున్నాడు","తన పాకెట్ మనీ గేమ్స్ మీద ఖర్చు పెట్టాడు"],"answer":"A","explanation":"Peter A ప్రతి నెలా ₹200ని ఒక వేరే \"ముట్టుకోకూడని\" డబ్బాలో దాచుకుంటూ వచ్చాడు. ఫోన్ పాడైనప్పుడు, డబ్బు ముందే సిద్ధంగా ఉంది."}}'::jsonb, 'save-emergency-fund',null,'live','ai'),
  ('save-emergency-fund-002','save', array['emergency-fund'], 'bronze','mcq', '{"en":{"prompt":"What is an emergency fund?","options":["Money saved to buy a new phone","Money borrowed when you run short","Money spent during festival sales","Money kept only for sudden, unplanned costs"],"answer":"D","explanation":"An emergency fund is set aside only for surprises like repairs or medical bills. Because it is ready, you do not need to borrow when trouble comes."},"hi":{"prompt":"इमरजेंसी फ़ंड क्या होता है?","options":["नया फ़ोन खरीदने के लिए बचाए गए पैसे","पैसे कम पड़ने पर उधार लिए गए पैसे","त्योहार की सेल में खर्च किए गए पैसे","सिर्फ़ अचानक, बिना प्लान के आने वाले खर्चों के लिए रखे गए पैसे"],"answer":"D","explanation":"इमरजेंसी फ़ंड सिर्फ़ अचानक आने वाले खर्चों, जैसे रिपेयर या इलाज के बिल, के लिए अलग रखा जाता है। क्योंकि यह पहले से तैयार रहता है, मुसीबत आने पर उधार लेने की ज़रूरत नहीं पड़ती।"},"te":{"prompt":"ఎమర్జెన్సీ ఫండ్ అంటే ఏమిటి?","options":["కొత్త ఫోన్ కొనడానికి దాచిన డబ్బు","డబ్బు సరిపోనప్పుడు అప్పుగా తీసుకున్న డబ్బు","పండగ సేల్స్‌లో ఖర్చు పెట్టిన డబ్బు","అనుకోకుండా వచ్చే, ప్లాన్ చేయని ఖర్చుల కోసం మాత్రమే ఉంచిన డబ్బు"],"answer":"D","explanation":"ఎమర్జెన్సీ ఫండ్‌ని రిపేర్లు, హాస్పిటల్ బిల్లుల లాంటి అనుకోని ఖర్చుల కోసం మాత్రమే పక్కన పెడతారు. అది ముందే సిద్ధంగా ఉంటుంది కాబట్టి, కష్టం వచ్చినప్పుడు అప్పు చేయాల్సిన అవసరం ఉండదు."}}'::jsonb, null,'save-emergency-fund','live','ai'),
  ('save-emergency-fund-003','save', array['emergency-fund'], 'bronze','mcq', '{"en":{"prompt":"Which of these is a real reason to use your emergency fund?","options":["A sudden hospital bill for a family member","A new video game that just launched","A big discount on branded shoes","A friend''s birthday party this weekend"],"answer":"A","explanation":"A hospital bill is unplanned and cannot wait, which is exactly what an emergency fund is for. Games, sales and parties are wants you can plan or skip."},"hi":{"prompt":"इनमें से कौन-सी इमरजेंसी फ़ंड इस्तेमाल करने की सही वजह है?","options":["परिवार के किसी सदस्य का अचानक आया अस्पताल का बिल","अभी-अभी लॉन्च हुआ नया वीडियो गेम","ब्रांडेड जूतों पर बड़ा डिस्काउंट","इस वीकेंड दोस्त की बर्थडे पार्टी"],"answer":"A","explanation":"अस्पताल का बिल अचानक आता है और टल नहीं सकता, इमरजेंसी फ़ंड ठीक इसी के लिए होता है। गेम, सेल और पार्टी चाहतें हैं, जिनके लिए आप पहले से प्लान कर सकते हैं या जिन्हें छोड़ सकते हैं।"},"te":{"prompt":"వీటిలో ఎమర్జెన్సీ ఫండ్ వాడడానికి నిజమైన కారణం ఏది?","options":["కుటుంబంలో ఒకరికి అనుకోకుండా వచ్చిన హాస్పిటల్ బిల్లు","ఇప్పుడే లాంచ్ అయిన కొత్త వీడియో గేమ్","బ్రాండెడ్ షూస్ మీద పెద్ద డిస్కౌంట్","ఈ వీకెండ్ ఫ్రెండ్ బర్త్‌డే పార్టీ"],"answer":"A","explanation":"హాస్పిటల్ బిల్లు అనుకోకుండా వస్తుంది, దాన్ని వాయిదా వేయలేం; ఎమర్జెన్సీ ఫండ్ సరిగ్గా దీని కోసమే. గేమ్స్, సేల్స్, పార్టీలు కోరికలు; వాటిని ముందే ప్లాన్ చేసుకోవచ్చు లేదా వదిలేయొచ్చు."}}'::jsonb, null,'save-emergency-fund','live','ai'),
  ('save-emergency-fund-004','save', array['emergency-fund'], 'bronze','mcq', '{"en":{"prompt":"Why should you keep your emergency fund separate from your spending money?","options":["So it earns double the interest","So your parents cannot see it","So you can lend it to friends easily","So you do not spend it by accident"],"answer":"D","explanation":"When the fund is mixed with everyday money, it slowly gets spent on small things. Keeping it apart protects it for a real emergency."},"hi":{"prompt":"अपना इमरजेंसी फ़ंड खर्च वाले पैसों से अलग क्यों रखना चाहिए?","options":["ताकि उस पर दोगुना ब्याज मिले","ताकि आपके माता-पिता उसे देख न सकें","ताकि आप आसानी से दोस्तों को उधार दे सकें","ताकि आप उसे गलती से खर्च न कर दें"],"answer":"D","explanation":"जब फ़ंड रोज़ के पैसों के साथ मिला रहता है, तो वह धीरे-धीरे छोटी-छोटी चीज़ों पर खर्च हो जाता है। उसे अलग रखने से वह असली इमरजेंसी के लिए बचा रहता है।"},"te":{"prompt":"మీ ఎమర్జెన్సీ ఫండ్‌ని ఖర్చు పెట్టే డబ్బు నుంచి ఎందుకు వేరుగా ఉంచాలి?","options":["దానికి రెట్టింపు వడ్డీ రావడానికి","మీ అమ్మానాన్నలు దాన్ని చూడకుండా ఉండడానికి","ఫ్రెండ్స్‌కి సులభంగా అప్పు ఇవ్వడానికి","పొరపాటున దాన్ని ఖర్చు పెట్టకుండా ఉండడానికి"],"answer":"D","explanation":"ఫండ్ రోజువారీ డబ్బుతో కలిసి ఉంటే, అది చిన్న చిన్న వాటికి కొద్దికొద్దిగా ఖర్చైపోతుంది. దాన్ని వేరుగా ఉంచితే, నిజమైన ఎమర్జెన్సీ కోసం భద్రంగా ఉంటుంది."}}'::jsonb, null,'save-emergency-fund','live','ai'),
  ('save-savings-goals-001','save', array['savings-goals'], 'bronze','mcq', '{"en":{"prompt":"Which of these is the clearest savings goal?","options":["Save ₹6,000 for a cycle in 6 months","Save some money soon","Save whatever is left at month end","Save more than my friends do"],"answer":"A","explanation":"A clear goal has an amount and a deadline. Then you can work out how much to save each month (here ₹1,000)."},"hi":{"prompt":"इनमें से सबसे साफ़ बचत लक्ष्य कौन-सा है?","options":["6 महीने में साइकिल के लिए ₹6,000 बचाना","जल्दी ही कुछ पैसे बचाना","महीने के आखिर में जो बचे, वो बचाना","अपने दोस्तों से ज़्यादा बचाना"],"answer":"A","explanation":"साफ़ लक्ष्य में रकम और समय-सीमा, दोनों होते हैं। फिर आप हिसाब लगा सकते हैं कि हर महीने कितना बचाना है (यहाँ ₹1,000)।"},"te":{"prompt":"వీటిలో అన్నిటికంటే స్పష్టమైన సేవింగ్స్ గోల్ ఏది?","options":["6 నెలల్లో సైకిల్ కోసం ₹6,000 దాచడం","త్వరలో కొంత డబ్బు దాచడం","నెలాఖరుకు ఏది మిగిలితే అది దాచడం","నా ఫ్రెండ్స్ కంటే ఎక్కువ దాచడం"],"answer":"A","explanation":"స్పష్టమైన గోల్‌లో ఎంత డబ్బు, ఎప్పటికల్లా అనే రెండూ ఉంటాయి. అప్పుడు నెలకు ఎంత దాచాలో లెక్కపెట్టొచ్చు (ఇక్కడ ₹1,000)."}}'::jsonb, null,'save-emergency-fund','live','ai'),
  ('save-emergency-fund-005','save', array['emergency-fund','savings-goals'], 'bronze','mcq', '{"en":{"prompt":"Kavya gets small pocket money and has no emergency fund yet. What is a good way to start one?","options":["Wait until she earns a full salary","Save only when she gets birthday money","Borrow money to fill it at once","Save a small amount, like ₹100, every month"],"answer":"D","explanation":"Even ₹100 a month adds up, and the habit matters more than the size. Starting small now is better than waiting for a big amount."},"hi":{"prompt":"काव्या को थोड़ी पॉकेट मनी मिलती है और अभी उसके पास कोई इमरजेंसी फ़ंड नहीं है। इसे शुरू करने का अच्छा तरीका क्या है?","options":["पूरी सैलरी मिलने तक इंतज़ार करना","सिर्फ़ तब बचाना जब जन्मदिन पर पैसे मिलें","एक साथ भरने के लिए पैसे उधार लेना","हर महीने थोड़ी रकम, जैसे ₹100, बचाना"],"answer":"D","explanation":"₹100 महीना भी जुड़ते-जुड़ते बढ़ जाता है, और रकम से ज़्यादा आदत मायने रखती है। बड़ी रकम का इंतज़ार करने से अच्छा है अभी छोटे से शुरू करना।"},"te":{"prompt":"కావ్యకి కొంచెం పాకెట్ మనీ వస్తుంది, ఇంకా ఎమర్జెన్సీ ఫండ్ లేదు. దాన్ని మొదలుపెట్టడానికి మంచి మార్గం ఏది?","options":["పూర్తి జీతం వచ్చేవరకు ఆగడం","బర్త్‌డే డబ్బు వచ్చినప్పుడు మాత్రమే దాచడం","ఒకేసారి నింపడానికి అప్పు తీసుకోవడం","ప్రతి నెలా ₹100 లాంటి చిన్న మొత్తం దాచడం"],"answer":"D","explanation":"నెలకు ₹100 అయినా కలిసి కలిసి పెరుగుతుంది, మొత్తం కంటే అలవాటే ముఖ్యం. పెద్ద మొత్తం కోసం ఎదురుచూడడం కంటే ఇప్పుడే చిన్నగా మొదలుపెట్టడం మంచిది."}}'::jsonb, null,'save-emergency-fund','live','ai'),
  ('save-bank-accounts-001','save', array['bank-accounts'], 'bronze','mcq', '{"en":{"prompt":"A bank pays you a small extra amount for keeping money in a savings account. What is it called?","options":["Interest","Dividend","EMI","Cashback"],"answer":"A","explanation":"Interest is what the bank pays you for keeping your money with it. The bank uses deposits to give loans and shares part of what it earns."},"hi":{"prompt":"सेविंग्स अकाउंट में पैसे रखने पर बैंक आपको थोड़े एक्स्ट्रा पैसे देता है। इसे क्या कहते हैं?","options":["ब्याज","डिविडेंड","EMI","कैशबैक"],"answer":"A","explanation":"ब्याज वह रकम है जो बैंक आपको अपना पैसा उसके पास रखने के बदले देता है। बैंक जमा पैसों से लोन देता है और जो कमाता है, उसका एक हिस्सा आपके साथ बाँटता है।"},"te":{"prompt":"సేవింగ్స్ అకౌంట్‌లో డబ్బు ఉంచినందుకు బ్యాంక్ మీకు కొంచెం అదనపు డబ్బు ఇస్తుంది. దాన్ని ఏమంటారు?","options":["వడ్డీ","డివిడెండ్","EMI","క్యాష్‌బ్యాక్"],"answer":"A","explanation":"మీ డబ్బుని తన దగ్గర ఉంచినందుకు బ్యాంక్ మీకు ఇచ్చేదే వడ్డీ. బ్యాంక్ డిపాజిట్ల నుంచి లోన్లు ఇస్తుంది, సంపాదించిన దానిలో కొంత భాగం మీతో పంచుకుంటుంది."}}'::jsonb, null,null,'live','ai'),
  ('save-bank-accounts-002','save', array['bank-accounts'], 'bronze','mcq', '{"en":{"prompt":"Why is a bank savings account safer than a piggy bank for your savings?","options":["The bank doubles your money every year","You can never take the money out","The bank pays your bills for you","Money is protected from loss and also earns interest"],"answer":"D","explanation":"Money at home can be lost, stolen or spent on impulse, while a bank keeps it safe. A savings account also adds interest to it."},"hi":{"prompt":"बचत के लिए बैंक का सेविंग्स अकाउंट गुल्लक से ज़्यादा सुरक्षित क्यों है?","options":["बैंक हर साल आपके पैसे दोगुने कर देता है","आप पैसे कभी नहीं निकाल सकते","बैंक आपके बिल भर देता है","पैसा खोने से बचा रहता है और उस पर ब्याज भी मिलता है"],"answer":"D","explanation":"घर पर रखा पैसा खो सकता है, चोरी हो सकता है या मन करने पर यूँ ही खर्च हो सकता है, जबकि बैंक उसे सुरक्षित रखता है। सेविंग्स अकाउंट उस पर ब्याज भी जोड़ता है।"},"te":{"prompt":"మీ పొదుపుకి హుండీ కంటే బ్యాంక్ సేవింగ్స్ అకౌంట్ ఎందుకు సురక్షితం?","options":["బ్యాంక్ ప్రతి సంవత్సరం మీ డబ్బుని రెట్టింపు చేస్తుంది","మీరు ఎప్పటికీ డబ్బు తీయలేరు","బ్యాంక్ మీ బిల్లులు కడుతుంది","డబ్బు పోకుండా భద్రంగా ఉంటుంది, వడ్డీ కూడా వస్తుంది"],"answer":"D","explanation":"ఇంట్లో ఉన్న డబ్బు పోవచ్చు, దొంగతనం కావచ్చు, లేదా తొందరపడి ఖర్చైపోవచ్చు; బ్యాంక్ దాన్ని భద్రంగా ఉంచుతుంది. సేవింగ్స్ అకౌంట్ దానికి వడ్డీ కూడా కలుపుతుంది."}}'::jsonb, null,null,'live','ai'),
  ('save-bank-accounts-003','save', array['bank-accounts'], 'bronze','mcq', '{"en":{"prompt":"What is a fixed deposit (FD)?","options":["Money left in a bank for a fixed time and rate","A loan the bank gives to students","A card used to pay in shops","An account you can top up daily"],"answer":"A","explanation":"In an FD you keep money with the bank for a fixed period. In return the bank pays an interest rate fixed at the start."},"hi":{"prompt":"फ़िक्स्ड डिपॉज़िट (FD) क्या है?","options":["तय समय और तय ब्याज दर पर बैंक में रखा गया पैसा","बैंक का छात्रों को दिया जाने वाला लोन","दुकानों में पेमेंट करने वाला कार्ड","ऐसा अकाउंट जिसमें आप रोज़ पैसे डाल सकें"],"answer":"A","explanation":"FD में आप तय समय के लिए बैंक में पैसे रखते हैं। बदले में बैंक वह ब्याज दर देता है जो शुरुआत में ही तय हो जाती है।"},"te":{"prompt":"ఫిక్స్‌డ్ డిపాజిట్ (FD) అంటే ఏమిటి?","options":["నిర్ణీత కాలానికి, నిర్ణీత వడ్డీ రేటుకి బ్యాంక్‌లో ఉంచిన డబ్బు","బ్యాంక్ విద్యార్థులకు ఇచ్చే లోన్","షాపుల్లో పేమెంట్ చేయడానికి వాడే కార్డ్","రోజూ డబ్బు వేయగలిగే అకౌంట్"],"answer":"A","explanation":"FDలో మీరు ఒక నిర్ణీత కాలం పాటు బ్యాంక్ దగ్గర డబ్బు ఉంచుతారు. బదులుగా, బ్యాంక్ మొదట్లోనే ఫిక్స్ చేసిన వడ్డీ రేటు ఇస్తుంది."}}'::jsonb, null,null,'live','ai'),
  ('save-simple-interest-001','save', array['simple-interest'], 'bronze','mcq', '{"en":{"prompt":"What is simple interest?","options":["Interest paid on interest as well","Interest paid only on the money you first put in","Interest that changes every single day","A fee the bank takes from you"],"answer":"B","explanation":"Simple interest is worked out only on the original amount. It stays the same every year."},"hi":{"prompt":"साधारण ब्याज (सिंपल इंटरेस्ट) क्या है?","options":["ब्याज पर भी मिलने वाला ब्याज","सिर्फ़ शुरू में जमा किए गए पैसों पर मिलने वाला ब्याज","हर दिन बदलने वाला ब्याज","बैंक की तरफ़ से आपसे ली जाने वाली फ़ीस"],"answer":"B","explanation":"साधारण ब्याज सिर्फ़ मूल रकम पर निकाला जाता है। यह हर साल एक जैसा रहता है।"},"te":{"prompt":"సాధారణ వడ్డీ (సింపుల్ ఇంట్రెస్ట్) అంటే ఏమిటి?","options":["వడ్డీ మీద కూడా వచ్చే వడ్డీ","మీరు మొదట వేసిన డబ్బు మీద మాత్రమే వచ్చే వడ్డీ","ప్రతి రోజూ మారే వడ్డీ","బ్యాంక్ మీ నుంచి తీసుకునే ఫీజు"],"answer":"B","explanation":"సాధారణ వడ్డీని అసలు మొత్తం మీద మాత్రమే లెక్కిస్తారు. అది ప్రతి సంవత్సరం ఒకేలా ఉంటుంది."}}'::jsonb, null,null,'live','ai'),
  ('save-simple-interest-002','save', array['simple-interest'], 'bronze','mcq', '{"en":{"prompt":"Arun puts ₹2,000 in a bank. What is this first amount called?","options":["Interest","Profit","Inflation","Principal"],"answer":"D","explanation":"The principal is the starting amount you deposit or borrow. Interest is calculated on it."},"hi":{"prompt":"अरुण बैंक में ₹2,000 जमा करता है। इस शुरुआती रकम को क्या कहते हैं?","options":["ब्याज","मुनाफ़ा","महंगाई","मूलधन"],"answer":"D","explanation":"मूलधन वह शुरुआती रकम है जो आप जमा करते हैं या उधार लेते हैं। ब्याज इसी पर निकाला जाता है।"},"te":{"prompt":"అరుణ్ బ్యాంక్‌లో ₹2,000 వేశాడు. ఈ మొదటి మొత్తాన్ని ఏమంటారు?","options":["వడ్డీ","లాభం","ద్రవ్యోల్బణం","అసలు"],"answer":"D","explanation":"మీరు డిపాజిట్ చేసే లేదా అప్పుగా తీసుకునే మొదటి మొత్తమే అసలు. వడ్డీని దాని మీదే లెక్కిస్తారు."}}'::jsonb, null,null,'live','ai'),
  ('save-compound-interest-001','save', array['compound-interest'], 'bronze','mcq', '{"en":{"prompt":"What is compound interest?","options":["Interest earned on your money plus past interest","Interest earned only on the first deposit","Interest that is paid just once","A penalty for taking money out early"],"answer":"A","explanation":"With compound interest, the interest is added to your money and then earns interest too. This makes savings grow faster over time."},"hi":{"prompt":"चक्रवृद्धि ब्याज (कंपाउंड इंटरेस्ट) क्या है?","options":["आपके पैसों और पहले मिले ब्याज, दोनों पर मिलने वाला ब्याज","सिर्फ़ पहली जमा पर मिलने वाला ब्याज","सिर्फ़ एक बार मिलने वाला ब्याज","जल्दी पैसे निकालने पर लगने वाला जुर्माना"],"answer":"A","explanation":"चक्रवृद्धि ब्याज में ब्याज आपके पैसों में जुड़ जाता है और फिर उस पर भी ब्याज मिलता है। इससे समय के साथ बचत तेज़ी से बढ़ती है।"},"te":{"prompt":"చక్రవడ్డీ (కాంపౌండ్ ఇంట్రెస్ట్) అంటే ఏమిటి?","options":["మీ డబ్బు మీదా, ఇంతకు ముందు వచ్చిన వడ్డీ మీదా వచ్చే వడ్డీ","మొదటి డిపాజిట్ మీద మాత్రమే వచ్చే వడ్డీ","ఒక్కసారి మాత్రమే ఇచ్చే వడ్డీ","ముందుగానే డబ్బు తీస్తే వేసే జరిమానా"],"answer":"A","explanation":"చక్రవడ్డీలో వడ్డీ మీ డబ్బులో కలుస్తుంది, తర్వాత దాని మీద కూడా వడ్డీ వస్తుంది. దీంతో కాలం గడిచేకొద్దీ పొదుపు వేగంగా పెరుగుతుంది."}}'::jsonb, null,'save-credit-card-trap','live','ai'),
  ('save-inflation-001','save', array['inflation'], 'bronze','mcq', '{"en":{"prompt":"What does inflation mean?","options":["Prices rise over time, so money buys less","Prices fall, so money buys more","Banks pay more interest each year","Your savings grow by themselves"],"answer":"A","explanation":"Inflation is the general rise in prices over time. The same ₹100 buys fewer things later."},"hi":{"prompt":"महंगाई (इन्फ़्लेशन) का क्या मतलब है?","options":["समय के साथ दाम बढ़ते हैं, इसलिए पैसों से कम चीज़ें आती हैं","दाम घटते हैं, इसलिए पैसों से ज़्यादा चीज़ें आती हैं","बैंक हर साल ज़्यादा ब्याज देते हैं","आपकी बचत अपने आप बढ़ती है"],"answer":"A","explanation":"महंगाई का मतलब है समय के साथ चीज़ों के दामों का आम तौर पर बढ़ना। वही ₹100 बाद में कम चीज़ें खरीद पाते हैं।"},"te":{"prompt":"ద్రవ్యోల్బణం (ఇన్‌ఫ్లేషన్) అంటే ఏమిటి?","options":["కాలంతో పాటు ధరలు పెరుగుతాయి, కాబట్టి డబ్బుతో తక్కువ వస్తాయి","ధరలు తగ్గుతాయి, కాబట్టి డబ్బుతో ఎక్కువ వస్తాయి","బ్యాంకులు ప్రతి సంవత్సరం ఎక్కువ వడ్డీ ఇస్తాయి","మీ పొదుపు దానంతట అదే పెరుగుతుంది"],"answer":"A","explanation":"ద్రవ్యోల్బణం అంటే కాలంతో పాటు ధరలు మొత్తంగా పెరగడం. అదే ₹100తో తర్వాత తక్కువ వస్తువులు వస్తాయి."}}'::jsonb, null,'invest-inflation','live','ai'),
  ('save-inflation-002','save', array['inflation'], 'bronze','mcq', '{"en":{"prompt":"A samosa cost ₹10 five years ago. Today the same samosa costs ₹15. What is this an example of?","options":["Simple interest","Inflation","Compound interest","Saving"],"answer":"B","explanation":"The same item now costs more rupees, which is inflation. Your money buys less than it did before."},"hi":{"prompt":"पाँच साल पहले एक समोसा ₹10 का था। आज वही समोसा ₹15 का है। यह किसका उदाहरण है?","options":["साधारण ब्याज","महंगाई","चक्रवृद्धि ब्याज","बचत"],"answer":"B","explanation":"वही चीज़ अब ज़्यादा रुपयों में मिलती है, यही महंगाई है। आपके पैसों से अब पहले से कम चीज़ें आती हैं।"},"te":{"prompt":"ఐదేళ్ల క్రితం ఒక సమోసా ₹10. ఇప్పుడు అదే సమోసా ₹15. ఇది దేనికి ఉదాహరణ?","options":["సాధారణ వడ్డీ","ద్రవ్యోల్బణం","చక్రవడ్డీ","పొదుపు"],"answer":"B","explanation":"అదే వస్తువుకి ఇప్పుడు ఎక్కువ రూపాయలు కట్టాలి, అదే ద్రవ్యోల్బణం. మీ డబ్బుతో ఇప్పుడు ముందుకంటే తక్కువ వస్తాయి."}}'::jsonb, null,'invest-inflation','live','ai'),
  ('save-savings-goals-002','save', array['savings-goals'], 'bronze','mcq', '{"en":{"prompt":"Kiran wants a ₹1,500 cricket bat. Which of these is a clear savings goal?","options":["Save some money sometime this year","Save whatever is left each month","Save ₹300 a month for 5 months","Borrow the money from friends"],"answer":"C","explanation":"A clear goal names the amount, the time and the monthly step. ₹300 × 5 months = ₹1,500."},"hi":{"prompt":"किरण को ₹1,500 का क्रिकेट बैट चाहिए। इनमें से कौन-सा साफ़ बचत लक्ष्य है?","options":["इस साल कभी कुछ पैसे बचाना","हर महीने जो बचे, वो बचाना","5 महीने तक हर महीने ₹300 बचाना","दोस्तों से पैसे उधार लेना"],"answer":"C","explanation":"साफ़ लक्ष्य में रकम, समय और हर महीने का कदम तय होता है। ₹300 × 5 महीने = ₹1,500।"},"te":{"prompt":"కిరణ్‌కి ₹1,500 క్రికెట్ బ్యాట్ కావాలి. వీటిలో స్పష్టమైన సేవింగ్స్ గోల్ ఏది?","options":["ఈ సంవత్సరం ఎప్పుడో కొంత డబ్బు దాచడం","ప్రతి నెలా మిగిలింది దాచడం","5 నెలల పాటు నెలకు ₹300 దాచడం","ఫ్రెండ్స్ దగ్గర అప్పు తీసుకోవడం"],"answer":"C","explanation":"స్పష్టమైన గోల్‌లో మొత్తం, సమయం, నెలనెలా వేయాల్సిన అడుగు ఉంటాయి. ₹300 × 5 నెలలు = ₹1,500."}}'::jsonb, null,null,'live','ai'),
  ('save-compound-interest-002','save', array['compound-interest'], 'silver','mcq', '{"en":{"prompt":"In the reel, two Mortys each save ₹500 a month until 58. One starts at 18, one at 28. Why does Early Morty end with far more?","options":["He got a much higher interest rate","He saved far more money each month","Late Morty took out his savings early","His money had ten more years to compound"],"answer":"D","explanation":"Both saved the same ₹500 at the same assumed rate, but Early Morty''s returns had more years to earn returns of their own. Time is what made his money snowball."},"hi":{"prompt":"रील में दो Morty 58 साल की उम्र तक हर महीने ₹500 बचाते हैं। एक 18 साल में शुरू करता है, दूसरा 28 में। आखिर में Early Morty के पास कहीं ज़्यादा पैसे क्यों होते हैं?","options":["उसे बहुत ज़्यादा ब्याज दर मिली","उसने हर महीने कहीं ज़्यादा पैसे बचाए","Late Morty ने अपनी बचत जल्दी निकाल ली","उसके पैसों को कंपाउंड होने के लिए दस साल ज़्यादा मिले"],"answer":"D","explanation":"दोनों ने एक ही मानी गई दर पर ₹500 बचाए, लेकिन Early Morty के रिटर्न को खुद रिटर्न कमाने के लिए ज़्यादा साल मिले। समय की वजह से ही उसका पैसा स्नोबॉल की तरह बढ़ा।"},"te":{"prompt":"రీల్‌లో ఇద్దరు Mortyలు 58 ఏళ్ల వరకు నెలకు ₹500 చొప్పున దాచుకుంటారు. ఒకరు 18 ఏళ్లకు, మరొకరు 28 ఏళ్లకు మొదలుపెడతారు. చివరికి Early Morty దగ్గర ఎందుకు చాలా ఎక్కువ ఉంటుంది?","options":["అతనికి చాలా ఎక్కువ వడ్డీ రేటు వచ్చింది","అతను నెలకు చాలా ఎక్కువ డబ్బు దాచాడు","Late Morty తన పొదుపుని ముందే తీసేశాడు","అతని డబ్బుకి కాంపౌండ్ అవ్వడానికి పది సంవత్సరాలు ఎక్కువ దొరికాయి"],"answer":"D","explanation":"ఇద్దరూ ఒకే అంచనా రేటుతో అదే ₹500 దాచారు, కానీ Early Morty రిటర్న్స్‌కి సొంతంగా రిటర్న్స్ సంపాదించడానికి ఎక్కువ సంవత్సరాలు దొరికాయి. అతని డబ్బు స్నోబాల్‌లా పెరగడానికి కారణం సమయమే."}}'::jsonb, 'save-compounding',null,'live','ai'),
  ('save-emergency-fund-006','save', array['emergency-fund'], 'silver','mcq', '{"en":{"prompt":"Riya has ₹2,000 in her emergency fund. Her friends plan a ₹1,500 day trip next month. What should she do?","options":["Keep the fund and save separately for the trip","Use the fund, since she can refill it","Use half the fund and borrow the rest","Close the fund to have more fun money"],"answer":"A","explanation":"A planned trip is not an emergency, so it needs its own savings. Keeping the fund untouched means she is still ready for real surprises."},"hi":{"prompt":"रिया के इमरजेंसी फ़ंड में ₹2,000 हैं। उसके दोस्त अगले महीने ₹1,500 की एक दिन की ट्रिप का प्लान बना रहे हैं। उसे क्या करना चाहिए?","options":["फ़ंड को रहने दे और ट्रिप के लिए अलग से बचाए","फ़ंड इस्तेमाल करे, क्योंकि बाद में फिर भर सकती है","आधा फ़ंड इस्तेमाल करे और बाकी उधार ले","मौज-मस्ती के लिए ज़्यादा पैसे पाने को फ़ंड बंद कर दे"],"answer":"A","explanation":"प्लान की हुई ट्रिप इमरजेंसी नहीं है, इसलिए उसके लिए अलग बचत चाहिए। फ़ंड को बिना छुए रखने से वह असली मुसीबतों के लिए तैयार रहती है।"},"te":{"prompt":"రియా ఎమర్జెన్సీ ఫండ్‌లో ₹2,000 ఉన్నాయి. వచ్చే నెల ఆమె ఫ్రెండ్స్ ₹1,500 ఖర్చయ్యే ఒక రోజు ట్రిప్ ప్లాన్ చేస్తున్నారు. ఆమె ఏం చేయాలి?","options":["ఫండ్‌ని అలాగే ఉంచి, ట్రిప్ కోసం వేరుగా దాచాలి","ఫండ్ వాడేయాలి, తర్వాత మళ్లీ నింపొచ్చు కదా","సగం ఫండ్ వాడి, మిగతాది అప్పు తీసుకోవాలి","ఎంజాయ్ చేయడానికి ఎక్కువ డబ్బు కోసం ఫండ్ మూసేయాలి"],"answer":"A","explanation":"ప్లాన్ చేసిన ట్రిప్ ఎమర్జెన్సీ కాదు, కాబట్టి దానికి వేరే పొదుపు కావాలి. ఫండ్‌ని ముట్టుకోకుండా ఉంచితే, నిజమైన అనుకోని ఖర్చులకి ఆమె సిద్ధంగా ఉంటుంది."}}'::jsonb, null,null,'live','ai'),
  ('save-emergency-fund-007','save', array['emergency-fund'], 'silver','mcq', '{"en":{"prompt":"Kiran used ₹1,000 from her emergency fund to pay for her brother''s medicine. What should she do next?","options":["Leave it empty since the emergency is over","Slowly refill the fund from her pocket money","Stop saving because emergencies are rare","Spend the rest of the fund too"],"answer":"B","explanation":"Emergencies can happen again, so the fund should be built back up. Adding a little each month refills it over time."},"hi":{"prompt":"किरण ने अपने भाई की दवाई के लिए इमरजेंसी फ़ंड से ₹1,000 इस्तेमाल किए। अब उसे क्या करना चाहिए?","options":["इमरजेंसी खत्म हो गई, तो फ़ंड खाली ही छोड़ दे","अपनी पॉकेट मनी से धीरे-धीरे फ़ंड फिर से भरे","बचत बंद कर दे, क्योंकि इमरजेंसी कम ही आती हैं","बाकी फ़ंड भी खर्च कर दे"],"answer":"B","explanation":"इमरजेंसी फिर से आ सकती है, इसलिए फ़ंड को दोबारा भरना चाहिए। हर महीने थोड़ा-थोड़ा डालने से यह समय के साथ फिर भर जाता है।"},"te":{"prompt":"కిరణ్ తన తమ్ముడి మందుల కోసం ఎమర్జెన్సీ ఫండ్ నుంచి ₹1,000 వాడింది. తర్వాత ఆమె ఏం చేయాలి?","options":["ఎమర్జెన్సీ అయిపోయింది కాబట్టి ఫండ్‌ని ఖాళీగా వదిలేయాలి","తన పాకెట్ మనీ నుంచి నెమ్మదిగా ఫండ్‌ని మళ్లీ నింపాలి","ఎమర్జెన్సీలు అరుదు కాబట్టి దాచడం ఆపేయాలి","మిగతా ఫండ్ కూడా ఖర్చు పెట్టేయాలి"],"answer":"B","explanation":"ఎమర్జెన్సీలు మళ్లీ రావచ్చు, కాబట్టి ఫండ్‌ని మళ్లీ పెంచుకోవాలి. ప్రతి నెలా కొంచెం కొంచెం వేస్తే, కొంత కాలానికి అది మళ్లీ నిండుతుంది."}}'::jsonb, null,null,'live','ai'),
  ('save-emergency-fund-008','save', array['emergency-fund','bank-accounts'], 'silver','mcq', '{"en":{"prompt":"Where is the best place to keep an emergency fund?","options":["A 5-year deposit that is hard to break","Lent to a friend who will return it","A savings account you can use quickly","In things whose price goes up and down"],"answer":"C","explanation":"Emergency money must be safe and ready the same day you need it. A savings account gives quick access without the value going up and down."},"hi":{"prompt":"इमरजेंसी फ़ंड रखने की सबसे अच्छी जगह कौन-सी है?","options":["5 साल का डिपॉज़िट, जिसे तोड़ना मुश्किल हो","किसी दोस्त को उधार, जो लौटा देगा","सेविंग्स अकाउंट, जिससे जल्दी पैसे निकाल सकें","ऐसी चीज़ों में, जिनकी कीमत ऊपर-नीचे होती रहती है"],"answer":"C","explanation":"इमरजेंसी का पैसा सुरक्षित होना चाहिए और जिस दिन ज़रूरत हो, उसी दिन मिल जाना चाहिए। सेविंग्स अकाउंट से पैसे जल्दी मिलते हैं और उसकी कीमत ऊपर-नीचे नहीं होती।"},"te":{"prompt":"ఎమర్జెన్సీ ఫండ్ ఉంచడానికి అన్నిటికంటే మంచి చోటు ఏది?","options":["తీయడం కష్టమైన 5 ఏళ్ల డిపాజిట్","తిరిగి ఇస్తానన్న ఫ్రెండ్‌కి అప్పుగా","త్వరగా వాడుకోగలిగే సేవింగ్స్ అకౌంట్","ధర పెరుగుతూ తగ్గుతూ ఉండే వాటిలో"],"answer":"C","explanation":"ఎమర్జెన్సీ డబ్బు భద్రంగా ఉండాలి, అవసరమైన రోజే చేతికి అందాలి. సేవింగ్స్ అకౌంట్‌లో విలువ పెరగడం తగ్గడం లేకుండా, త్వరగా డబ్బు తీసుకోవచ్చు."}}'::jsonb, null,null,'live','ai'),
  ('save-savings-goals-003','save', array['savings-goals'], 'silver','mcq', '{"en":{"prompt":"Meena wants ₹3,600 for a school trip in 6 months. How much should she save each month?","options":["₹300","₹500","₹600","₹720"],"answer":"C","explanation":"Divide the goal by the months: ₹3,600 ÷ 6 = ₹600. Saving that each month gets her there on time."},"hi":{"prompt":"मीना को 6 महीने में स्कूल ट्रिप के लिए ₹3,600 चाहिए। उसे हर महीने कितना बचाना चाहिए?","options":["₹300","₹500","₹600","₹720"],"answer":"C","explanation":"लक्ष्य को महीनों से भाग दें: ₹3,600 ÷ 6 = ₹600। हर महीने इतना बचाने से उसका लक्ष्य समय पर पूरा हो जाएगा।"},"te":{"prompt":"మీనాకి 6 నెలల్లో స్కూల్ ట్రిప్ కోసం ₹3,600 కావాలి. ఆమె ప్రతి నెలా ఎంత దాచాలి?","options":["₹300","₹500","₹600","₹720"],"answer":"C","explanation":"గోల్‌ని నెలలతో భాగించండి: ₹3,600 ÷ 6 = ₹600. ప్రతి నెలా అంత దాచితే ఆమె సమయానికి గోల్ చేరుకుంటుంది."}}'::jsonb, null,null,'live','ai'),
  ('save-savings-goals-004','save', array['savings-goals'], 'silver','mcq', '{"en":{"prompt":"Rahul gets ₹1,000 pocket money a month and wants to save for headphones. Which habit will help him most?","options":["Save whatever is left at the end","Save only in months he spends less","Decide each week if he feels like saving","Put ₹200 aside the day he gets the money"],"answer":"D","explanation":"Saving first, on the day money comes in, makes saving automatic. Waiting until month end often leaves nothing to save."},"hi":{"prompt":"राहुल को हर महीने ₹1,000 पॉकेट मनी मिलती है और वह हेडफ़ोन के लिए बचाना चाहता है। कौन-सी आदत उसकी सबसे ज़्यादा मदद करेगी?","options":["महीने के आखिर में जो बचे, वो बचाना","सिर्फ़ उन महीनों में बचाना जब कम खर्च हो","हर हफ़्ते तय करना कि बचाने का मन है या नहीं","पैसे मिलते ही उसी दिन ₹200 अलग रख देना"],"answer":"D","explanation":"पैसे आते ही उसी दिन पहले बचत करने से बचत अपने आप होने लगती है। महीने के आखिर तक इंतज़ार करने पर अक्सर बचाने को कुछ नहीं बचता।"},"te":{"prompt":"రాహుల్‌కి నెలకు ₹1,000 పాకెట్ మనీ వస్తుంది, హెడ్‌ఫోన్స్ కోసం దాచాలనుకుంటున్నాడు. ఏ అలవాటు అతనికి ఎక్కువగా సాయపడుతుంది?","options":["నెలాఖరుకు మిగిలింది దాచడం","తక్కువ ఖర్చు చేసిన నెలల్లో మాత్రమే దాచడం","దాచాలని అనిపిస్తుందో లేదో ప్రతి వారం నిర్ణయించుకోవడం","డబ్బు వచ్చిన రోజే ₹200 పక్కన పెట్టడం"],"answer":"D","explanation":"డబ్బు వచ్చిన రోజే ముందుగా దాచేస్తే, పొదుపు దానంతట అదే జరిగిపోతుంది. నెలాఖరు వరకు ఆగితే చాలాసార్లు దాచడానికి ఏమీ మిగలదు."}}'::jsonb, null,null,'live','ai'),
  ('save-bank-accounts-004','save', array['bank-accounts'], 'silver','mcq', '{"en":{"prompt":"Sana keeps her ₹5,000 birthday savings in a tin at home. Compared with a savings account, what is she missing?","options":["The chance to double it every year","Safety and the interest the bank would pay","Free money the bank gives every month","Nothing, a tin works the same"],"answer":"B","explanation":"In a bank, her money is protected and earns interest. In a tin it can be lost or stolen and never grows."},"hi":{"prompt":"सना अपने जन्मदिन पर मिले ₹5,000 घर पर एक डिब्बे में रखती है। सेविंग्स अकाउंट की तुलना में उसे क्या नहीं मिल रहा?","options":["हर साल पैसे दोगुने करने का मौका","सुरक्षा और बैंक से मिलने वाला ब्याज","बैंक से हर महीने मिलने वाले मुफ़्त पैसे","कुछ नहीं, डिब्बा भी उतना ही अच्छा है"],"answer":"B","explanation":"बैंक में उसके पैसे सुरक्षित रहते हैं और उन पर ब्याज मिलता है। डिब्बे में वे खो सकते हैं या चोरी हो सकते हैं, और कभी बढ़ते नहीं।"},"te":{"prompt":"సనా తన బర్త్‌డే పొదుపు ₹5,000ని ఇంట్లో ఒక డబ్బాలో ఉంచుతుంది. సేవింగ్స్ అకౌంట్‌తో పోలిస్తే ఆమె ఏం కోల్పోతోంది?","options":["ప్రతి సంవత్సరం దాన్ని రెట్టింపు చేసుకునే అవకాశం","భద్రత, బ్యాంక్ ఇచ్చే వడ్డీ","బ్యాంక్ ప్రతి నెలా ఇచ్చే ఫ్రీ డబ్బు","ఏమీ లేదు, డబ్బా కూడా అలాగే పనిచేస్తుంది"],"answer":"B","explanation":"బ్యాంక్‌లో ఆమె డబ్బు భద్రంగా ఉంటుంది, వడ్డీ కూడా వస్తుంది. డబ్బాలో అయితే పోవచ్చు లేదా దొంగతనం కావచ్చు, ఎప్పటికీ పెరగదు."}}'::jsonb, null,null,'live','ai'),
  ('save-bank-accounts-005','save', array['bank-accounts'], 'silver','mcq', '{"en":{"prompt":"Vikram will not touch ₹10,000 for 2 years. Why might an FD suit him better than a savings account?","options":["FDs let you take money out any time free","FDs always double your money in 2 years","FDs usually pay more interest for a locked period","FDs pay no interest but are safer"],"answer":"C","explanation":"An FD usually offers a higher rate because you agree to leave the money for a fixed time. Since Vikram does not need it soon, he can accept that lock."},"hi":{"prompt":"विक्रम ₹10,000 को 2 साल तक हाथ नहीं लगाएगा। उसके लिए सेविंग्स अकाउंट से FD बेहतर क्यों हो सकती है?","options":["FD से कभी भी मुफ़्त में पैसे निकाल सकते हैं","FD हमेशा 2 साल में पैसे दोगुने कर देती है","तय समय के लिए पैसे रखने पर FD आमतौर पर ज़्यादा ब्याज देती है","FD पर ब्याज नहीं मिलता, लेकिन यह ज़्यादा सुरक्षित है"],"answer":"C","explanation":"FD आमतौर पर ज़्यादा ब्याज दर देती है, क्योंकि आप तय समय तक पैसे न निकालने के लिए राज़ी होते हैं। विक्रम को ये पैसे जल्दी नहीं चाहिए, इसलिए वह यह शर्त मान सकता है।"},"te":{"prompt":"విక్రమ్ ₹10,000ని 2 సంవత్సరాల వరకు ముట్టుకోడు. అతనికి సేవింగ్స్ అకౌంట్ కంటే FD ఎందుకు బాగా సరిపోవచ్చు?","options":["FD నుంచి ఎప్పుడైనా ఫ్రీగా డబ్బు తీసుకోవచ్చు","FD ఎప్పుడూ 2 ఏళ్లలో డబ్బుని రెట్టింపు చేస్తుంది","లాక్ చేసిన కాలానికి FD సాధారణంగా ఎక్కువ వడ్డీ ఇస్తుంది","FD వడ్డీ ఇవ్వదు, కానీ ఎక్కువ సురక్షితం"],"answer":"C","explanation":"నిర్ణీత కాలం డబ్బు తీయకుండా ఉంచుతామని ఒప్పుకుంటాం కాబట్టి, FD సాధారణంగా ఎక్కువ రేటు ఇస్తుంది. విక్రమ్‌కి ఆ డబ్బు త్వరలో అవసరం లేదు కాబట్టి, ఆ లాక్‌కి అతను ఒప్పుకోవచ్చు."}}'::jsonb, null,null,'live','ai'),
  ('save-bank-accounts-006','save', array['bank-accounts'], 'silver','mcq', '{"en":{"prompt":"Divya''s savings account balance went up by ₹25, but she deposited nothing. What is the most likely reason?","options":["Someone sent her money by mistake","The bank gave her a loan","Prices in the market went down","The bank added interest to her account"],"answer":"D","explanation":"Banks add interest to savings accounts from time to time. That small increase is the bank paying her for keeping money there."},"hi":{"prompt":"दिव्या के सेविंग्स अकाउंट का बैलेंस ₹25 बढ़ गया, जबकि उसने कुछ जमा नहीं किया। इसकी सबसे संभावित वजह क्या है?","options":["किसी ने गलती से उसे पैसे भेज दिए","बैंक ने उसे लोन दे दिया","बाज़ार में दाम कम हो गए","बैंक ने उसके अकाउंट में ब्याज जोड़ा"],"answer":"D","explanation":"बैंक समय-समय पर सेविंग्स अकाउंट में ब्याज जोड़ते हैं। यह छोटी-सी बढ़त वही रकम है जो बैंक उसे पैसे रखने के बदले दे रहा है।"},"te":{"prompt":"దివ్య సేవింగ్స్ అకౌంట్ బ్యాలెన్స్ ₹25 పెరిగింది, కానీ ఆమె ఏమీ డిపాజిట్ చేయలేదు. దీనికి అసలు కారణం ఏమై ఉండొచ్చు?","options":["ఎవరో పొరపాటున ఆమెకి డబ్బు పంపారు","బ్యాంక్ ఆమెకి లోన్ ఇచ్చింది","మార్కెట్‌లో ధరలు తగ్గాయి","బ్యాంక్ ఆమె అకౌంట్‌లో వడ్డీ కలిపింది"],"answer":"D","explanation":"బ్యాంకులు అప్పుడప్పుడు సేవింగ్స్ అకౌంట్లలో వడ్డీ కలుపుతాయి. ఆ చిన్న పెరుగుదల, డబ్బు తమ దగ్గర ఉంచినందుకు బ్యాంక్ ఆమెకి ఇచ్చినదే."}}'::jsonb, null,null,'live','ai'),
  ('save-simple-interest-003','save', array['simple-interest'], 'silver','mcq', '{"en":{"prompt":"Priya puts ₹1,000 in a deposit at 5% simple interest a year. How much interest does she earn in 1 year? (Assume the rate stays fixed.)","options":["₹5","₹50","₹500","₹1,050"],"answer":"B","explanation":"5% of ₹1,000 is ₹50. ₹1,050 is the total amount, not the interest."},"hi":{"prompt":"प्रिया ₹1,000 एक डिपॉज़िट में 5% सालाना साधारण ब्याज पर रखती है। 1 साल में उसे कितना ब्याज मिलेगा? (मान लें कि दर तय रहती है।)","options":["₹5","₹50","₹500","₹1,050"],"answer":"B","explanation":"₹1,000 का 5% ₹50 है। ₹1,050 कुल रकम है, ब्याज नहीं।"},"te":{"prompt":"ప్రియ ₹1,000ని సంవత్సరానికి 5% సాధారణ వడ్డీకి డిపాజిట్ చేసింది. 1 సంవత్సరంలో ఆమెకి ఎంత వడ్డీ వస్తుంది? (రేటు మారదని అనుకోండి.)","options":["₹5","₹50","₹500","₹1,050"],"answer":"B","explanation":"₹1,000లో 5% అంటే ₹50. ₹1,050 మొత్తం సొమ్ము, వడ్డీ కాదు."}}'::jsonb, null,null,'live','ai'),
  ('save-simple-interest-004','save', array['simple-interest'], 'silver','mcq', '{"en":{"prompt":"Two deposits pay simple interest on ₹5,000 for 1 year: one at 4%, one at 6%. How much more does the 6% one earn?","options":["₹2","₹100","₹200","₹300"],"answer":"B","explanation":"At 4% you earn ₹200 and at 6% you earn ₹300. The difference is ₹100."},"hi":{"prompt":"दो डिपॉज़िट ₹5,000 पर 1 साल के लिए साधारण ब्याज देते हैं: एक 4% पर, दूसरा 6% पर। 6% वाले पर कितना ज़्यादा मिलता है?","options":["₹2","₹100","₹200","₹300"],"answer":"B","explanation":"4% पर ₹200 मिलते हैं और 6% पर ₹300। फ़र्क ₹100 है।"},"te":{"prompt":"రెండు డిపాజిట్లు ₹5,000 మీద 1 సంవత్సరానికి సాధారణ వడ్డీ ఇస్తాయి: ఒకటి 4%, మరొకటి 6%. 6% దానికి ఎంత ఎక్కువ వస్తుంది?","options":["₹2","₹100","₹200","₹300"],"answer":"B","explanation":"4%కి ₹200, 6%కి ₹300 వస్తాయి. తేడా ₹100."}}'::jsonb, null,null,'live','ai'),
  ('save-compound-interest-003','save', array['compound-interest'], 'silver','mcq', '{"en":{"prompt":"Ankit and Neha each deposit ₹1,000 at the same rate. Ankit takes out his interest every year; Neha leaves hers in. Who has more after 5 years?","options":["Neha, because her interest also earns interest","Ankit, because he took money out often","Both have the same total","Ankit, because withdrawals add bonus interest"],"answer":"A","explanation":"Neha''s interest stays in and earns more interest, so her money compounds. Ankit''s money stays at ₹1,000, so it only earns simple interest."},"hi":{"prompt":"अंकित और नेहा दोनों एक ही दर पर ₹1,000 जमा करते हैं। अंकित हर साल अपना ब्याज निकाल लेता है; नेहा अपना ब्याज अंदर ही रहने देती है। 5 साल बाद किसके पास ज़्यादा होगा?","options":["नेहा, क्योंकि उसके ब्याज पर भी ब्याज मिलता है","अंकित, क्योंकि उसने बार-बार पैसे निकाले","दोनों के पास बराबर कुल रकम होगी","अंकित, क्योंकि पैसे निकालने पर बोनस ब्याज मिलता है"],"answer":"A","explanation":"नेहा का ब्याज अंदर रहता है और उस पर और ब्याज मिलता है, इसलिए उसका पैसा कंपाउंड होता है। अंकित का पैसा ₹1,000 ही रहता है, इसलिए उसे सिर्फ़ साधारण ब्याज मिलता है।"},"te":{"prompt":"అంకిత్, నేహా ఇద్దరూ ఒకే రేటుకి చెరో ₹1,000 డిపాజిట్ చేశారు. అంకిత్ ప్రతి సంవత్సరం తన వడ్డీ తీసేసుకుంటాడు; నేహా తనది అలాగే ఉంచుతుంది. 5 సంవత్సరాల తర్వాత ఎవరి దగ్గర ఎక్కువ ఉంటుంది?","options":["నేహా, ఎందుకంటే ఆమె వడ్డీ మీద కూడా వడ్డీ వస్తుంది","అంకిత్, ఎందుకంటే అతను తరచూ డబ్బు తీశాడు","ఇద్దరి దగ్గర మొత్తం ఒకటే","అంకిత్, ఎందుకంటే డబ్బు తీస్తే బోనస్ వడ్డీ వస్తుంది"],"answer":"A","explanation":"నేహా వడ్డీ అకౌంట్‌లోనే ఉండి మరింత వడ్డీ సంపాదిస్తుంది, కాబట్టి ఆమె డబ్బు కాంపౌండ్ అవుతుంది. అంకిత్ డబ్బు ₹1,000 దగ్గరే ఉంటుంది, కాబట్టి అతనికి సాధారణ వడ్డీ మాత్రమే వస్తుంది."}}'::jsonb, null,'save-credit-card-trap','live','ai'),
  ('save-compound-interest-004','save', array['compound-interest'], 'silver','mcq', '{"en":{"prompt":"Same amount, same yearly rate, same 10 years. Which grows a little more: interest added once a year or every month?","options":["Interest added once a year","Both grow exactly the same","Neither grows, the rate is the same","Interest added every month"],"answer":"D","explanation":"When interest is added more often, it starts earning interest sooner. So monthly compounding ends slightly higher."},"hi":{"prompt":"वही रकम, वही सालाना दर, वही 10 साल। कौन-सा थोड़ा ज़्यादा बढ़ता है: साल में एक बार जुड़ने वाला ब्याज या हर महीने जुड़ने वाला?","options":["साल में एक बार जुड़ने वाला ब्याज","दोनों बिल्कुल बराबर बढ़ते हैं","कोई नहीं बढ़ता, दर तो वही है","हर महीने जुड़ने वाला ब्याज"],"answer":"D","explanation":"जब ब्याज ज़्यादा बार जुड़ता है, तो वह जल्दी ब्याज कमाना शुरू कर देता है। इसलिए हर महीने कंपाउंडिंग से आखिर में थोड़ा ज़्यादा पैसा बनता है।"},"te":{"prompt":"అదే మొత్తం, అదే వార్షిక రేటు, అదే 10 సంవత్సరాలు. ఏది కొంచెం ఎక్కువ పెరుగుతుంది: సంవత్సరానికి ఒకసారి కలిపే వడ్డీనా, ప్రతి నెలా కలిపే వడ్డీనా?","options":["సంవత్సరానికి ఒకసారి కలిపే వడ్డీ","రెండూ సరిగ్గా ఒకేలా పెరుగుతాయి","ఏదీ పెరగదు, రేటు ఒకటే కదా","ప్రతి నెలా కలిపే వడ్డీ"],"answer":"D","explanation":"వడ్డీ ఎంత తరచుగా కలిస్తే, అది అంత త్వరగా వడ్డీ సంపాదించడం మొదలుపెడుతుంది. అందుకే నెలనెలా కాంపౌండింగ్‌తో చివరికి కొంచెం ఎక్కువ వస్తుంది."}}'::jsonb, null,'save-credit-card-trap','live','ai'),
  ('save-inflation-003','save', array['inflation'], 'silver','mcq', '{"en":{"prompt":"Prices rise about 6% a year. Lakshmi keeps ₹1,000 in a drawer for a year. What happens to it?","options":["Still ₹1,000, but it buys less than before","It grows to ₹1,060 by itself","It drops to ₹940 in notes","Nothing changes at all"],"answer":"A","explanation":"The notes stay ₹1,000, but things cost about 6% more. So the same money buys fewer things."},"hi":{"prompt":"दाम हर साल लगभग 6% बढ़ते हैं। लक्ष्मी ₹1,000 एक साल तक दराज़ में रखती है। उन पैसों का क्या होता है?","options":["अब भी ₹1,000 हैं, लेकिन उनसे पहले से कम चीज़ें आती हैं","अपने आप बढ़कर ₹1,060 हो जाते हैं","नोट घटकर ₹940 रह जाते हैं","कुछ भी नहीं बदलता"],"answer":"A","explanation":"नोट ₹1,000 के ही रहते हैं, लेकिन चीज़ें लगभग 6% महंगी हो जाती हैं। इसलिए उतने ही पैसों से कम चीज़ें आती हैं।"},"te":{"prompt":"ధరలు సంవత్సరానికి సుమారు 6% పెరుగుతాయి. లక్ష్మి ₹1,000ని ఒక సంవత్సరం పాటు డ్రాయర్‌లో ఉంచింది. ఆ డబ్బుకి ఏమవుతుంది?","options":["ఇంకా ₹1,000 ఉంటాయి, కానీ ముందుకంటే తక్కువ వస్తువులు వస్తాయి","దానంతట అదే ₹1,060 అవుతుంది","నోట్లు ₹940కి తగ్గిపోతాయి","ఏమీ మారదు"],"answer":"A","explanation":"నోట్లు ₹1,000 గానే ఉంటాయి, కానీ వస్తువుల ధరలు సుమారు 6% పెరుగుతాయి. కాబట్టి అదే డబ్బుతో తక్కువ వస్తువులు వస్తాయి."}}'::jsonb, null,null,'live','ai'),
  ('save-inflation-004','save', array['inflation','bank-accounts'], 'silver','mcq', '{"en":{"prompt":"Your savings account pays 3% a year, and prices rise 6% a year. What happens to what your savings can buy? (Example rates; real rates vary.)","options":["It grows, because you earn interest","It falls, because prices rise faster than interest","It stays exactly the same","It doubles every few years"],"answer":"B","explanation":"Your money grows 3% but prices grow 6%, so each year it buys a little less. Interest must beat inflation for buying power to grow."},"hi":{"prompt":"आपका सेविंग्स अकाउंट सालाना 3% ब्याज देता है, और दाम सालाना 6% बढ़ते हैं। आपकी बचत की खरीदने की ताकत का क्या होता है? (ये उदाहरण की दरें हैं; असली दरें अलग-अलग होती हैं।)","options":["बढ़ती है, क्योंकि आपको ब्याज मिलता है","घटती है, क्योंकि दाम ब्याज से तेज़ बढ़ते हैं","बिल्कुल वैसी ही रहती है","हर कुछ साल में दोगुनी हो जाती है"],"answer":"B","explanation":"आपका पैसा 3% बढ़ता है लेकिन दाम 6% बढ़ते हैं, इसलिए हर साल उससे थोड़ा कम आता है। खरीदने की ताकत बढ़ाने के लिए ब्याज का महंगाई से ज़्यादा होना ज़रूरी है।"},"te":{"prompt":"మీ సేవింగ్స్ అకౌంట్ సంవత్సరానికి 3% ఇస్తుంది, ధరలు సంవత్సరానికి 6% పెరుగుతాయి. మీ పొదుపు కొనుగోలు శక్తికి ఏమవుతుంది? (ఇవి ఉదాహరణ రేట్లు; అసలు రేట్లు మారుతుంటాయి.)","options":["పెరుగుతుంది, ఎందుకంటే వడ్డీ వస్తుంది","తగ్గుతుంది, ఎందుకంటే వడ్డీ కంటే ధరలు వేగంగా పెరుగుతాయి","సరిగ్గా అలాగే ఉంటుంది","కొన్నేళ్లకు ఒకసారి రెట్టింపు అవుతుంది"],"answer":"B","explanation":"మీ డబ్బు 3% పెరుగుతుంది కానీ ధరలు 6% పెరుగుతాయి, కాబట్టి ప్రతి సంవత్సరం దానితో కొంచెం తక్కువ వస్తుంది. కొనుగోలు శక్తి పెరగాలంటే వడ్డీ ద్రవ్యోల్బణం కంటే ఎక్కువ ఉండాలి."}}'::jsonb, null,'invest-inflation','live','ai'),
  ('save-simple-interest-005','save', array['simple-interest'], 'gold','mcq', '{"en":{"prompt":"Anjali puts ₹10,000 in a deposit at 8% simple interest a year for 3 years. What is the total amount at the end? (Assume a fixed rate.)","options":["₹2,400","₹10,800","₹12,400","₹12,597"],"answer":"C","explanation":"Interest each year is 8% of ₹10,000 = ₹800, so 3 years give ₹2,400. Total = ₹10,000 + ₹2,400 = ₹12,400."},"hi":{"prompt":"अंजलि ₹10,000 एक डिपॉज़िट में 3 साल के लिए 8% सालाना साधारण ब्याज पर रखती है। आखिर में कुल रकम कितनी होगी? (मान लें कि दर तय है।)","options":["₹2,400","₹10,800","₹12,400","₹12,597"],"answer":"C","explanation":"हर साल का ब्याज ₹10,000 का 8% = ₹800 है, तो 3 साल में ₹2,400 बनता है। कुल = ₹10,000 + ₹2,400 = ₹12,400।"},"te":{"prompt":"అంజలి ₹10,000ని సంవత్సరానికి 8% సాధారణ వడ్డీకి 3 సంవత్సరాలు డిపాజిట్ చేసింది. చివరికి మొత్తం ఎంత అవుతుంది? (రేటు మారదని అనుకోండి.)","options":["₹2,400","₹10,800","₹12,400","₹12,597"],"answer":"C","explanation":"ప్రతి సంవత్సరం వడ్డీ ₹10,000లో 8% = ₹800, కాబట్టి 3 సంవత్సరాలకి ₹2,400. మొత్తం = ₹10,000 + ₹2,400 = ₹12,400."}}'::jsonb, null,'save-magic-of-compounding','live','ai'),
  ('save-compound-interest-005','save', array['compound-interest'], 'gold','mcq', '{"en":{"prompt":"Suresh deposits ₹10,000 at 10% a year, compounded yearly, for 2 years. How much does he have at the end? (Assume a fixed rate.)","options":["₹11,000","₹12,000","₹12,100","₹12,210"],"answer":"C","explanation":"Year 1: ₹10,000 + ₹1,000 = ₹11,000. Year 2: ₹11,000 + ₹1,100 = ₹12,100."},"hi":{"prompt":"सुरेश ₹10,000 को 2 साल के लिए 10% सालाना दर पर जमा करता है, और ब्याज हर साल कंपाउंड होता है। आखिर में उसके पास कितने होंगे? (मान लें कि दर तय है।)","options":["₹11,000","₹12,000","₹12,100","₹12,210"],"answer":"C","explanation":"साल 1: ₹10,000 + ₹1,000 = ₹11,000। साल 2: ₹11,000 + ₹1,100 = ₹12,100।"},"te":{"prompt":"సురేష్ ₹10,000ని సంవత్సరానికి 10% రేటుకి, ఏటా కాంపౌండ్ అయ్యేలా, 2 సంవత్సరాలు డిపాజిట్ చేశాడు. చివరికి అతని దగ్గర ఎంత ఉంటుంది? (రేటు మారదని అనుకోండి.)","options":["₹11,000","₹12,000","₹12,100","₹12,210"],"answer":"C","explanation":"1వ సంవత్సరం: ₹10,000 + ₹1,000 = ₹11,000. 2వ సంవత్సరం: ₹11,000 + ₹1,100 = ₹12,100."}}'::jsonb, null,'save-magic-of-compounding','live','ai'),
  ('save-compound-interest-006','save', array['compound-interest','simple-interest'], 'gold','mcq', '{"en":{"prompt":"₹5,000 is kept for 2 years at 10% a year. How much more interest does compound interest earn than simple interest? (Assume yearly compounding.)","options":["₹0","₹50","₹100","₹500"],"answer":"B","explanation":"Simple interest gives ₹500 + ₹500 = ₹1,000. Compound gives ₹500 + ₹550 = ₹1,050, which is ₹50 more."},"hi":{"prompt":"₹5,000 को 10% सालाना दर पर 2 साल के लिए रखा जाता है। चक्रवृद्धि ब्याज, साधारण ब्याज से कितना ज़्यादा ब्याज देता है? (मान लें कि ब्याज हर साल कंपाउंड होता है।)","options":["₹0","₹50","₹100","₹500"],"answer":"B","explanation":"साधारण ब्याज से ₹500 + ₹500 = ₹1,000 मिलते हैं। चक्रवृद्धि से ₹500 + ₹550 = ₹1,050 मिलते हैं, यानी ₹50 ज़्यादा।"},"te":{"prompt":"₹5,000ని సంవత్సరానికి 10% రేటుకి 2 సంవత్సరాలు ఉంచారు. సాధారణ వడ్డీ కంటే చక్రవడ్డీ ఎంత ఎక్కువ వడ్డీ ఇస్తుంది? (ఏటా కాంపౌండ్ అవుతుందని అనుకోండి.)","options":["₹0","₹50","₹100","₹500"],"answer":"B","explanation":"సాధారణ వడ్డీతో ₹500 + ₹500 = ₹1,000 వస్తుంది. చక్రవడ్డీతో ₹500 + ₹550 = ₹1,050, అంటే ₹50 ఎక్కువ."}}'::jsonb, null,'save-magic-of-compounding','live','ai'),
  ('save-inflation-005','save', array['inflation'], 'gold','mcq', '{"en":{"prompt":"Rick says money that sits still slowly loses value. If prices rise 5% a year, what will ₹200 of groceries cost next year? (Assume 5% exactly.)","options":["₹190","₹200","₹205","₹210"],"answer":"D","explanation":"5% of ₹200 is ₹10, so the same groceries cost ₹210. ₹200 kept still will no longer buy them."},"hi":{"prompt":"Rick कहता है कि जो पैसा यूँ ही पड़ा रहता है, उसकी कीमत धीरे-धीरे घटती है। अगर दाम हर साल 5% बढ़ें, तो ₹200 का राशन अगले साल कितने का होगा? (मान लें ठीक 5%।)","options":["₹190","₹200","₹205","₹210"],"answer":"D","explanation":"₹200 का 5% ₹10 है, इसलिए वही राशन ₹210 का होगा। पड़े हुए ₹200 से अब वह राशन नहीं खरीदा जा सकेगा।"},"te":{"prompt":"కదలకుండా ఉన్న డబ్బు నెమ్మదిగా విలువ కోల్పోతుందని Rick అంటాడు. ధరలు సంవత్సరానికి 5% పెరిగితే, ₹200 కిరాణా సామాను వచ్చే ఏడాది ఎంత అవుతుంది? (సరిగ్గా 5% అనుకోండి.)","options":["₹190","₹200","₹205","₹210"],"answer":"D","explanation":"₹200లో 5% అంటే ₹10, కాబట్టి అదే సామాను ₹210 అవుతుంది. అలాగే ఉంచిన ₹200తో అది ఇక కొనలేరు."}}'::jsonb, 'save-inflation','save-magic-of-compounding','live','ai'),
  ('save-compound-interest-007','save', array['compound-interest'], 'gold','mcq', '{"en":{"prompt":"The rule of 72 says: years to double ≈ 72 ÷ yearly rate. At 8% a year, compounded, about how long until money doubles?","options":["About 4 years","About 9 years","About 12 years","About 64 years"],"answer":"B","explanation":"72 ÷ 8 = 9, so money roughly doubles in 9 years at 8%. This is a quick estimate, not an exact answer."},"hi":{"prompt":"72 का नियम (रूल ऑफ़ 72) कहता है: पैसे दोगुने होने में लगने वाले साल ≈ 72 ÷ सालाना दर। 8% सालाना कंपाउंड दर पर पैसे लगभग कितने समय में दोगुने होंगे?","options":["लगभग 4 साल","लगभग 9 साल","लगभग 12 साल","लगभग 64 साल"],"answer":"B","explanation":"72 ÷ 8 = 9, यानी 8% पर पैसे लगभग 9 साल में दोगुने होते हैं। यह एक जल्दी लगाया गया अंदाज़ा है, सटीक जवाब नहीं।"},"te":{"prompt":"రూల్ ఆఫ్ 72 (72 నియమం) ప్రకారం: డబ్బు రెట్టింపు అవ్వడానికి పట్టే సంవత్సరాలు ≈ 72 ÷ వార్షిక రేటు. సంవత్సరానికి 8% కాంపౌండ్ రేటుకి, డబ్బు రెట్టింపు అవ్వడానికి సుమారు ఎంత కాలం పడుతుంది?","options":["సుమారు 4 సంవత్సరాలు","సుమారు 9 సంవత్సరాలు","సుమారు 12 సంవత్సరాలు","సుమారు 64 సంవత్సరాలు"],"answer":"B","explanation":"72 ÷ 8 = 9, కాబట్టి 8% వద్ద డబ్బు సుమారు 9 సంవత్సరాల్లో రెట్టింపు అవుతుంది. ఇది త్వరగా వేసే అంచనా మాత్రమే, ఖచ్చితమైన జవాబు కాదు."}}'::jsonb, null,'save-magic-of-compounding','live','ai'),
  ('save-emergency-fund-009','save', array['emergency-fund','savings-goals'], 'platinum','mcq', '{"en":{"prompt":"Zoya has ₹5,000 saved and no emergency fund. Her phone works, but she wants a ₹5,000 upgrade. Which choice best balances both needs?","options":["Spend all ₹5,000 now on the upgrade","Never upgrade, since saving is always better","Keep some as an emergency fund, save more for later","Buy the phone and borrow if trouble comes"],"answer":"C","explanation":"Her phone still works, so the upgrade can wait while she keeps a cushion for surprises. Saving a little more lets her have both, without borrowing later."},"hi":{"prompt":"ज़ोया के पास ₹5,000 की बचत है और कोई इमरजेंसी फ़ंड नहीं है। उसका फ़ोन ठीक चल रहा है, लेकिन वह ₹5,000 का अपग्रेड चाहती है। कौन-सा विकल्प दोनों ज़रूरतों में सबसे अच्छा संतुलन बनाता है?","options":["अभी पूरे ₹5,000 अपग्रेड पर खर्च कर दे","कभी अपग्रेड न करे, क्योंकि बचत हमेशा बेहतर है","कुछ पैसे इमरजेंसी फ़ंड के रूप में रखे, बाद के लिए और बचाए","फ़ोन खरीद ले और मुसीबत आए तो उधार ले"],"answer":"C","explanation":"उसका फ़ोन अभी चल रहा है, इसलिए अपग्रेड रुक सकता है और तब तक वह अचानक के खर्चों के लिए कुछ पैसे रख सकती है। थोड़ा और बचाकर वह बाद में उधार लिए बिना दोनों चीज़ें पा सकती है।"},"te":{"prompt":"జోయా దగ్గర ₹5,000 పొదుపు ఉంది, ఎమర్జెన్సీ ఫండ్ లేదు. ఆమె ఫోన్ బాగానే పనిచేస్తోంది, కానీ ₹5,000తో అప్‌గ్రేడ్ చేయాలనుకుంటోంది. రెండు అవసరాలనూ బాగా బ్యాలెన్స్ చేసే ఎంపిక ఏది?","options":["ఇప్పుడే మొత్తం ₹5,000 అప్‌గ్రేడ్‌కి ఖర్చు పెట్టడం","పొదుపే ఎప్పుడూ మంచిది కాబట్టి, ఎప్పటికీ అప్‌గ్రేడ్ చేయకపోవడం","కొంత ఎమర్జెన్సీ ఫండ్‌గా ఉంచి, తర్వాత కోసం ఇంకా దాచడం","ఫోన్ కొనేసి, కష్టం వస్తే అప్పు చేయడం"],"answer":"C","explanation":"ఆమె ఫోన్ ఇంకా పనిచేస్తోంది కాబట్టి అప్‌గ్రేడ్ ఆగొచ్చు, ఈలోగా అనుకోని ఖర్చుల కోసం కొంత ఉంచుకోవచ్చు. ఇంకొంచెం దాచితే, తర్వాత అప్పు చేయకుండానే రెండూ సాధ్యమవుతాయి."}}'::jsonb, null,null,'live','ai'),
  ('save-bank-accounts-007','save', array['bank-accounts'], 'platinum','mcq', '{"en":{"prompt":"Rohan may need ₹8,000 any week for his mother''s medicine. Why might a savings account suit him better than a 1-year FD, despite lower interest?","options":["He can take money out anytime without a penalty","Savings accounts always pay more than FDs","FD money can never be taken out","Savings accounts grow faster with compounding"],"answer":"A","explanation":"Breaking an FD early usually means lower interest or a penalty. When money may be needed at short notice, easy access matters more than a slightly higher rate."},"hi":{"prompt":"रोहन को अपनी माँ की दवाई के लिए किसी भी हफ़्ते ₹8,000 की ज़रूरत पड़ सकती है। कम ब्याज के बावजूद, उसके लिए 1 साल की FD से सेविंग्स अकाउंट बेहतर क्यों हो सकता है?","options":["वह बिना किसी जुर्माने के कभी भी पैसे निकाल सकता है","सेविंग्स अकाउंट हमेशा FD से ज़्यादा ब्याज देते हैं","FD का पैसा कभी निकाला ही नहीं जा सकता","सेविंग्स अकाउंट कंपाउंडिंग से तेज़ बढ़ते हैं"],"answer":"A","explanation":"FD को जल्दी तोड़ने पर आमतौर पर ब्याज कम मिलता है या जुर्माना लगता है। जब पैसों की ज़रूरत अचानक पड़ सकती हो, तो थोड़ी ज़्यादा दर से ज़्यादा ज़रूरी है कि पैसे आसानी से मिल जाएँ।"},"te":{"prompt":"రోహన్‌కి తన అమ్మ మందుల కోసం ఏ వారమైనా ₹8,000 అవసరం కావచ్చు. వడ్డీ తక్కువైనా, 1 సంవత్సరం FD కంటే సేవింగ్స్ అకౌంట్ అతనికి ఎందుకు బాగా సరిపోవచ్చు?","options":["ఏ జరిమానా లేకుండా ఎప్పుడైనా డబ్బు తీసుకోవచ్చు","సేవింగ్స్ అకౌంట్లు ఎప్పుడూ FD కంటే ఎక్కువ వడ్డీ ఇస్తాయి","FD డబ్బుని ఎప్పటికీ తీయలేరు","సేవింగ్స్ అకౌంట్లు కాంపౌండింగ్‌తో వేగంగా పెరుగుతాయి"],"answer":"A","explanation":"FDని ముందే బ్రేక్ చేస్తే సాధారణంగా వడ్డీ తగ్గుతుంది లేదా జరిమానా పడుతుంది. డబ్బు ఉన్నట్టుండి అవసరమయ్యే అవకాశం ఉంటే, కొంచెం ఎక్కువ రేటు కంటే సులభంగా చేతికి అందడమే ముఖ్యం."}}'::jsonb, null,null,'live','ai'),
  ('save-inflation-006','save', array['inflation','bank-accounts'], 'platinum','mcq', '{"en":{"prompt":"An FD pays 7% a year and a savings account pays 3%. Prices rise 6% a year. Which is true? (Example rates; real rates vary.)","options":["Both grow buying power","FD buying power grows slightly; savings account''s falls","Both lose buying power","Savings account grows; FD loses"],"answer":"B","explanation":"Buying power grows only when interest beats inflation: 7% beats 6% by a little, but 3% falls 3% behind. So the FD just keeps ahead while the savings account loses ground."},"hi":{"prompt":"एक FD सालाना 7% देती है और एक सेविंग्स अकाउंट 3%। दाम सालाना 6% बढ़ते हैं। कौन-सी बात सही है? (ये उदाहरण की दरें हैं; असली दरें अलग-अलग होती हैं।)","options":["दोनों की खरीदने की ताकत बढ़ती है","FD की खरीदने की ताकत थोड़ी बढ़ती है; सेविंग्स अकाउंट की घटती है","दोनों की खरीदने की ताकत घटती है","सेविंग्स अकाउंट की बढ़ती है; FD की घटती है"],"answer":"B","explanation":"खरीदने की ताकत तभी बढ़ती है जब ब्याज महंगाई से ज़्यादा हो: 7% थोड़ा-सा 6% से आगे है, लेकिन 3% पूरे 3% पीछे है। इसलिए FD बस आगे बनी रहती है, जबकि सेविंग्स अकाउंट पीछे छूटता जाता है।"},"te":{"prompt":"ఒక FD సంవత్సరానికి 7%, ఒక సేవింగ్స్ అకౌంట్ 3% ఇస్తాయి. ధరలు సంవత్సరానికి 6% పెరుగుతాయి. ఏది నిజం? (ఇవి ఉదాహరణ రేట్లు; అసలు రేట్లు మారుతుంటాయి.)","options":["రెండింటి కొనుగోలు శక్తి పెరుగుతుంది","FD కొనుగోలు శక్తి కొంచెం పెరుగుతుంది; సేవింగ్స్ అకౌంట్‌ది తగ్గుతుంది","రెండింటి కొనుగోలు శక్తి తగ్గుతుంది","సేవింగ్స్ అకౌంట్‌ది పెరుగుతుంది; FDది తగ్గుతుంది"],"answer":"B","explanation":"వడ్డీ ద్రవ్యోల్బణం కంటే ఎక్కువ ఉన్నప్పుడే కొనుగోలు శక్తి పెరుగుతుంది: 7% అనేది 6% కంటే కొంచెం ముందుంది, కానీ 3% మాత్రం 3% వెనకబడింది. కాబట్టి FD కొద్దిగా ముందుంటుంది, సేవింగ్స్ అకౌంట్ వెనకబడిపోతుంది."}}'::jsonb, null,'invest-inflation','live','ai'),
  ('save-compound-interest-008','save', array['compound-interest','savings-goals'], 'platinum','mcq', '{"en":{"prompt":"Isha, 17, can save ₹500 a month from now, or ₹1,000 a month starting at 27. Both stop at 60. Assume 8% a year (not a promise). Which ends bigger?","options":["₹1,000 from 27, since she pays in more","Both end with exactly the same","₹500 from 17, even though she pays in less","It depends only on the total paid in"],"answer":"C","explanation":"Starting at 17 grows to about ₹22 lakh, while starting at 27 grows to about ₹19 lakh, even though she pays in less. The extra 10 years of compounding outweigh the bigger monthly amount."},"hi":{"prompt":"17 साल की ईशा अभी से हर महीने ₹500 बचा सकती है, या 27 साल की उम्र से हर महीने ₹1,000। दोनों 60 साल पर रुकते हैं। मान लें 8% सालाना (यह कोई वादा नहीं है)। आखिर में कौन-सा ज़्यादा बनेगा?","options":["27 से ₹1,000, क्योंकि उसमें वह ज़्यादा पैसे डालती है","दोनों बिल्कुल बराबर","17 से ₹500, भले ही उसमें वह कम पैसे डालती है","यह सिर्फ़ कुल डाले गए पैसों पर निर्भर करता है"],"answer":"C","explanation":"17 से शुरू करने पर, कम पैसे डालने के बावजूद, लगभग ₹22 लाख बनते हैं, जबकि 27 से शुरू करने पर लगभग ₹19 लाख। कंपाउंडिंग के 10 एक्स्ट्रा साल बड़ी मासिक रकम पर भारी पड़ते हैं।"},"te":{"prompt":"17 ఏళ్ల ఇషా ఇప్పటి నుంచి నెలకు ₹500 దాచొచ్చు, లేదా 27 ఏళ్ల నుంచి నెలకు ₹1,000 దాచొచ్చు. రెండూ 60 ఏళ్లకు ఆగుతాయి. సంవత్సరానికి 8% అనుకోండి (ఇది హామీ కాదు). చివరికి ఏది ఎక్కువ అవుతుంది?","options":["27 నుంచి ₹1,000, ఎందుకంటే అందులో ఆమె ఎక్కువ కడుతుంది","రెండూ సరిగ్గా సమానం","17 నుంచి ₹500, అందులో ఆమె తక్కువ కట్టినా సరే","కట్టిన మొత్తం మీద మాత్రమే ఆధారపడి ఉంటుంది"],"answer":"C","explanation":"తక్కువ కట్టినా, 17 నుంచి మొదలుపెడితే సుమారు ₹22 లక్షలు అవుతాయి, 27 నుంచి మొదలుపెడితే సుమారు ₹19 లక్షలు. కాంపౌండింగ్‌కి దొరికిన అదనపు 10 సంవత్సరాలు, ఎక్కువ నెలవారీ మొత్తం కంటే బలంగా పనిచేస్తాయి."}}'::jsonb, null,null,'live','ai'),
  ('save-savings-goals-005','save', array['savings-goals'], 'platinum','mcq', '{"en":{"prompt":"Kabir wants a ₹12,000 laptop. He can save ₹1,000 a month for a year, or buy now paying ₹1,200 a month for a year. What is the trade-off?","options":["Both options cost exactly ₹12,000","Saving first costs ₹2,400 more","Buying now costs only ₹200 extra","Buying now costs ₹2,400 extra; waiting costs nothing extra"],"answer":"D","explanation":"Paying ₹1,200 × 12 = ₹14,400 is ₹2,400 more than the price. Saving first means waiting a year, but he pays only ₹12,000."},"hi":{"prompt":"कबीर को ₹12,000 का लैपटॉप चाहिए। वह एक साल तक हर महीने ₹1,000 बचा सकता है, या अभी खरीदकर एक साल तक हर महीने ₹1,200 चुका सकता है। दोनों रास्तों में असली फ़र्क क्या है?","options":["दोनों में खर्च बिल्कुल ₹12,000 है","पहले बचाने पर ₹2,400 ज़्यादा लगते हैं","अभी खरीदने पर सिर्फ़ ₹200 ज़्यादा लगते हैं","अभी खरीदने पर ₹2,400 ज़्यादा लगते हैं; इंतज़ार करने पर कुछ ज़्यादा नहीं लगता"],"answer":"D","explanation":"₹1,200 × 12 = ₹14,400 चुकाना कीमत से ₹2,400 ज़्यादा है। पहले बचाने का मतलब एक साल इंतज़ार है, लेकिन तब उसे सिर्फ़ ₹12,000 देने पड़ते हैं।"},"te":{"prompt":"కబీర్‌కి ₹12,000 ల్యాప్‌టాప్ కావాలి. అతను ఒక సంవత్సరం పాటు నెలకు ₹1,000 దాచొచ్చు, లేదా ఇప్పుడే కొని ఒక సంవత్సరం పాటు నెలకు ₹1,200 కట్టొచ్చు. ఈ రెండు దారుల మధ్య అసలు తేడా ఏమిటి?","options":["రెండింటికీ సరిగ్గా ₹12,000 ఖర్చు","ముందు దాచితే ₹2,400 ఎక్కువ ఖర్చు","ఇప్పుడే కొంటే కేవలం ₹200 ఎక్కువ","ఇప్పుడే కొంటే ₹2,400 ఎక్కువ; ఆగితే ఏమీ ఎక్కువ కాదు"],"answer":"D","explanation":"₹1,200 × 12 = ₹14,400, అంటే ధర కంటే ₹2,400 ఎక్కువ. ముందు దాచితే ఒక సంవత్సరం ఆగాలి, కానీ అతను కట్టేది ₹12,000 మాత్రమే."}}'::jsonb, null,null,'live','ai'),
  ('save-savings-goals-006','save', array['savings-goals'], 'diamond','mcq', '{"en":{"prompt":"Ananya needs ₹30,000 for college fees in 2 years. She already has ₹6,000 saved. Ignoring interest, how much must she save each month?","options":["₹750","₹1,000","₹1,250","₹2,000"],"answer":"B","explanation":"She still needs ₹30,000 − ₹6,000 = ₹24,000. Over 24 months that is ₹24,000 ÷ 24 = ₹1,000 a month."},"hi":{"prompt":"अनन्या को 2 साल में कॉलेज फ़ीस के लिए ₹30,000 चाहिए। उसके पास पहले से ₹6,000 बचे हुए हैं। ब्याज को छोड़ दें, तो उसे हर महीने कितना बचाना होगा?","options":["₹750","₹1,000","₹1,250","₹2,000"],"answer":"B","explanation":"उसे अभी भी ₹30,000 − ₹6,000 = ₹24,000 चाहिए। 24 महीनों में यह ₹24,000 ÷ 24 = ₹1,000 महीना है।"},"te":{"prompt":"అనన్యకి 2 సంవత్సరాల్లో కాలేజీ ఫీజు కోసం ₹30,000 కావాలి. ఆమె దగ్గర ఇప్పటికే ₹6,000 దాచినవి ఉన్నాయి. వడ్డీని లెక్కలోకి తీసుకోకపోతే, ఆమె నెలకు ఎంత దాచాలి?","options":["₹750","₹1,000","₹1,250","₹2,000"],"answer":"B","explanation":"ఆమెకి ఇంకా ₹30,000 − ₹6,000 = ₹24,000 కావాలి. 24 నెలల్లో అంటే నెలకు ₹24,000 ÷ 24 = ₹1,000."}}'::jsonb, null,null,'live','ai'),
  ('save-emergency-fund-010','save', array['emergency-fund','savings-goals'], 'diamond','mcq', '{"en":{"prompt":"Nikhil saves ₹1,500 a month. First he builds a ₹6,000 emergency fund, then saves for a ₹9,000 course. Ignoring interest, how many months until both are done?","options":["4 months","6 months","10 months","15 months"],"answer":"C","explanation":"He needs ₹6,000 + ₹9,000 = ₹15,000 in total. At ₹1,500 a month, that takes 15,000 ÷ 1,500 = 10 months."},"hi":{"prompt":"निखिल हर महीने ₹1,500 बचाता है। पहले वह ₹6,000 का इमरजेंसी फ़ंड बनाता है, फिर ₹9,000 के कोर्स के लिए बचाता है। ब्याज को छोड़ दें, तो दोनों पूरे होने में कितने महीने लगेंगे?","options":["4 महीने","6 महीने","10 महीने","15 महीने"],"answer":"C","explanation":"उसे कुल ₹6,000 + ₹9,000 = ₹15,000 चाहिए। ₹1,500 महीने के हिसाब से इसमें 15,000 ÷ 1,500 = 10 महीने लगते हैं।"},"te":{"prompt":"నిఖిల్ నెలకు ₹1,500 దాస్తాడు. ముందు ₹6,000 ఎమర్జెన్సీ ఫండ్ కూడబెడతాడు, తర్వాత ₹9,000 కోర్సు కోసం దాస్తాడు. వడ్డీని లెక్కలోకి తీసుకోకపోతే, రెండూ పూర్తవడానికి ఎన్ని నెలలు పడుతుంది?","options":["4 నెలలు","6 నెలలు","10 నెలలు","15 నెలలు"],"answer":"C","explanation":"అతనికి మొత్తం ₹6,000 + ₹9,000 = ₹15,000 కావాలి. నెలకు ₹1,500 చొప్పున, దానికి 15,000 ÷ 1,500 = 10 నెలలు పడుతుంది."}}'::jsonb, null,null,'live','ai'),
  ('save-inflation-007','save', array['inflation','compound-interest'], 'diamond','mcq', '{"en":{"prompt":"A coaching course costs ₹20,000 today. Fees rise 10% every year. What will it cost in 2 years? (Assume exactly 10% a year.)","options":["₹22,000","₹24,000","₹24,200","₹40,000"],"answer":"C","explanation":"After 1 year: ₹20,000 + ₹2,000 = ₹22,000. After 2 years: ₹22,000 + ₹2,200 = ₹24,200, because each rise is on the new price."},"hi":{"prompt":"एक कोचिंग कोर्स की फ़ीस आज ₹20,000 है। फ़ीस हर साल 10% बढ़ती है। 2 साल बाद यह कितने की होगी? (मान लें हर साल ठीक 10%।)","options":["₹22,000","₹24,000","₹24,200","₹40,000"],"answer":"C","explanation":"1 साल बाद: ₹20,000 + ₹2,000 = ₹22,000। 2 साल बाद: ₹22,000 + ₹2,200 = ₹24,200, क्योंकि हर बढ़त नई कीमत पर होती है।"},"te":{"prompt":"ఒక కోచింగ్ కోర్సు ఫీజు ఈ రోజు ₹20,000. ఫీజు ప్రతి సంవత్సరం 10% పెరుగుతుంది. 2 సంవత్సరాల తర్వాత అది ఎంత అవుతుంది? (సంవత్సరానికి సరిగ్గా 10% అనుకోండి.)","options":["₹22,000","₹24,000","₹24,200","₹40,000"],"answer":"C","explanation":"1 సంవత్సరం తర్వాత: ₹20,000 + ₹2,000 = ₹22,000. 2 సంవత్సరాల తర్వాత: ₹22,000 + ₹2,200 = ₹24,200, ఎందుకంటే ప్రతి పెరుగుదల కొత్త ధర మీద లెక్కిస్తారు."}}'::jsonb, null,'invest-inflation','live','ai'),
  ('save-compound-interest-009','save', array['compound-interest'], 'diamond','mcq', '{"en":{"prompt":"Pooja deposits ₹5,000 now and another ₹5,000 after 1 year, at 10% a year compounded yearly. How much does she have after 2 years? (Assume a fixed rate.)","options":["₹11,000","₹11,500","₹11,550","₹12,100"],"answer":"C","explanation":"The first ₹5,000 grows for 2 years to ₹6,050, and the second grows for 1 year to ₹5,500. Together that is ₹11,550."},"hi":{"prompt":"पूजा अभी ₹5,000 जमा करती है और 1 साल बाद ₹5,000 और, 10% सालाना दर पर, जिसमें ब्याज हर साल कंपाउंड होता है। 2 साल बाद उसके पास कितने होंगे? (मान लें कि दर तय है।)","options":["₹11,000","₹11,500","₹11,550","₹12,100"],"answer":"C","explanation":"पहले ₹5,000 2 साल में बढ़कर ₹6,050 हो जाते हैं, और दूसरे ₹5,000 1 साल में ₹5,500। कुल मिलाकर ₹11,550।"},"te":{"prompt":"పూజ ఇప్పుడు ₹5,000, 1 సంవత్సరం తర్వాత మరో ₹5,000 డిపాజిట్ చేస్తుంది, సంవత్సరానికి 10% రేటుకి, ఏటా కాంపౌండ్ అయ్యేలా. 2 సంవత్సరాల తర్వాత ఆమె దగ్గర ఎంత ఉంటుంది? (రేటు మారదని అనుకోండి.)","options":["₹11,000","₹11,500","₹11,550","₹12,100"],"answer":"C","explanation":"మొదటి ₹5,000 2 సంవత్సరాల్లో ₹6,050 అవుతుంది, రెండో ₹5,000 1 సంవత్సరంలో ₹5,500 అవుతుంది. రెండూ కలిపి ₹11,550."}}'::jsonb, null,null,'live','ai'),
  ('save-bank-accounts-008','save', array['bank-accounts','simple-interest','inflation'], 'diamond','mcq', '{"en":{"prompt":"Asif puts ₹10,000 in an FD at 7% simple interest for 2 years. A ₹10,000 laptop''s price rises 6% each year. After 2 years, can he afford it? (Example rates.)","options":["Yes, with about ₹160 to spare","Yes, with ₹1,400 to spare","No, he is about ₹200 short","No, the laptop then costs ₹12,000"],"answer":"A","explanation":"His FD becomes ₹10,000 + ₹1,400 = ₹11,400, while the laptop becomes ₹10,000 × 1.06 × 1.06 = ₹11,236. He has about ₹164 left over."},"hi":{"prompt":"आसिफ़ ₹10,000 एक FD में 2 साल के लिए 7% साधारण ब्याज पर रखता है। ₹10,000 के एक लैपटॉप की कीमत हर साल 6% बढ़ती है। 2 साल बाद क्या वह इसे खरीद पाएगा? (ये उदाहरण की दरें हैं।)","options":["हाँ, लगभग ₹160 बचेंगे","हाँ, ₹1,400 बचेंगे","नहीं, उसके पास लगभग ₹200 कम होंगे","नहीं, तब लैपटॉप ₹12,000 का होगा"],"answer":"A","explanation":"उसकी FD ₹10,000 + ₹1,400 = ₹11,400 हो जाती है, जबकि लैपटॉप ₹10,000 × 1.06 × 1.06 = ₹11,236 का हो जाता है। उसके पास लगभग ₹164 बचते हैं।"},"te":{"prompt":"ఆసిఫ్ ₹10,000ని 7% సాధారణ వడ్డీకి 2 సంవత్సరాలు FDలో వేశాడు. ₹10,000 ల్యాప్‌టాప్ ధర ప్రతి సంవత్సరం 6% పెరుగుతుంది. 2 సంవత్సరాల తర్వాత అతను దాన్ని కొనగలడా? (ఇవి ఉదాహరణ రేట్లు.)","options":["అవును, సుమారు ₹160 మిగులుతాయి","అవును, ₹1,400 మిగులుతాయి","లేదు, సుమారు ₹200 తక్కువ పడతాయి","లేదు, అప్పటికి ల్యాప్‌టాప్ ₹12,000 అవుతుంది"],"answer":"A","explanation":"అతని FD ₹10,000 + ₹1,400 = ₹11,400 అవుతుంది, ల్యాప్‌టాప్ ధర ₹10,000 × 1.06 × 1.06 = ₹11,236 అవుతుంది. అతని దగ్గర సుమారు ₹164 మిగులుతాయి."}}'::jsonb, null,null,'live','ai')
